        .flat_map(|line| line.split_whitespace())
        .next()
        .unwrap_or("0")
        .parse()
        .unwrap();

    let n = nums.len();
    let mut suffix_or = vec![0u64; n + 1];

    for i in (0..n).rev() {
        suffix_or[i] = suffix_or[i + 1] | nums[i];
    }

    let mut prefix_or = 0u64;
    let mut answer = 0u64;

    for i in 0..n {
        answer = answer.max(prefix_or | (nums[i] << k) | suffix_or[i + 1]);
        prefix_or |= nums[i];
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
