    let dictionary: Vec<Vec<u8>> = tokens.map(|word| word.as_bytes().to_vec()).collect();

    let n = s.len();
    let mut dp = vec![usize::MAX; n + 1];
    dp[0] = 0;

    for i in 0..n {
        dp[i + 1] = dp[i + 1].min(dp[i] + 1);

        for word in &dictionary {
            let end = i + word.len();
            if end <= n && s[i..end] == word[..] {
                dp[end] = dp[end].min(dp[i]);
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
