use std::io::{self, Read, Write};

const MOD: i64 = 1_000_000_007;

fn decrement(num: &str) -> String {
    let mut digits = num.as_bytes().to_vec();
    let mut i = digits.len();

    while i > 0 {
        i -= 1;
        if digits[i] > b'0' {
            digits[i] -= 1;
            break;
        }
        digits[i] = b'9';
    }

    String::from_utf8(digits).unwrap()
}

fn count_at_most(bound: &str, min_sum: usize, max_sum: usize) -> i64 {
    let mut dp = vec![vec![0i64; max_sum + 1]; 2];
    dp[1][0] = 1;

    for &ch in bound.as_bytes() {
        let bound_digit = (ch - b'0') as usize;
        let mut next = vec![vec![0i64; max_sum + 1]; 2];

        for tight in 0..=1 {
            let limit = if tight == 1 { bound_digit } else { 9 };

            for sum in 0..=max_sum {
                let ways = dp[tight][sum];
                if ways == 0 {
                    continue;
                }

                for digit in 0..=limit {
                    let new_sum = sum + digit;
                    if new_sum > max_sum {
                        break;
                    }

                    let new_tight = if tight == 1 && digit == bound_digit {
                        1
                    } else {
                        0
                    };

                    next[new_tight][new_sum] += ways;
                    if next[new_tight][new_sum] >= MOD {
                        next[new_tight][new_sum] -= MOD;
                    }
                }
            }
        }

        dp = next;
    }

    let mut result = 0i64;
    for sum in min_sum..=max_sum {
        result += dp[0][sum] + dp[1][sum];
        result %= MOD;
    }
    result
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let num1 = iter.next().unwrap();
    let num2 = iter.next().unwrap();
    let min_sum: usize = iter.next().unwrap().parse().unwrap();
    let max_sum: usize = iter.next().unwrap().parse().unwrap();

    let before_num1 = decrement(num1);
    let upper_count = count_at_most(num2, min_sum, max_sum);
    let lower_count = count_at_most(&before_num1, min_sum, max_sum);

    let answer = (upper_count - lower_count + MOD) % MOD;

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
