    let n = nums.len();
    let pos_one = nums.iter().position(|&x| x == 1).unwrap();
    let pos_n = nums.iter().position(|&x| x == n).unwrap();

    let mut operations = pos_one + (n - 1 - pos_n);
    if pos_one > pos_n {
        operations -= 1;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{operations}").unwrap();
}
