use std::io::{self, Read, Write};

fn can_partition(
    digits: &[u8],
    pos: usize,
    remaining: usize,
    memo: &mut [Vec<i8>],
) -> bool {
    if pos == digits.len() {
        return remaining == 0;
    }

    if memo[pos][remaining] != -1 {
        return memo[pos][remaining] == 1;
    }

    let mut value = 0usize;

    for end in pos..digits.len() {
        value = value * 10 + (digits[end] - b'0') as usize;

        if value > remaining {
            break;
        }

        if can_partition(digits, end + 1, remaining - value, memo) {
            memo[pos][remaining] = 1;
            return true;
        }
    }

    memo[pos][remaining] = 0;
    false
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let n: usize = input
        .split_whitespace()
        .find_map(|token| token.parse().ok())
        .unwrap();

    let mut answer = 0u64;

    for i in 1..=n {
        let square = i * i;
        let square_string = square.to_string();
        let digits = square_string.as_bytes();
        let mut memo = vec![vec![-1i8; i + 1]; digits.len()];

        if can_partition(digits, 0, i, &mut memo) {
            answer += square as u64;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
