use std::io::{self, Read, Write};

fn parse_numbers(line: &str) -> Vec<i64> {
    line.split(|c: char| !c.is_ascii_digit() && c != '-')
        .filter(|s| !s.is_empty())
        .filter_map(|s| s.parse::<i64>().ok())
        .collect()
}

fn lower_bound(values: &[i64], target: i64) -> usize {
    let mut left = 0;
    let mut right = values.len();
    while left < right {
        let mid = left + (right - left) / 2;
        if values[mid] < target {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    left
}

struct FenwickMax {
    tree: Vec<i64>,
}

impl FenwickMax {
    fn new(size: usize) -> Self {
        Self {
            tree: vec![-1; size + 1],
        }
    }

    fn update(&mut self, mut index: usize, value: i64) {
        while index < self.tree.len() {
            self.tree[index] = self.tree[index].max(value);
            index += index & index.wrapping_neg();
        }
    }

    fn query(&self, mut index: usize) -> i64 {
        let mut result = -1;
        while index > 0 {
            result = result.max(self.tree[index]);
            index -= index & index.wrapping_neg();
        }
        result
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let lines: Vec<&str> = input.lines().filter(|line| !line.trim().is_empty()).collect();
    if lines.len() < 3 {
        return;
    }

    let nums1 = parse_numbers(lines[0]);
    let nums2 = parse_numbers(lines[1]);
    let query_count = parse_numbers(lines[2])
        .first()
        .copied()
        .unwrap_or(0) as usize;

    let n = nums1.len().min(nums2.len());
    let mut points: Vec<(i64, i64)> = (0..n)
        .map(|i| (nums1[i], nums2[i]))
        .collect();
    points.sort_unstable_by(|a, b| b.0.cmp(&a.0));

    let mut queries = Vec::with_capacity(query_count);
    for i in 0..query_count {
        let values = parse_numbers(lines[3 + i]);
        queries.push((values[0], values[1], i));
    }
    queries.sort_unstable_by(|a, b| b.0.cmp(&a.0));

    let mut ys: Vec<i64> = nums2[..n].to_vec();
    ys.sort_unstable();
    ys.dedup();

    let mut fenwick = FenwickMax::new(ys.len());
    let mut answers = vec![-1_i64; query_count];
    let mut point_index = 0;

    for (x, y, original_index) in queries {
        while point_index < points.len() && points[point_index].0 >= x {
            let (a, b) = points[point_index];
            let position = lower_bound(&ys, b);
            let reversed_index = ys.len() - position;
            fenwick.update(reversed_index, a + b);
            point_index += 1;
        }

        let position = lower_bound(&ys, y);
        if position < ys.len() {
            answers[original_index] = fenwick.query(ys.len() - position);
        }
    }

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    for (i, answer) in answers.iter().enumerate() {
        if i > 0 {
            write!(output, " ").unwrap();
        }
        write!(output, "{answer}").unwrap();
    }
    writeln!(output).unwrap();
}
