use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace().map(|s| s.parse::<usize>().unwrap());

    let x = values.next().unwrap();
    let y = values.next().unwrap();
    let z = values.next().unwrap();

    // States:
    // 0 = empty
    // 1 = ends with one A
    // 2 = ends with two A's
    // 3 = ends with one B
    // 4 = ends with two B's
    let ys = y + 1;
    let zs = z + 1;
    let index = |i: usize, j: usize, k: usize, state: usize| {
        (((i * ys + j) * zs + k) * 5) + state
    };

    let mut reachable = vec![false; (x + 1) * (y + 1) * (z + 1) * 5];
    reachable[index(0, 0, 0, 0)] = true;

    let mut max_blocks = 0;

    for i in 0..=x {
        for j in 0..=y {
            for k in 0..=z {
                for state in 0..5 {
                    if !reachable[index(i, j, k, state)] {
                        continue;
                    }

                    max_blocks = max_blocks.max(i + j + k);

                    // Append "AA": valid only if the current string does not end in A.
                    if i < x && state != 1 && state != 2 {
                        reachable[index(i + 1, j, k, 2)] = true;
                    }

                    // Append "BB": valid only if the current string does not end in B.
                    if j < y && state != 3 && state != 4 {
                        reachable[index(i, j + 1, k, 4)] = true;
                    }

                    // Append "AB": invalid only when the current string ends in "AA".
                    if k < z && state != 2 {
                        reachable[index(i, j, k + 1, 3)] = true;
                    }
                }
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", max_blocks * 2).unwrap();
}
