use std::io::{self, Read, Write};

fn count_at_most(nums: &[usize], limit: usize) -> i64 {
    if limit == 0 {
        return 0;
    }

    let max_value = nums.iter().copied().max().unwrap_or(0);
    let mut frequency = vec![0usize; max_value + 1];
    let mut left = 0usize;
    let mut distinct = 0usize;
    let mut count = 0i64;

    for right in 0..nums.len() {
        let value = nums[right];
        if frequency[value] == 0 {
            distinct += 1;
        }
        frequency[value] += 1;

        while distinct > limit {
            let left_value = nums[left];
            frequency[left_value] -= 1;
            if frequency[left_value] == 0 {
                distinct -= 1;
            }
            left += 1;
        }

        count += (right - left + 1) as i64;
    }

    count
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let nums: Vec<usize> = input
        .split_whitespace()
        .filter_map(|token| token.parse().ok())
        .collect();

    if nums.is_empty() {
        return;
    }

    let max_value = nums.iter().copied().max().unwrap();
    let mut seen = vec![false; max_value + 1];
    let mut total_distinct = 0usize;

    for &value in &nums {
        if !seen[value] {
            seen[value] = true;
            total_distinct += 1;
        }
    }

    let answer =
        count_at_most(&nums, total_distinct) - count_at_most(&nums, total_distinct - 1);

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    writeln!(output, "{answer}").unwrap();
}
