fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let nums: Vec<i64> = input
        .split_whitespace()
        .filter_map(|s| s.parse::<i64>().ok())
        .collect();

    let mut min_queue: VecDeque<usize> = VecDeque::new();
    let mut max_queue: VecDeque<usize> = VecDeque::new();
    let mut left = 0usize;
    let mut answer = 0i64;

    for right in 0..nums.len() {
        while let Some(&idx) = min_queue.back() {
            if nums[idx] >= nums[right] {
                min_queue.pop_back();
            } else {
                break;
            }
        }
        min_queue.push_back(right);

        while let Some(&idx) = max_queue.back() {
            if nums[idx] <= nums[right] {
                max_queue.pop_back();
            } else {
                break;
            }
        }
        max_queue.push_back(right);

        while nums[*max_queue.front().unwrap()] - nums[*min_queue.front().unwrap()] > 2 {
            if min_queue.front() == Some(&left) {
                min_queue.pop_front();
            }
            if max_queue.front() == Some(&left) {
                max_queue.pop_front();
            }
            left += 1;
        }

        answer += (right - left + 1) as i64;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
