        .map(|s| s.parse::<i64>().unwrap())
        .collect();

    let mut output = io::BufWriter::new(io::stdout().lock());

    if values.len() < 2 {
        writeln!(output, "false").unwrap();
        return;
    }

    let k = values[values.len() - 1] as usize;
    let nums = &values[..values.len() - 1];
    let n = nums.len();

    if k == 0 || k > n {
        writeln!(output, "false").unwrap();
        return;
    }

    let mut expirations = vec![0i64; n + 1];
    let mut active = 0i64;
    let mut possible = true;

    for i in 0..n {
        active += expirations[i];
        let remaining = nums[i] - active;

        if remaining < 0 {
            possible = false;
            break;
        }

        if remaining > 0 {
            if i + k > n {
                possible = false;
                break;
            }
            active += remaining;
            expirations[i + k] -= remaining;
        }
    }

    writeln!(output, "{}", possible).unwrap();
}
