use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let s = iter.next().unwrap().as_bytes();
    let k: usize = iter.next().unwrap().parse().unwrap();
    let n = s.len();

    // cost[left][right] is the minimum changes needed to make
    // s[left..right] a semi-palindrome.
    let mut cost = vec![vec![usize::MAX; n + 1]; n];

    for left in 0..n {
        for right in left + 2..=n {
            let len = right - left;
            let mut best = usize::MAX;

            for d in 1..len {
                if len % d != 0 {
                    continue;
                }

                let group_len = len / d;
                let mut changes = 0;

                for remainder in 0..d {
                    for t in 0..group_len / 2 {
                        let a = left + remainder + t * d;
                        let b = left + remainder + (group_len - 1 - t) * d;
                        if s[a] != s[b] {
                            changes += 1;
                        }
                    }
                }

                best = best.min(changes);
            }

            cost[left][right] = best;
        }
    }

    let inf = usize::MAX / 4;
    let mut dp = vec![vec![inf; n + 1]; k + 1];
    dp[0][0] = 0;

    for parts in 1..=k {
        for end in 2 * parts..=n {
            for start in 2 * (parts - 1)..=end - 2 {
                if dp[parts - 1][start] != inf {
                    dp[parts][end] =
                        dp[parts][end].min(dp[parts - 1][start] + cost[start][end]);
                }
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", dp[k][n]).unwrap();
}
