use std::collections::HashSet;
use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();

    let word = match tokens.next() {
        Some(s) => s.as_bytes().to_vec(),
        None => return,
    };

    let remaining: Vec<&str> = tokens.collect();
    let start = if remaining.first().is_some_and(|s| s.bytes().all(|b| b.is_ascii_digit())) {
        1
    } else {
        0
    };

    let mut forbidden: HashSet<Vec<u8>> = HashSet::with_capacity(remaining.len());
    let mut max_forbidden_len = 0usize;

    for s in remaining.iter().skip(start) {
        let bytes = s.as_bytes().to_vec();
        max_forbidden_len = max_forbidden_len.max(bytes.len());
        forbidden.insert(bytes);
    }

    let mut left = 0usize;
    let mut answer = 0usize;

    for right in 0..word.len() {
        let max_len = max_forbidden_len.min(right + 1);

        for len in 1..=max_len {
            let begin = right + 1 - len;
            if begin < left {
                break;
            }
            if forbidden.contains(&word[begin..=right]) {
                left = begin + 1;
                break;
            }
        }

        answer = answer.max(right + 1 - left);
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
