        let different = best[1 - parity] - x;
        let current = same.max(different) + value;
        best[parity] = best[parity].max(current);
    }

    let answer = best[0].max(best[1]);
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
