    let mut groups = 0_i64;

    for limit in limits {
        available += limit;
        let required = groups + 1;

        if available >= required {
            available -= required;
            groups += 1;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{groups}").unwrap();
