use std::io::{self, Read, Write};

const MOD: i64 = 1_000_000_007;

fn count_leq(bound: &str) -> i64 {
    // prev == 10 means that the number has not started yet.
    let mut dp = [[0i64; 2]; 11];
    dp[10][1] = 1;

    for &byte in bound.as_bytes() {
        let bound_digit = (byte - b'0') as usize;
        let mut next = [[0i64; 2]; 11];

        for prev in 0..=10 {
            for tight in 0..=1 {
                let ways = dp[prev][tight];
                if ways == 0 {
                    continue;
                }

                let limit = if tight == 1 { bound_digit } else { 9 };

                for digit in 0..=limit {
                    let new_tight = if tight == 1 && digit == bound_digit {
                        1
                    } else {
                        0
                    };

                    let new_prev = if prev == 10 {
                        if digit == 0 {
                            10
                        } else {
                            digit
                        }
                    } else {
                        let difference = if prev > digit {
                            prev - digit
                        } else {
                            digit - prev
                        };
                        if difference != 1 {
                            continue;
                        }
                        digit
                    };

                    next[new_prev][new_tight] =
                        (next[new_prev][new_tight] + ways) % MOD;
                }
            }
        }

        dp = next;
    }

    let mut result = 0i64;
    for prev in 0..10 {
        result = (result + dp[prev][0] + dp[prev][1]) % MOD;
    }
    result
}

fn is_stepping(number: &str) -> bool {
    let digits = number.as_bytes();
    for i in 1..digits.len() {
        if (digits[i] as i32 - digits[i - 1] as i32).abs() != 1 {
            return false;
        }
    }
    true
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();

    let low = tokens.next().unwrap();
    let high = tokens.next().unwrap();

    let mut answer = count_leq(high) - count_leq(low);
    if is_stepping(low) {
        answer += 1;
    }
    answer = (answer % MOD + MOD) % MOD;

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    writeln!(output, "{}", answer).unwrap();
}
