fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let heights: Vec<i64> = input
        .split_whitespace()
        .map(|s| s.parse().unwrap())
        .collect();

    let n = heights.len();
    if n == 0 {
        return;
    }

    let mut left = vec![0_i64; n];
    let mut stack: Vec<usize> = Vec::new();

    for i in 0..n {
        while let Some(&j) = stack.last() {
            if heights[j] > heights[i] {
                stack.pop();
            } else {
                break;
            }
        }

        left[i] = if let Some(&j) = stack.last() {
            left[j] + heights[i] * (i - j) as i64
        } else {
            heights[i] * (i + 1) as i64
        };

        stack.push(i);
    }

    let mut right = vec![0_i64; n];
    stack.clear();

    for i in (0..n).rev() {
        while let Some(&j) = stack.last() {
            if heights[j] > heights[i] {
                stack.pop();
            } else {
                break;
            }
        }

        right[i] = if let Some(&j) = stack.last() {
            right[j] + heights[i] * (j - i) as i64
        } else {
            heights[i] * (n - i) as i64
        };

        stack.push(i);
    }

    let answer = (0..n)
        .map(|i| left[i] + right[i] - heights[i])
        .max()
        .unwrap();

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
