use std::io::{self, Read, Write};

struct Fenwick {
    tree: Vec<i64>,
}

impl Fenwick {
    fn new(n: usize) -> Self {
        Self { tree: vec![0; n + 1] }
    }

    fn update(&mut self, mut index: usize, value: i64) {
        while index < self.tree.len() {
            self.tree[index] = self.tree[index].max(value);
            index += index & (!index + 1);
        }
    }

    fn query(&self, mut index: usize) -> i64 {
        let mut result = 0;
        while index > 0 {
            result = result.max(self.tree[index]);
            index &= index - 1;
        }
        result
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let nums: Vec<i64> = input
        .split_whitespace()
        .map(|s| s.parse().unwrap())
        .collect();

    if nums.is_empty() {
        return;
    }

    let keys: Vec<i64> = nums
        .iter()
        .enumerate()
        .map(|(i, &value)| value - i as i64)
        .collect();

    let mut sorted_keys = keys.clone();
    sorted_keys.sort_unstable();
    sorted_keys.dedup();

    let mut fenwick = Fenwick::new(sorted_keys.len());
    let mut answer = i64::MIN;

    for (i, &value) in nums.iter().enumerate() {
        let rank = sorted_keys.binary_search(&keys[i]).unwrap() + 1;
        let best_previous = fenwick.query(rank);
        let current = value + best_previous;

        answer = answer.max(current);
        fenwick.update(rank, current);
    }

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    writeln!(output, "{answer}").unwrap();
}
