        if x >= 2 {
            x * (x - 1) / 2
        } else {
            0
        }
    };

    let answer = choose_two(n + 2)
        - 3 * choose_two(n - limit + 1)
        + 3 * choose_two(n - 2 * limit)
        - choose_two(n - 3 * limit - 1);

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
