fn main() {
    const MOD: i64 = 1_000_000_007;

    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let n: usize = input
        .split_whitespace()
        .find_map(|s| s.parse().ok())
        .unwrap();

    // dp[e][l][t], with each count capped at its required amount.
    let mut dp = [[[0_i64; 2]; 2]; 3];
    dp[0][0][0] = 1;

    for _ in 0..n {
        let mut next = [[[0_i64; 2]; 2]; 3];

        for e in 0..3 {
            for l in 0..2 {
                for t in 0..2 {
                    let value = dp[e][l][t];
                    if value == 0 {
                        continue;
                    }

                    // Any of the other 23 lowercase letters.
                    next[e][l][t] = (next[e][l][t] + value * 23) % MOD;

                    // Add 'e'.
                    let ne = (e + 1).min(2);
                    next[ne][l][t] = (next[ne][l][t] + value) % MOD;

                    // Add 'l'.
                    next[e][1][t] = (next[e][1][t] + value) % MOD;

                    // Add 't'.
                    next[e][l][1] = (next[e][l][1] + value) % MOD;
                }
            }
        }

        dp = next;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", dp[2][1][1]).unwrap();
}
