use std::io::{self, Read, Write};

fn count(prefix: &[[i32; 26]], left: usize, right: usize, ch: usize) -> i32 {
    prefix[right + 1][ch] - prefix[left][ch]
}

fn mismatch_count(prefix: &[i32], left: usize, right: usize) -> i32 {
    prefix[right + 1] - prefix[left]
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();

    let s = tokens.next().unwrap().as_bytes();
    let n = s.len();
    let half = n / 2;

    // Compare the first half with the reversed second half.
    let mut first_prefix = vec![[0i32; 26]; half + 1];
    let mut second_prefix = vec![[0i32; 26]; half + 1];
    let mut mismatch_prefix = vec![0i32; half + 1];

    for i in 0..half {
        let first_char = (s[i] - b'a') as usize;
        let second_char = (s[n - 1 - i] - b'a') as usize;

        first_prefix[i + 1] = first_prefix[i];
        second_prefix[i + 1] = second_prefix[i];

        first_prefix[i + 1][first_char] += 1;
        second_prefix[i + 1][second_char] += 1;

        mismatch_prefix[i + 1] =
            mismatch_prefix[i] + if first_char != second_char { 1 } else { 0 };
    }

    let query_count: usize = tokens.next().unwrap().parse().unwrap();
    let total_mismatches = mismatch_prefix[half];

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for query_index in 0..query_count {
        let a: usize = tokens.next().unwrap().parse().unwrap();
        let b: usize = tokens.next().unwrap().parse().unwrap();
        let c: usize = tokens.next().unwrap().parse().unwrap();
        let d: usize = tokens.next().unwrap().parse().unwrap();

        // Map the second-half interval into reversed-second-half coordinates.
        let left_b = n - 1 - d;
        let right_b = n - 1 - c;

        let intersection_left = a.max(left_b);
        let intersection_right = b.min(right_b);
        let has_intersection = intersection_left <= intersection_right;

        let mut mismatches_in_union =
            mismatch_count(&mismatch_prefix, a, b)
                + mismatch_count(&mismatch_prefix, left_b, right_b);

        if has_intersection {
            mismatches_in_union -= mismatch_count(
                &mismatch_prefix,
                intersection_left,
                intersection_right,
            );
        }

        let mut possible = mismatches_in_union == total_mismatches;

        if possible {
            for ch in 0..26 {
                let first_in_a = count(&first_prefix, a, b, ch);
                let second_in_b = count(&second_prefix, left_b, right_b, ch);

                let second_in_a = count(&second_prefix, a, b, ch);
                let first_in_b = count(&first_prefix, left_b, right_b, ch);

                let (second_in_intersection, first_in_intersection) =
                    if has_intersection {
                        (
                            count(
                                &second_prefix,
                                intersection_left,
                                intersection_right,
                                ch,
                            ),
                            count(
                                &first_prefix,
                                intersection_left,
                                intersection_right,
                                ch,
                            ),
                        )
                    } else {
                        (0, 0)
                    };

                // Characters required in A \ B and B \ A are fixed by the
                // opposite half. Remaining characters must match in A ∩ B.
                let remaining_first =
                    first_in_a - (second_in_a - second_in_intersection);
                let remaining_second =
                    second_in_b - (first_in_b - first_in_intersection);

                if remaining_first < 0
                    || remaining_second < 0
                    || remaining_first != remaining_second
                {
                    possible = false;
                    break;
                }
            }
        }

        if query_index > 0 {
            write!(out, " ").unwrap();
        }
        write!(out, "{}", if possible { "true" } else { "false" }).unwrap();
    }

    writeln!(out).unwrap();
}
