use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let nums: Vec<i64> = input
        .split_whitespace()
        .filter_map(|s| s.parse::<i64>().ok())
        .collect();

    let n = nums.len();
    if n == 0 {
        println!("0");
        return;
    }

    let mut prefix = vec![0_i64; n + 1];
    for i in 0..n {
        prefix[i + 1] = prefix[i] + nums[i];
    }

    let mut dp = vec![0_usize; n + 1];
    let mut predecessor = vec![0_usize; n + 1];
    let mut threshold = vec![0_i64; n + 1];

    let mut queue = Vec::with_capacity(n + 1);
    queue.push(0_usize);
    let mut head = 0_usize;

    for i in 1..=n {
        while head + 1 < queue.len()
            && threshold[queue[head + 1]] <= prefix[i]
        {
            head += 1;
        }

        predecessor[i] = queue[head];
        dp[i] = dp[predecessor[i]] + 1;
        threshold[i] = 2 * prefix[i] - prefix[predecessor[i]];

        while queue.len() > head
            && threshold[*queue.last().unwrap()] >= threshold[i]
        {
            queue.pop();
        }
        queue.push(i);
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", dp[n]).unwrap();
}
