fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut values: Vec<i64> = input
        .split_whitespace()
        .map(|s| s.parse::<i64>().unwrap())
        .collect();

    if values.len() < 2 {
        return;
    }

    let limit = values.pop().unwrap();
    let nums = values;
    let n = nums.len();

    let mut sorted: Vec<(i64, usize)> = nums
        .iter()
        .enumerate()
        .map(|(index, &value)| (value, index))
        .collect();
    sorted.sort_unstable();

    let mut answer = vec![0i64; n];
    let mut start = 0;

    while start < n {
        let mut end = start + 1;
        while end < n && sorted[end].0 - sorted[end - 1].0 <= limit {
            end += 1;
        }

        let mut indices: Vec<usize> = sorted[start..end]
            .iter()
            .map(|&(_, index)| index)
            .collect();
        indices.sort_unstable();

        for (offset, &index) in indices.iter().enumerate() {
            answer[index] = sorted[start + offset].0;
        }

        start = end;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for (i, value) in answer.iter().enumerate() {
        if i > 0 {
            write!(out, " ").unwrap();
        }
        write!(out, "{value}").unwrap();
    }
    writeln!(out).unwrap();
}
