use std::io::{self, Read, Write};

const MOD: i64 = 1_000_000_007;

fn mod_pow(mut base: i64, mut exp: usize) -> i64 {
    let mut result = 1i64;
    while exp > 0 {
        if exp & 1 == 1 {
            result = result * base % MOD;
        }
        base = base * base % MOD;
        exp >>= 1;
    }
    result
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace().map(|s| s.parse::<usize>().unwrap());

    let n = values.next().unwrap();
    let sick: Vec<usize> = values.collect();

    let healthy = n - sick.len();

    let mut factorial = vec![1i64; healthy + 1];
    for i in 1..=healthy {
        factorial[i] = factorial[i - 1] * i as i64 % MOD;
    }

    let mut answer = factorial[healthy];

    let left_gap = sick[0];
    answer = answer * mod_pow(factorial[left_gap], MOD as usize - 2) % MOD;

    for pair in sick.windows(2) {
        let gap = pair[1] - pair[0] - 1;
        answer = answer * mod_pow(factorial[gap], MOD as usize - 2) % MOD;
        if gap > 0 {
            answer = answer * mod_pow(2, gap - 1) % MOD;
        }
    }

    let right_gap = n - 1 - sick[sick.len() - 1];
    answer = answer * mod_pow(factorial[right_gap], MOD as usize - 2) % MOD;

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
