    let mut lines = input.lines().filter(|line| !line.trim().is_empty());
    let nums_line = lines.next().unwrap_or("");
    let nums: Vec<i64> = nums_line
        .split_whitespace()
        .filter_map(|s| s.parse().ok())
        .collect();

    let k: usize = lines
        .flat_map(|line| line.split_whitespace())
        .next()
        .and_then(|s| s.parse().ok())
        .unwrap_or(0);

    let mut frequencies: HashMap<i64, usize> = HashMap::new();
    let mut left = 0usize;
    let mut longest = 0usize;

    for right in 0..nums.len() {
        *frequencies.entry(nums[right]).or_insert(0) += 1;

        while frequencies.get(&nums[right]).copied().unwrap_or(0) > k {
            if let Some(count) = frequencies.get_mut(&nums[left]) {
                *count -= 1;
            }
            left += 1;
        }

        longest = longest.max(right - left + 1);
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{longest}").unwrap();
