    let mut dp = [0usize; 26];
    for c in 0..26 {
        dp[c] = usize::from(c != (bytes[0] - b'a') as usize);
    }

    for &byte in &bytes[1..] {
        let original = (byte - b'a') as usize;
        let mut next = [usize::MAX; 26];

        for current in 0..26 {
            let change_cost = usize::from(current != original);
            for previous in 0..26 {
                if current.abs_diff(previous) > 1 {
                    next[current] = next[current].min(dp[previous] + change_cost);
                }
            }
        }

        dp = next;
    }

    let answer = *dp.iter().min().unwrap();
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
