    index: usize,
    mask: u32,
    can_change: bool,
    s: &[u8],
    k: u32,
    memo: &mut HashMap<u64, i32>,
) -> i32 {
    if index == s.len() {
        return 0;
    }

    let key = ((index as u64) << 27) | ((mask as u64) << 1) | can_change as u64;
    if let Some(&result) = memo.get(&key) {
        return result;
    }

    let original = (s[index] - b'a') as u32;
    let original_bit = 1u32 << original;
    let combined = mask | original_bit;

    let mut best = if combined.count_ones() > k {
        1 + dfs(index + 1, original_bit, can_change, s, k, memo)
    } else {
        dfs(index + 1, combined, can_change, s, k, memo)
    };

    if can_change {
        let mut seen_masks = [0u32; 26];
        let mut seen_splits = [false; 26];
        let mut seen_len = 0usize;

        for replacement in 0..26u32 {
            if replacement == original {
                continue;
            }

            let bit = 1u32 << replacement;
            let new_combined = mask | bit;
            let (next_mask, split) = if new_combined.count_ones() > k {
                (bit, true)
            } else {
                (new_combined, false)
            };

            let mut duplicate = false;
            for j in 0..seen_len {
                if seen_masks[j] == next_mask && seen_splits[j] == split {
                    duplicate = true;
                    break;
                }
            }
            if duplicate {
                continue;
            }

            seen_masks[seen_len] = next_mask;
            seen_splits[seen_len] = split;
            seen_len += 1;

            let value = if split {
                1 + dfs(index + 1, next_mask, false, s, k, memo)
            } else {
                dfs(index + 1, next_mask, false, s, k, memo)
            };
            best = best.max(value);
        }
    }

    memo.insert(key, best);
    best
}

fn solve(s: Vec<u8>, k: u32) -> i32 {
    if k == 26 {
        return 1;
    }

    let mut memo = HashMap::with_capacity(s.len().saturating_mul(16));
    1 + dfs(0, 0, true, &s, k, &mut memo)
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();

    let s = tokens.next().unwrap().as_bytes().to_vec();
    let k: u32 = tokens.next().unwrap().parse().unwrap();

    let answer = std::thread::Builder::new()
        .stack_size(64 * 1024 * 1024)
        .spawn(move || solve(s, k))
        .unwrap()
        .join()
        .unwrap();

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
