use std::io::{self, Read, Write};

fn feasible(nums: &[u32], forbidden: u32, required_groups: usize) -> bool {
    let mut groups = 0usize;
    let mut current = (1u32 << 30) - 1;

    for &value in nums {
        current &= value;
        if current & forbidden == 0 {
            groups += 1;
            current = (1u32 << 30) - 1;
        }
    }

    groups >= required_groups
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut lines = input.lines().filter(|line| !line.trim().is_empty());
    let nums_line = lines.next().unwrap_or("");
    let k_line = lines.next().unwrap_or("0");

    let nums: Vec<u32> = nums_line
        .split_whitespace()
        .map(|s| s.parse::<u32>().unwrap())
        .collect();
    let k: usize = k_line
        .split_whitespace()
        .next()
        .unwrap_or("0")
        .parse()
        .unwrap();

    let required_groups = nums.len() - k;
    let mut forbidden = 0u32;
    let mut answer = 0u32;

    for bit in (0..30).rev() {
        let candidate = forbidden | (1u32 << bit);
        if feasible(&nums, candidate, required_groups) {
            forbidden = candidate;
        } else {
            answer |= 1u32 << bit;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
