use std::io::{self, Read, Write};

fn parse_numbers(line: &str) -> Vec<i64> {
    line.split(|c: char| !c.is_ascii_digit() && c != '-')
        .filter(|s| !s.is_empty())
        .filter_map(|s| s.parse::<i64>().ok())
        .collect()
}

fn feasible(nums: &[i64], changes: &[usize], time: usize) -> bool {
    let n = nums.len();
    let mut last = vec![usize::MAX; n];

    for second in 0..time {
        last[changes[second]] = second;
    }

    if last.iter().any(|&second| second == usize::MAX) {
        return false;
    }

    let mut available_seconds: i64 = 0;

    for second in 0..time {
        let index = changes[second];
        if last[index] == second {
            if available_seconds < nums[index] {
                return false;
            }
            available_seconds -= nums[index];
        } else {
            available_seconds += 1;
        }
    }

    true
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut lines = input.lines().filter(|line| !line.trim().is_empty());
    let nums = match lines.next() {
        Some(line) => parse_numbers(line),
        None => return,
    };
    let change_values = match lines.next() {
        Some(line) => parse_numbers(line),
        None => return,
    };

    let changes: Vec<usize> = change_values
        .into_iter()
        .map(|value| (value - 1) as usize)
        .collect();

    let mut left = 1usize;
    let mut right = changes.len();
    let mut answer = -1i64;

    while left <= right {
        let mid = left + (right - left) / 2;

        if feasible(&nums, &changes, mid) {
            answer = mid as i64;
            if mid == 0 {
                break;
            }
            right = mid - 1;
        } else {
            left = mid + 1;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", answer).unwrap();
}
