        if byte.is_ascii_digit() {
            current = current * 10 + (byte - b'0') as u64;
            reading = true;
        } else if reading {
            nums.push(current);
            current = 0;
            reading = false;
        }
    }
    if reading {
        nums.push(current);
    }

    let mut counts: HashMap<u64, usize> = HashMap::new();
    for value in nums {
        *counts.entry(value).or_insert(0) += 1;
    }

    let mut answer = 1usize;

    if let Some(&ones) = counts.get(&1) {
        let usable = if ones % 2 == 1 { ones } else { ones - 1 };
        answer = answer.max(usable);
    }

    let values: Vec<u64> = counts.keys().copied().filter(|&x| x > 1).collect();

    for mut value in values {
        let mut length = 0usize;

        while counts.get(&value).copied().unwrap_or(0) >= 2 {
            length += 2;
            value *= value;
        }

        if counts.get(&value).copied().unwrap_or(0) >= 1 {
            length += 1;
        } else if length > 0 {
            length -= 1;
        }

        answer = answer.max(length);
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
