fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let values: Vec<i64> = input
        .split_whitespace()
        .map(|s| s.parse::<i64>().unwrap())
        .collect();

    if values.len() < 2 {
        return;
    }

    let k = *values.last().unwrap() as usize;
    let nums = &values[..values.len() - 1];

    const NEG_INF: i64 = i64::MIN / 4;

    let mut best = vec![NEG_INF; k + 1];
    let mut ending = vec![NEG_INF; k + 1];
    best[0] = 0;

    for (i, &num) in nums.iter().enumerate() {
        let max_j = k.min(i + 1);

        for j in (1..=max_j).rev() {
            let magnitude = (k - j + 1) as i64;
            let weight = if j % 2 == 1 {
                magnitude
            } else {
                -magnitude
            };
            let contribution = weight * num;

            let extend = if ending[j] == NEG_INF {
                NEG_INF
            } else {
                ending[j] + contribution
            };

            let start = if best[j - 1] == NEG_INF {
                NEG_INF
            } else {
                best[j - 1] + contribution
            };

            ending[j] = extend.max(start);
            best[j] = best[j].max(ending[j]);
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", best[k]).unwrap();
}
