use std::io::{self, Read, Write};

const MOD: i64 = 1_000_000_007;

fn count_subsequences(nums: &[i64], k: usize, min_diff: i64) -> i64 {
    let n = nums.len();

    let mut limit = vec![0usize; n];
    let mut left = 0usize;
    for i in 0..n {
        while left < i && nums[i] - nums[left] >= min_diff {
            left += 1;
        }
        limit[i] = left;
    }

    let mut dp = vec![1i64; n];

    for _len in 2..=k {
        let mut prefix = vec![0i64; n + 1];
        for i in 0..n {
            prefix[i + 1] = (prefix[i] + dp[i]) % MOD;
        }

        let mut next = vec![0i64; n];
        for i in 0..n {
            next[i] = prefix[limit[i]];
        }
        dp = next;
    }

    dp.into_iter().fold(0, |sum, value| (sum + value) % MOD)
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let values: Vec<i64> = input
        .split_whitespace()
        .map(|s| s.parse::<i64>().unwrap())
        .collect();

    if values.len() < 3 {
        return;
    }

    let k = *values.last().unwrap() as usize;
    let mut nums = values[..values.len() - 1].to_vec();
    nums.sort_unstable();

    let n = nums.len();
    let mut differences = Vec::new();

    for i in 0..n {
        for j in i + 1..n {
            let difference = nums[j] - nums[i];
            if difference > 0 {
                differences.push(difference);
            }
        }
    }

    differences.sort_unstable();
    differences.dedup();

    let mut answer = 0i64;
    let mut previous = 0i64;

    for difference in differences {
        let count = count_subsequences(&nums, k, difference);
        let width = (difference - previous) % MOD;
        answer = (answer + width * count) % MOD;
        previous = difference;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
