use std::io::{self, Read, Write};

fn count_subarrays_with_at_most(nums: &[usize], k: usize, max_value: usize) -> i64 {
    let mut frequency = vec![0usize; max_value + 1];
    let mut left = 0usize;
    let mut distinct = 0usize;
    let mut count = 0i64;

    for right in 0..nums.len() {
        let value = nums[right];
        if frequency[value] == 0 {
            distinct += 1;
        }
        frequency[value] += 1;

        while distinct > k {
            let value = nums[left];
            frequency[value] -= 1;
            if frequency[value] == 0 {
                distinct -= 1;
            }
            left += 1;
        }

        count += (right - left + 1) as i64;
    }

    count
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let nums: Vec<usize> = input
        .split(|c: char| !c.is_ascii_digit())
        .filter(|s| !s.is_empty())
        .map(|s| s.parse().unwrap())
        .collect();

    if nums.is_empty() {
        return;
    }

    let n = nums.len() as i64;
    let total_subarrays = n * (n + 1) / 2;
    let median_rank = (total_subarrays + 1) / 2;
    let max_value = *nums.iter().max().unwrap();

    let mut low = 1usize;
    let mut high = nums.len();

    while low < high {
        let mid = low + (high - low) / 2;
        let count = count_subarrays_with_at_most(&nums, mid, max_value);

        if count >= median_rank {
            high = mid;
        } else {
            low = mid + 1;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{low}").unwrap();
}
