use std::io::{self, Read, Write};

fn gcd(mut a: u64, mut b: u64) -> u64 {
    while b != 0 {
        let r = a % b;
        a = b;
        b = r;
    }
    a
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let values: Vec<u64> = input
        .split(|c: char| !c.is_ascii_digit())
        .filter(|s| !s.is_empty())
        .map(|s| s.parse::<u64>().unwrap())
        .collect();

    if values.len() < 2 {
        return;
    }

    let k = *values.last().unwrap();
    let mut coins = values[..values.len() - 1].to_vec();
    coins.sort_unstable();

    // A denomination divisible by a smaller one contributes no new amounts.
    let mut reduced = Vec::new();
    for coin in coins {
        if !reduced.iter().any(|&smaller| coin % smaller == 0) {
            reduced.push(coin);
        }
    }
    coins = reduced;

    let n = coins.len();
    let subset_count = 1usize << n;
    let mut lcms = vec![1u64; subset_count];
    let mut signs = vec![0i64; subset_count];

    for mask in 1..subset_count {
        let bit = mask & mask.wrapping_neg();
        let index = bit.trailing_zeros() as usize;
        let previous = mask ^ bit;

        let a = lcms[previous];
        let b = coins[index];
        lcms[mask] = (a / gcd(a, b)) * b;
        signs[mask] = if mask.count_ones() % 2 == 1 { 1 } else { -1 };
    }

    let count_amounts = |limit: u64| -> i64 {
        let mut count = 0i64;
        for mask in 1..subset_count {
            count += signs[mask] * (limit / lcms[mask]) as i64;
        }
        count
    };

    let mut low = 1u64;
    let mut high = coins[0] * k;

    while low < high {
        let mid = low + (high - low) / 2;
        if count_amounts(mid) >= k as i64 {
            high = mid;
        } else {
            low = mid + 1;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{low}").unwrap();
}
