use std::io::{self, Read, Write};

const MOD: i64 = 1_000_000_007;
const NEG_INF: i64 = i64::MIN / 4;

type Matrix = [i64; 4];

fn max_plus_mul(a: Matrix, b: Matrix) -> Matrix {
    let mut result = [NEG_INF; 4];

    for row in 0..2 {
        for col in 0..2 {
            for mid in 0..2 {
                let x = a[row * 2 + mid];
                let y = b[mid * 2 + col];
                if x != NEG_INF && y != NEG_INF {
                    result[row * 2 + col] =
                        result[row * 2 + col].max(x + y);
                }
            }
        }
    }

    result
}

fn combine(left: Matrix, right: Matrix) -> Matrix {
    max_plus_mul(right, left)
}

fn leaf(value: i64) -> Matrix {
    [
        0, 0,
        value, NEG_INF,
    ]
}

fn identity() -> Matrix {
    [
        0, NEG_INF,
        NEG_INF, 0,
    ]
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut lines = input.lines().filter(|line| !line.trim().is_empty());

    let nums_line = match lines.next() {
        Some(line) => line,
        None => return,
    };

    let nums: Vec<i64> = nums_line
        .split_whitespace()
        .map(|s| s.parse().unwrap())
        .collect();

    let remaining = lines.collect::<Vec<_>>().join(" ");
    let mut tokens = remaining.split_whitespace();

    let query_count: usize = tokens.next().unwrap().parse().unwrap();

    let n = nums.len();
    let mut size = 1usize;
    while size < n {
        size *= 2;
    }

    let mut tree = vec![identity(); size * 2];

    for i in 0..n {
        tree[size + i] = leaf(nums[i]);
    }

    for i in (1..size).rev() {
        tree[i] = combine(tree[i * 2], tree[i * 2 + 1]);
    }

    let mut total = 0i64;

    for _ in 0..query_count {
        let pos: usize = tokens.next().unwrap().parse().unwrap();
        let value: i64 = tokens.next().unwrap().parse().unwrap();

        let mut index = size + pos;
        tree[index] = leaf(value);

        index /= 2;
        while index > 0 {
            tree[index] = combine(tree[index * 2], tree[index * 2 + 1]);
            index /= 2;
        }

        let answer = tree[1][0].max(tree[1][2]).max(0);
        total = (total + answer % MOD) % MOD;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", total).unwrap();
}
