use std::io::{self, Read, Write};

struct Fenwick {
    tree: Vec<i32>,
}

impl Fenwick {
    fn new(n: usize) -> Self {
        Self {
            tree: vec![0; n + 1],
        }
    }

    fn add(&mut self, index: usize, delta: i32) {
        let mut i = index + 1;
        while i < self.tree.len() {
            self.tree[i] += delta;
            i += i & i.wrapping_neg();
        }
    }

    // Sum over indices [0, end).
    fn prefix_sum(&self, end: usize) -> i32 {
        let mut i = end;
        let mut sum = 0;
        while i > 0 {
            sum += self.tree[i];
            i -= i & i.wrapping_neg();
        }
        sum
    }

    // Sum over indices [left, right).
    fn range_sum(&self, left: usize, right: usize) -> i32 {
        self.prefix_sum(right) - self.prefix_sum(left)
    }
}

fn is_peak(nums: &[i32], index: usize) -> bool {
    index > 0
        && index + 1 < nums.len()
        && nums[index] > nums[index - 1]
        && nums[index] > nums[index + 1]
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut lines = input.lines().filter(|line| !line.trim().is_empty());

    let Some(nums_line) = lines.next() else {
        return;
    };

    let mut nums: Vec<i32> = nums_line
        .split_whitespace()
        .map(|value| value.parse().unwrap())
        .collect();

    let query_count: usize = lines
        .next()
        .and_then(|line| line.trim().parse().ok())
        .unwrap_or(0);

    let n = nums.len();
    let mut fenwick = Fenwick::new(n);

    for i in 1..n.saturating_sub(1) {
        if is_peak(&nums, i) {
            fenwick.add(i, 1);
        }
    }

    let mut answers = Vec::new();

    for line in lines.take(query_count) {
        let query: Vec<i32> = line
            .split_whitespace()
            .map(|value| value.parse().unwrap())
            .collect();

        if query.len() < 3 {
            continue;
        }

        if query[0] == 1 {
            let left = query[1] as usize;
            let right = query[2] as usize;

            let count = if right <= left + 1 {
                0
            } else {
                fenwick.range_sum(left + 1, right)
            };
            answers.push(count.to_string());
        } else {
            let index = query[1] as usize;
            let value = query[2];

            let start = index.saturating_sub(1);
            let end = (index + 1).min(n - 1);

            let old_states: Vec<(usize, bool)> = (start..=end)
                .map(|i| (i, is_peak(&nums, i)))
                .collect();

            nums[index] = value;

            for (i, old_peak) in old_states {
                let new_peak = is_peak(&nums, i);
                if old_peak != new_peak {
                    fenwick.add(i, if new_peak { 1 } else { -1 });
                }
            }
        }
    }

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    writeln!(output, "{}", answers.join(" ")).unwrap();
}
