use std::io::{self, Read, Write};

fn generate(pos: usize, n: usize, prev_zero: bool, current: &mut String, result: &mut Vec<String>) {
    if pos == n {
        result.push(current.clone());
        return;
    }

    if !prev_zero {
        current.push('0');
        generate(pos + 1, n, true, current, result);
        current.pop();
    }

    current.push('1');
    generate(pos + 1, n, false, current, result);
    current.pop();
}

fn main() {
