use std::io::{self, Read, Write};

fn main() {
    const MOD: i64 = 1_000_000_007;

    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let m: usize = it.next().unwrap().parse().unwrap();

    let mut requirements = vec![None; n + 1];
    for _ in 0..m {
        let end: usize = it.next().unwrap().parse().unwrap();
        let count: usize = it.next().unwrap().parse().unwrap();
        requirements[end + 1] = Some(count);
    }

    let target = requirements[n].unwrap();
    let mut dp = vec![0i64; target + 1];
    dp[0] = 1;

    for len in 1..=n {
        let mut next = vec![0i64; target + 1];
        let mut window = 0i64;

        for inversions in 0..=target {
            window += dp[inversions];
            if window >= MOD {
                window -= MOD;
            }

            if inversions >= len {
                window -= dp[inversions - len];
                if window < 0 {
                    window += MOD;
                }
            }

            next[inversions] = window;
        }

        if let Some(required) = requirements[len] {
            if required <= target {
                let ways = next[required];
                next.fill(0);
                next[required] = ways;
            } else {
                next.fill(0);
            }
        }

        dp = next;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", dp[target]).unwrap();
}
