use std::collections::{HashMap, HashSet};
use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let tokens: Vec<&str> = input.split_whitespace().collect();

    if tokens.is_empty() {
        return;
    }

    let target = tokens[0].as_bytes();
    let split = (1..tokens.len())
        .find(|&i| tokens[i].as_bytes()[0].is_ascii_digit())
        .unwrap_or(tokens.len());

    let words = &tokens[1..split];
    let cost_tokens = &tokens[split..];

    let base: u64 = 911_382_323;
    let mut dictionary: HashMap<(usize, u64), Vec<(Vec<u8>, i64)>> = HashMap::new();
    let mut length_set = HashSet::new();

    for (word, cost_str) in words.iter().zip(cost_tokens.iter()) {
        let bytes = word.as_bytes();
        let cost: i64 = cost_str.parse().unwrap();

        let mut hash = 0u64;
        for &ch in bytes {
            hash = hash
                .wrapping_mul(base)
                .wrapping_add((ch - b'a' + 1) as u64);
        }

        let bucket = dictionary.entry((bytes.len(), hash)).or_default();
        if let Some((_, existing_cost)) = bucket
            .iter_mut()
            .find(|(existing_word, _)| existing_word.as_slice() == bytes)
        {
            *existing_cost = (*existing_cost).min(cost);
        } else {
            bucket.push((bytes.to_vec(), cost));
        }

        length_set.insert(bytes.len());
    }

    let mut lengths: Vec<usize> = length_set.into_iter().collect();
    lengths.sort_unstable();

    let n = target.len();
    let mut powers = vec![1u64; n + 1];
    let mut prefix = vec![0u64; n + 1];

    for i in 0..n {
        powers[i + 1] = powers[i].wrapping_mul(base);
        prefix[i + 1] = prefix[i]
            .wrapping_mul(base)
            .wrapping_add((target[i] - b'a' + 1) as u64);
    }

    let inf = i64::MAX / 4;
    let mut dp = vec![inf; n + 1];
    dp[0] = 0;

    for end in 1..=n {
        for &len in &lengths {
            if len > end {
                break;
            }

            let start = end - len;
            if dp[start] == inf {
                continue;
            }

            let hash = prefix[end].wrapping_sub(prefix[start].wrapping_mul(powers[len]));

            if let Some(bucket) = dictionary.get(&(len, hash)) {
                let slice = &target[start..end];
                for (word, cost) in bucket {
                    if word.as_slice() == slice {
                        dp[end] = dp[end].min(dp[start] + *cost);
                    }
                }
            }
        }
    }

    let answer = if dp[n] == inf { -1 } else { dp[n] };
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
