use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut tokens = input.split_whitespace();
    let rows: usize = match tokens.next().and_then(|s| s.parse().ok()) {
        Some(value) => value,
        None => return,
    };

    let mut cells = Vec::new();
    for token in tokens {
        for ch in token.bytes() {
            if ch == b'X' || ch == b'Y' || ch == b'.' {
                cells.push(ch);
            }
        }
    }

    if rows == 0 || cells.is_empty() || cells.len() % rows != 0 {
        return;
    }

    let cols = cells.len() / rows;
    let mut prefix_balance = vec![0i32; cols];
    let mut prefix_x = vec![0i32; cols];
    let mut answer = 0i64;

    for r in 0..rows {
        let mut row_balance = 0i32;
        let mut row_x = 0i32;

        for c in 0..cols {
            match cells[r * cols + c] {
                b'X' => {
                    row_balance += 1;
                    row_x += 1;
                }
                b'Y' => row_balance -= 1,
                _ => {}
            }

            prefix_balance[c] += row_balance;
            prefix_x[c] += row_x;

            if prefix_balance[c] == 0 && prefix_x[c] > 0 {
                answer += 1;
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
