use std::collections::BinaryHeap;
use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let mut distances = Vec::with_capacity(n);

    for _ in 0..n {
        let x: i64 = iter.next().unwrap().parse().unwrap();
        let y: i64 = iter.next().unwrap().parse().unwrap();
        distances.push(x.abs() + y.abs());
    }

    let k: usize = iter.next().unwrap().parse().unwrap();
    let mut nearest = BinaryHeap::<i64>::with_capacity(k);
    let mut output = String::new();

    for (i, distance) in distances.into_iter().enumerate() {
        if nearest.len() < k {
            nearest.push(distance);
        } else if distance < *nearest.peek().unwrap() {
            nearest.pop();
            nearest.push(distance);
        }

        if i > 0 {
            output.push(' ');
        }

        if nearest.len() < k {
            output.push_str("-1");
        } else {
            output.push_str(&nearest.peek().unwrap().to_string());
        }
    }

    output.push('\n');
    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());
    writer.write_all(output.as_bytes()).unwrap();
}
