    io::stdin().read_to_string(&mut input).unwrap();

    let values: Vec<usize> = input
        .split_whitespace()
        .filter_map(|s| s.parse().ok())
        .collect();

    if values.len() < 3 {
        return;
    }

    let k = *values.last().unwrap();
    let nums = &values[..values.len() - 1];
    let pairs = nums.len() / 2;

    let mut diff = vec![0i32; k + 2];
    let baseline = (2 * pairs) as i32;

    for i in 0..pairs {
        let a = nums[i];
        let b = nums[nums.len() - 1 - i];

        let difference = a.abs_diff(b);
        let one_change_limit = a.max(b).max(k - a.min(b));

        diff[0] -= 1;
        diff[one_change_limit + 1] += 1;

        diff[difference] -= 1;
        diff[difference + 1] += 1;
    }

    let mut current = baseline;
    let mut answer = baseline;

    for x in 0..=k {
        current += diff[x];
        answer = answer.min(current);
    }

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    writeln!(output, "{answer}").unwrap();
}
