use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let edge_count: usize = it.next().unwrap().parse().unwrap();
    let n = edge_count + 1;

    let mut graph = vec![Vec::<usize>::new(); n];
    for _ in 0..edge_count {
        let u: usize = it.next().unwrap().parse().unwrap();
        let v: usize = it.next().unwrap().parse().unwrap();
        graph[u].push(v);
        graph[v].push(u);
    }

    let weight = |node: usize| -> usize {
        if node % 2 == 0 { 2 } else { 1 }
    };

    let mut parent = vec![n; n];
    parent[0] = 0;
    let mut order = Vec::with_capacity(n);
    let mut stack = vec![0usize];

    while let Some(u) = stack.pop() {
        order.push(u);
        for &v in &graph[u] {
            if v != parent[u] {
                parent[v] = u;
                stack.push(v);
            }
        }
    }

    // down[u]: maximum marking time from u to a node in u's subtree.
    let mut down = vec![0usize; n];
    for &u in order.iter().rev() {
        for &v in &graph[u] {
            if parent[v] == u {
                down[u] = down[u].max(weight(v) + down[v]);
            }
        }
    }

    // up[u]: maximum marking time from u to a node outside u's subtree.
    let mut up = vec![0usize; n];

    for &u in &order {
        let mut best1 = (0usize, n);
        let mut best2 = (0usize, n);

        if u != 0 {
            best1 = (up[u], n);
        }

        for &v in &graph[u] {
            if parent[v] != u {
                continue;
            }

            let value = weight(v) + down[v];
            if value > best1.0 {
                best2 = best1;
                best1 = (value, v);
            } else if value > best2.0 {
                best2 = (value, v);
            }
        }

        for &v in &graph[u] {
            if parent[v] != u {
                continue;
            }

            let best_excluding_v = if best1.1 == v {
                best2.0
            } else {
                best1.0
            };

            up[v] = weight(u) + best_excluding_v;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for i in 0..n {
        if i > 0 {
            write!(out, " ").unwrap();
        }
        write!(out, "{}", down[i].max(up[i])).unwrap();
    }
    writeln!(out).unwrap();
}
