fn main() {
    const MOD: i64 = 1_000_000_007;

    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let nums: Vec<usize> = input
        .split_whitespace()
        .map(|s| s.parse().unwrap())
        .collect();

    if nums.is_empty() {
        return;
    }

    let mut dp = vec![0_i64; 51];
    for x in 0..=nums[0] {
        dp[x] = 1;
    }

    for i in 1..nums.len() {
        let mut prefix = vec![0_i64; 51];
        prefix[0] = dp[0];
        for x in 1..=50 {
            prefix[x] = (prefix[x - 1] + dp[x]) % MOD;
        }

        let mut next = vec![0_i64; 51];
        for x in 0..=nums[i] {
            let limit = x as isize + nums[i - 1] as isize - nums[i] as isize;
            if limit >= 0 {
                next[x] = prefix[(limit as usize).min(x)];
            }
        }
        dp = next;
    }

    let answer = dp.iter().fold(0_i64, |sum, &value| (sum + value) % MOD);

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
