use std::collections::HashSet;
use std::io::{self, Read, Write};

fn pow10(exp: usize) -> u64 {
    let mut result = 1u64;
    for _ in 0..exp {
        result *= 10;
    }
    result
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let values: Vec<usize> = input
        .split_whitespace()
        .filter_map(|s| s.parse().ok())
        .collect();

    let n = values[0];
    let k = values[1] as u64;

    let half_len = (n + 1) / 2;
    let start = pow10(half_len - 1);
    let end = pow10(half_len);

    let mut digit_sets = HashSet::<[u8; 10]>::new();

    for half in start..end {
        let mut palindrome = half;
        let mut remaining = if n % 2 == 1 { half / 10 } else { half };

        while remaining > 0 {
            palindrome = palindrome * 10 + remaining % 10;
            remaining /= 10;
        }

        if palindrome % k != 0 {
            continue;
        }

        let mut counts = [0u8; 10];
        let mut value = palindrome;
        while value > 0 {
            counts[(value % 10) as usize] += 1;
            value /= 10;
        }
        digit_sets.insert(counts);
    }

    let mut factorial = [1u64; 11];
    for i in 1..=10 {
        factorial[i] = factorial[i - 1] * i as u64;
    }

    let mut answer = 0u64;

    for counts in digit_sets {
        let mut denominator = 1u64;
        for &count in &counts {
            denominator *= factorial[count as usize];
        }

        let total_permutations = factorial[n] / denominator;

        let leading_zero_permutations = if counts[0] > 0 {
            let mut zero_denominator = factorial[(counts[0] - 1) as usize];
            for &count in &counts[1..] {
                zero_denominator *= factorial[count as usize];
            }
            factorial[n - 1] / zero_denominator
        } else {
            0
        };

        answer += total_permutations - leading_zero_permutations;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
