use std::collections::VecDeque;
use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut lines = input.lines().filter(|line| !line.trim().is_empty());
    let m: usize = lines.next().unwrap().trim().parse().unwrap();

    let mut grid = Vec::with_capacity(m);
    for _ in 0..m {
        let row: Vec<i32> = lines
            .next()
            .unwrap()
            .split_whitespace()
            .map(|x| x.parse().unwrap())
            .collect();
        grid.push(row);
    }

    let health: i32 = lines.next().unwrap().trim().parse().unwrap();
    let n = grid[0].len();

    let mut dist = vec![vec![i32::MAX; n]; m];
    let mut deque = VecDeque::new();

    dist[0][0] = grid[0][0];
    deque.push_front((0usize, 0usize));

    let directions = [(1isize, 0isize), (-1, 0), (0, 1), (0, -1)];

    while let Some((r, c)) = deque.pop_front() {
        let current = dist[r][c];

        for &(dr, dc) in &directions {
            let nr = r as isize + dr;
            let nc = c as isize + dc;

            if nr < 0 || nr >= m as isize || nc < 0 || nc >= n as isize {
                continue;
            }

            let nr = nr as usize;
            let nc = nc as usize;
            let weight = grid[nr][nc];
            let next_dist = current + weight;

            if next_dist < dist[nr][nc] {
                dist[nr][nc] = next_dist;
                if weight == 0 {
                    deque.push_front((nr, nc));
                } else {
                    deque.push_back((nr, nc));
                }
            }
        }
    }

    let answer = dist[m - 1][n - 1] < health;

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", answer).unwrap();
}
