fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let tokens: Vec<&str> = input.split_whitespace().collect();

    if tokens.len() < 2 {
        return;
    }

    let (words, target): (Vec<&str>, &str) = if let Ok(count) = tokens[0].parse::<usize>() {
        if tokens.len() >= count + 2 {
            (tokens[1..=count].to_vec(), tokens[count + 1])
        } else {
            (tokens[..tokens.len() - 1].to_vec(), tokens[tokens.len() - 1])
        }
    } else {
        (tokens[..tokens.len() - 1].to_vec(), tokens[tokens.len() - 1])
    };

    let mut trie: Vec<[i32; 26]> = vec![[-1; 26]];

    for word in words {
        let mut node = 0usize;
        for &byte in word.as_bytes() {
            let c = (byte - b'a') as usize;
            let next = trie[node][c];
            if next == -1 {
                let new_node = trie.len();
                trie.push([-1; 26]);
                trie[node][c] = new_node as i32;
                node = new_node;
            } else {
                node = next as usize;
            }
        }
    }

    let target = target.as_bytes();
    let n = target.len();
    let inf = n + 1;
    let mut dp = vec![inf; n + 1];
    dp[0] = 0;

    for i in 0..n {
        if dp[i] == inf {
            continue;
        }

        let mut node = 0usize;
        for j in i..n {
            let c = (target[j] - b'a') as usize;
            let next = trie[node][c];
            if next == -1 {
                break;
            }

            node = next as usize;
            dp[j + 1] = dp[j + 1].min(dp[i] + 1);
        }
    }

    let answer = if dp[n] == inf { -1 } else { dp[n] as i32 };
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
