use std::collections::VecDeque;
use std::io::{self, Read, Write};

fn bfs(start: (usize, usize), targets: &[(usize, usize)]) -> Vec<i32> {
    const SIZE: usize = 50;
    const MOVES: [(isize, isize); 8] = [
        (2, 1), (2, -1), (-2, 1), (-2, -1),
        (1, 2), (1, -2), (-1, 2), (-1, -2),
    ];

    let mut distances = vec![-1i32; SIZE * SIZE];
    let mut queue = VecDeque::new();

    distances[start.0 * SIZE + start.1] = 0;
    queue.push_back(start);

    while let Some((x, y)) = queue.pop_front() {
        let current_distance = distances[x * SIZE + y];

        for &(dx, dy) in &MOVES {
            let nx = x as isize + dx;
            let ny = y as isize + dy;

            if nx >= 0 && nx < SIZE as isize && ny >= 0 && ny < SIZE as isize {
                let nx = nx as usize;
                let ny = ny as usize;
                let index = nx * SIZE + ny;

                if distances[index] == -1 {
                    distances[index] = current_distance + 1;
                    queue.push_back((nx, ny));
                }
            }
        }
    }

    targets
        .iter()
        .map(|&(x, y)| distances[x * SIZE + y])
        .collect()
}

fn solve(
    current: usize,
    remaining: usize,
    pawn_count: usize,
    distances: &[Vec<i32>],
    memo: &mut [i32],
) -> i32 {
    if remaining == 0 {
        return 0;
    }

    let width = pawn_count + 1;
    let memo_index = remaining * width + current;

    if memo[memo_index] != -1 {
        return memo[memo_index];
    }

    let captured = pawn_count - remaining.count_ones() as usize;
    let alice_turn = captured % 2 == 0;

    let mut result = if alice_turn { i32::MIN } else { i32::MAX };

    for pawn in 0..pawn_count {
        if remaining & (1usize << pawn) == 0 {
            continue;
        }

        let next_remaining = remaining ^ (1usize << pawn);
        let score = distances[current][pawn]
            + solve(pawn, next_remaining, pawn_count, distances, memo);

        if alice_turn {
            result = result.max(score);
        } else {
            result = result.min(score);
        }
    }

    memo[memo_index] = result;
    result
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();

    let kx: usize = values.next().unwrap().parse().unwrap();
    let ky: usize = values.next().unwrap().parse().unwrap();
    let pawn_count: usize = values.next().unwrap().parse().unwrap();

    let mut pawns = Vec::with_capacity(pawn_count);
    for _ in 0..pawn_count {
        let x: usize = values.next().unwrap().parse().unwrap();
        let y: usize = values.next().unwrap().parse().unwrap();
        pawns.push((x, y));
    }

    let mut points = pawns.clone();
    points.push((kx, ky));

    let mut distances = vec![vec![0i32; pawn_count]; pawn_count + 1];
    for i in 0..=pawn_count {
        distances[i] = bfs(points[i], &pawns);
    }

    let all_remaining = (1usize << pawn_count) - 1;
    let mut memo = vec![-1i32; (1usize << pawn_count) * (pawn_count + 1)];

    let answer = solve(
        pawn_count,
        all_remaining,
        pawn_count,
        &distances,
        &mut memo,
    );

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    writeln!(output, "{answer}").unwrap();
}
