use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let rows: usize = iter.next().unwrap().parse().unwrap();
    let values: Vec<usize> = iter.map(|s| s.parse().unwrap()).collect();
    let cols = values.len() / rows;

    let mut row_masks = [0usize; 101];

    for r in 0..rows {
        for c in 0..cols {
            let value = values[r * cols + c];
            row_masks[value] |= 1usize << r;
        }
    }

    let size = 1usize << rows;
    let mut dp = vec![-1i32; size];
    dp[0] = 0;

    for value in 1..=100 {
        if row_masks[value] == 0 {
            continue;
        }

        let mut next = dp.clone();

        for mask in 0..size {
            if dp[mask] < 0 {
                continue;
            }

            let available = row_masks[value] & !mask;
            for row in 0..rows {
                let bit = 1usize << row;
                if available & bit != 0 {
                    let new_mask = mask | bit;
                    next[new_mask] = next[new_mask].max(dp[mask] + value as i32);
                }
            }
        }

        dp = next;
    }

    let answer = dp.into_iter().max().unwrap();

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
