use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut lines = input.lines().filter(|line| !line.trim().is_empty());

    let nums: Vec<usize> = lines
        .next()
        .unwrap_or("")
        .split_whitespace()
        .map(|s| s.parse().unwrap())
        .collect();

    let queries: Vec<i64> = lines
        .next()
        .unwrap_or("")
        .split_whitespace()
        .map(|s| s.parse().unwrap())
        .collect();

    let max_value = nums.iter().copied().max().unwrap_or(0);
    let mut frequency = vec![0i64; max_value + 1];

    for value in nums {
        frequency[value] += 1;
    }

    // divisible_pairs[d] is the number of pairs whose GCD is divisible by d.
    let mut divisible_pairs = vec![0i64; max_value + 1];
    for d in 1..=max_value {
        let mut divisible_count = 0i64;
        for multiple in (d..=max_value).step_by(d) {
            divisible_count += frequency[multiple];
        }
        divisible_pairs[d] = divisible_count * (divisible_count - 1) / 2;
    }

    // exact_pairs[d] is the number of pairs whose GCD is exactly d.
    let mut exact_pairs = divisible_pairs;
    for d in (1..=max_value).rev() {
        let mut multiple = d * 2;
        while multiple <= max_value {
            exact_pairs[d] -= exact_pairs[multiple];
            multiple += d;
        }
    }

    // Convert counts into cumulative counts.
    let mut prefix = vec![0i64; max_value + 1];
    for d in 1..=max_value {
        prefix[d] = prefix[d - 1] + exact_pairs[d];
    }

    let mut output = io::BufWriter::new(io::stdout().lock());

    for (i, query) in queries.iter().enumerate() {
        let mut low = 1usize;
        let mut high = max_value;

        while low < high {
            let mid = low + (high - low) / 2;
            if prefix[mid] > *query {
                high = mid;
            } else {
                low = mid + 1;
            }
        }

        if i > 0 {
            write!(output, " ").unwrap();
        }
        write!(output, "{}", low).unwrap();
    }

    writeln!(output).unwrap();
}
