    // The tourist may start in any city without earning or spending points.
    let mut dp = vec![0i32; n];

    for day in 0..k {
        let mut next = vec![i32::MIN; n];

        for destination in 0..n {
            // Stay in the current city.
            next[destination] = dp[destination] + stay_score[day][destination];

            // Travel from a different city to the destination.
            for current in 0..n {
                if current != destination {
                    next[destination] = next[destination]
                        .max(dp[current] + travel_score[current][destination]);
                }
            }
        }

        dp = next;
    }

    let answer = dp.into_iter().max().unwrap();

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    writeln!(output, "{answer}").unwrap();
