        .split_whitespace()
        .filter_map(|s| s.parse().ok())
        .collect();

    if nums.is_empty() {
        return;
    }

    let max_value = *nums.iter().max().unwrap();
    let mut smallest_prime_factor = vec![0usize; max_value + 1];

    for i in 2..=max_value {
        if smallest_prime_factor[i] == 0 {
            smallest_prime_factor[i] = i;
            if i <= max_value / i {
                let mut multiple = i * i;
                while multiple <= max_value {
                    if smallest_prime_factor[multiple] == 0 {
                        smallest_prime_factor[multiple] = i;
                    }
                    multiple += i;
                }
            }
        }
    }

    let mut operations = 0usize;
    let mut upper_bound = *nums.last().unwrap();

    for &value in nums[..nums.len() - 1].iter().rev() {
        if value <= upper_bound {
            upper_bound = value;
        } else {
            let reduced = if value >= 2 {
                smallest_prime_factor[value]
            } else {
                value
            };

            if reduced >= value || reduced > upper_bound {
                let stdout = io::stdout();
                let mut out = io::BufWriter::new(stdout.lock());
                writeln!(out, "-1").unwrap();
                return;
            }

            operations += 1;
            upper_bound = reduced;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{operations}").unwrap();
}
