use std::io::{self, Read, Write};

const MOD: u64 = 1_000_000_007;

fn gcd(mut a: usize, mut b: usize) -> usize {
    while b != 0 {
        let r = a % b;
        a = b;
        b = r;
    }
    a
}

fn add_mod(target: &mut u64, value: u64) {
    *target += value;
    if *target >= MOD {
        *target -= MOD;
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let nums: Vec<usize> = input
        .split(|c: char| !c.is_ascii_digit())
        .filter(|s| !s.is_empty())
        .map(|s| s.parse().unwrap())
        .collect();

    if nums.is_empty() {
        println!("0");
        return;
    }

    let max_value = *nums.iter().max().unwrap();
    let size = max_value + 1;
    let mut dp = vec![0u64; size * size];
    dp[0] = 1;

    for x in nums {
        let mut next = vec![0u64; size * size];

        for g1 in 0..size {
            for g2 in 0..size {
                let value = dp[g1 * size + g2];
                if value == 0 {
                    continue;
                }

                add_mod(&mut next[g1 * size + g2], value);

                let new_g1 = gcd(g1, x);
                add_mod(&mut next[new_g1 * size + g2], value);

                let new_g2 = gcd(g2, x);
                add_mod(&mut next[g1 * size + new_g2], value);
            }
        }

        dp = next;
    }

    let mut answer = 0u64;
    for g in 1..size {
        add_mod(&mut answer, dp[g * size + g]);
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
