use std::io::{self, Read, Write};

fn lower_bound(a: &[i64], target: i64) -> usize {
    let (mut left, mut right) = (0, a.len());
    while left < right {
        let mid = left + (right - left) / 2;
        if a[mid] < target {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    left
}

fn upper_bound(a: &[i64], target: i64) -> usize {
    let (mut left, mut right) = (0, a.len());
    while left < right {
        let mid = left + (right - left) / 2;
        if a[mid] <= target {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    left
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let values: Vec<i64> = input
        .split_whitespace()
        .filter_map(|s| s.parse::<i64>().ok())
        .collect();

    if values.len() < 3 {
        return;
    }

    let k = values[values.len() - 2];
    let num_operations = values[values.len() - 1] as usize;
    let mut nums = values[..values.len() - 2].to_vec();
    nums.sort_unstable();

    let n = nums.len();
    let mut answer = 1usize;

    // Targets not necessarily already present: all selected values must fit
    // in an interval of width 2*k.
    let mut left = 0usize;
    for right in 0..n {
        while nums[right] - nums[left] > 2 * k {
            left += 1;
        }
        answer = answer.max((right - left + 1).min(num_operations));
    }

    // Targets already present can also include their unchanged occurrences.
    let mut i = 0usize;
    while i < n {
        let value = nums[i];
        let mut j = i + 1;
        while j < n && nums[j] == value {
            j += 1;
        }

        let frequency = j - i;
        let reachable_left = lower_bound(&nums, value - k);
        let reachable_right = upper_bound(&nums, value + k);
        let reachable_count = reachable_right - reachable_left;

        answer = answer.max(reachable_count.min(frequency + num_operations));
        i = j;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
