use std::io::{self, Read, Write};

const MOD: i64 = 1_000_000_007;

fn steps_to_one(mut x: usize) -> usize {
    let mut steps = 0;
    while x > 1 {
        x = x.count_ones() as usize;
        steps += 1;
    }
    steps
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();

    let s = tokens.next().unwrap().as_bytes();
    let k: usize = tokens.next().unwrap().parse().unwrap();
    let len = s.len();

    let mut combinations = vec![vec![0_i64; len + 1]; len + 1];
    combinations[0][0] = 1;

    for i in 1..=len {
        combinations[i][0] = 1;
        combinations[i][i] = 1;
        for j in 1..i {
            combinations[i][j] =
                (combinations[i - 1][j - 1] + combinations[i - 1][j]) % MOD;
        }
    }

    // count_by_ones[c] is the number of integers x < n with exactly c set bits.
    let mut count_by_ones = vec![0_i64; len + 1];
    let mut prefix_ones = 0usize;

    for (i, &bit) in s.iter().enumerate() {
        if bit == b'1' {
            let remaining = len - i - 1;

            // Put 0 here instead of n's 1, making the resulting number smaller.
            for suffix_ones in 0..=remaining {
                let total_ones = prefix_ones + suffix_ones;
                count_by_ones[total_ones] =
                    (count_by_ones[total_ones]
                        + combinations[remaining][suffix_ones])
                        % MOD;
            }

            prefix_ones += 1;
        }
    }

    let mut answer = 0_i64;

    for ones in 1..=len {
        if steps_to_one(ones) <= k - 1 {
            answer = (answer + count_by_ones[ones]) % MOD;
        }
    }

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    writeln!(output, "{answer}").unwrap();
}
