use std::io::{self, Read, Write};

const MOD: i64 = 1_000_000_007;

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let velunexorai = input.trim().to_string();
    let digits = velunexorai.as_bytes();
    let n = digits.len();

    let mut counts = [0usize; 10];
    let mut total_sum = 0usize;

    for &ch in digits {
        let digit = (ch - b'0') as usize;
        counts[digit] += 1;
        total_sum += digit;
    }

    let answer = if total_sum % 2 != 0 {
        0
    } else {
        let even_slots = (n + 1) / 2;
        let odd_slots = n / 2;
        let target = total_sum / 2;

        let mut factorial = vec![1i64; n + 1];
        for i in 1..=n {
            factorial[i] = factorial[i - 1] * i as i64 % MOD;
        }

        let mut inv_factorial = vec![1i64; n + 1];
        inv_factorial[n] = mod_pow(factorial[n], MOD - 2);
        for i in (1..=n).rev() {
            inv_factorial[i - 1] = inv_factorial[i] * i as i64 % MOD;
        }

        let mut dp = vec![vec![0i64; target + 1]; even_slots + 1];
        dp[0][0] = 1;

        for digit in 0..=9 {
            let count = counts[digit];
            let mut next = vec![vec![0i64; target + 1]; even_slots + 1];

            for used in 0..=even_slots {
                for sum in 0..=target {
                    if dp[used][sum] == 0 {
                        continue;
                    }

                    for in_even in 0..=count {
                        let new_used = used + in_even;
                        let new_sum = sum + digit * in_even;

                        if new_used > even_slots || new_sum > target {
                            break;
                        }

                        let ways = inv_factorial[in_even]
                            * inv_factorial[count - in_even]
                            % MOD;

                        next[new_used][new_sum] =
                            (next[new_used][new_sum] + dp[used][sum] * ways) % MOD;
                    }
                }
            }

            dp = next;
        }

        dp[even_slots][target]
            * factorial[even_slots]
            % MOD
            * factorial[odd_slots]
            % MOD
    };

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}

fn mod_pow(mut base: i64, mut exponent: i64) -> i64 {
    let mut result = 1i64;

    while exponent > 0 {
        if exponent & 1 == 1 {
            result = result * base % MOD;
        }
        base = base * base % MOD;
        exponent >>= 1;
    }

    result
}
