    for row in &mut fruits {
        for value in row {
            *value = iter.next().unwrap().parse().unwrap();
        }
    }

    const NEG: i64 = i64::MIN / 4;

    let diagonal: i64 = (0..n).map(|i| fruits[i][i]).sum();

    // Child starting from (0, n - 1).
    let mut prev = vec![NEG; n];
    prev[n - 1] = fruits[0][n - 1];

    for row in 1..n {
        let mut cur = vec![NEG; n];

        for col in row..n {
            let mut best = prev[col];
            if col > 0 {
                best = best.max(prev[col - 1]);
            }
            if col + 1 < n {
                best = best.max(prev[col + 1]);
            }

            if best != NEG {
                let gain = if row == col { 0 } else { fruits[row][col] };
                cur[col] = best + gain;
            }
        }

        prev = cur;
    }

    let upper = prev[n - 1];

    // Child starting from (n - 1, 0).
    let mut prev = vec![NEG; n];
    prev[n - 1] = fruits[n - 1][0];

    for col in 1..n {
        let mut cur = vec![NEG; n];

        for row in col..n {
            let mut best = prev[row];
            if row > 0 {
                best = best.max(prev[row - 1]);
            }
            if row + 1 < n {
                best = best.max(prev[row + 1]);
            }

            if best != NEG {
                let gain = if row == col { 0 } else { fruits[row][col] };
                cur[row] = best + gain;
            }
        }

        prev = cur;
    }

    let lower = prev[n - 1];
    let answer = diagonal + upper + lower;

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
