use std::io::{self, Read, Write};

fn parse_numbers(line: &str) -> Vec<i64> {
    line.split(|c: char| !c.is_ascii_digit())
        .filter(|s| !s.is_empty())
        .filter_map(|s| s.parse::<i64>().ok())
        .collect()
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut lines = input.lines().filter(|line| !line.trim().is_empty());
    let nums = match lines.next() {
        Some(line) => parse_numbers(line),
        None => return,
    };

    let rest: Vec<i64> = lines.flat_map(parse_numbers).collect();
    if rest.len() < 3 {
        return;
    }

    let k = rest[0];
    let op1 = rest[1] as usize;
    let op2 = rest[2] as usize;

    let width = op2 + 1;
    let size = (op1 + 1) * width;
    let inf = i64::MAX / 4;
    let mut dp = vec![inf; size];
    dp[0] = 0;

    for &x in &nums {
        let mut next = vec![inf; size];

        for used1 in 0..=op1 {
            for used2 in 0..=op2 {
                let index = used1 * width + used2;
                let current = dp[index];
                if current == inf {
                    continue;
                }

                next[index] = next[index].min(current + x);

                let halved = (x + 1) / 2;
                if used1 < op1 {
                    let ni = (used1 + 1) * width + used2;
                    next[ni] = next[ni].min(current + halved);
                }

                if used2 < op2 && x >= k {
                    let ni = used1 * width + used2 + 1;
                    next[ni] = next[ni].min(current + x - k);
                }

                if used1 < op1 && used2 < op2 {
                    let mut best_both = inf;

                    if x >= k {
                        best_both = best_both.min((x - k + 1) / 2);
                    }

                    if halved >= k {
                        best_both = best_both.min(halved - k);
                    }

                    if best_both != inf {
                        let ni = (used1 + 1) * width + used2 + 1;
                        next[ni] = next[ni].min(current + best_both);
                    }
                }
            }
        }

        dp = next;
    }

    let answer = dp.into_iter().min().unwrap_or(0);
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
