use std::cmp::Reverse;
use std::collections::BinaryHeap;
use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let m: usize = it.next().unwrap().parse().unwrap();

    let digits = n.to_string().len();
    let mut power10 = 1usize;
    for _ in 0..digits {
        power10 *= 10;
    }
    let max_value = power10 - 1;
    let min_value = if digits == 1 { 1 } else { power10 / 10 };

    let mut is_prime = vec![true; max_value + 1];
    is_prime[0] = false;
    if max_value >= 1 {
        is_prime[1] = false;
    }

    let mut p = 2usize;
    while p * p <= max_value {
        if is_prime[p] {
            let mut multiple = p * p;
            while multiple <= max_value {
                is_prime[multiple] = false;
                multiple += p;
            }
        }
        p += 1;
    }

    let answer = if is_prime[n] || is_prime[m] {
        None
    } else {
        let mut dist = vec![u64::MAX; max_value + 1];
        let mut heap = BinaryHeap::new();

        dist[n] = n as u64;
        heap.push(Reverse((n as u64, n)));

        let mut result = None;

        while let Some(Reverse((cost, value))) = heap.pop() {
            if cost != dist[value] {
                continue;
            }
            if value == m {
                result = Some(cost);
                break;
            }

            let mut place = 1usize;
            for _ in 0..digits {
                let digit = (value / place) % 10;

                if digit < 9 {
                    let next = value + place;
                    if !is_prime[next] {
                        let next_cost = cost + next as u64;
                        if next_cost < dist[next] {
                            dist[next] = next_cost;
                            heap.push(Reverse((next_cost, next)));
                        }
                    }
                }

                if digit > 0 {
                    let next = value - place;
                    if next >= min_value && !is_prime[next] {
                        let next_cost = cost + next as u64;
                        if next_cost < dist[next] {
                            dist[next] = next_cost;
                            heap.push(Reverse((next_cost, next)));
                        }
                    }
                }

                place *= 10;
            }
        }

        result
    };

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    match answer {
        Some(cost) => writeln!(out, "{cost}").unwrap(),
        None => writeln!(out, "-1").unwrap(),
    }
}
