fn has_three_sections(mut intervals: Vec<(i64, i64)>) -> bool {
    intervals.sort_unstable();

    let mut sections = 0;
    let mut current_end = i64::MIN;

    for (start, end) in intervals {
        if start >= current_end {
            sections += 1;
            current_end = end;
            if sections >= 3 {
                return true;
            }
        } else {
            current_end = current_end.max(end);
        }
    }

    false
}

