use std::io::{self, Read, Write};

fn feasible(nums: &[i64], limit: i64, min_boundary: Option<i64>, max_boundary: i64) -> bool {
    for pair in nums.windows(2) {
        if pair[0] != -1 && pair[1] != -1 && (pair[0] - pair[1]).abs() > limit {
            return false;
        }
    }

    let Some(min_value) = min_boundary else {
        return true;
    };

    let x = min_value + limit;
    let y = (max_boundary - limit).max(1);
    let close = |a: i64, b: i64| (a - b).abs() <= limit;

    let n = nums.len();
    let mut i = 0;

    while i < n {
        if nums[i] != -1 {
            i += 1;
            continue;
        }

        let start = i;
        while i < n && nums[i] == -1 {
            i += 1;
        }
        let length = i - start;

        let left = if start > 0 { Some(nums[start - 1]) } else { None };
        let right = if i < n { Some(nums[i]) } else { None };

        match (left, right) {
            (None, None) => {}
            (Some(a), None) | (None, Some(a)) => {
                if !close(a, x) && !close(a, y) {
                    return false;
                }
            }
            (Some(a), Some(b)) => {
                let all_x = close(a, x) && close(b, x);
                let all_y = close(a, y) && close(b, y);

                if length == 1 {
                    if !all_x && !all_y {
                        return false;
                    }
                } else {
                    let can_switch = close(x, y)
                        && ((close(a, x) && close(b, y))
                            || (close(a, y) && close(b, x)));

                    if !all_x && !all_y && !can_switch {
                        return false;
                    }
                }
            }
        }
    }

    true
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let bytes = input.as_bytes();
    let mut nums = Vec::<i64>::new();
    let mut i = 0;

    while i < bytes.len() {
        while i < bytes.len() && bytes[i] != b'-' && !bytes[i].is_ascii_digit() {
            i += 1;
        }
        if i >= bytes.len() {
            break;
        }

        let mut sign = 1_i64;
        if bytes[i] == b'-' {
            sign = -1;
            i += 1;
        }

        let mut value = 0_i64;
        let mut has_digit = false;
        while i < bytes.len() && bytes[i].is_ascii_digit() {
            has_digit = true;
            value = value * 10 + (bytes[i] - b'0') as i64;
            i += 1;
        }

        if has_digit {
            nums.push(sign * value);
        }
    }

    if nums.len() < 2 {
        println!("0");
        return;
    }

    let mut min_boundary: Option<i64> = None;
    let mut max_boundary = 0_i64;

    for idx in 0..nums.len() {
        if nums[idx] == -1 {
            continue;
        }

        let adjacent_to_missing = (idx > 0 && nums[idx - 1] == -1)
            || (idx + 1 < nums.len() && nums[idx + 1] == -1);

        if adjacent_to_missing {
            min_boundary = Some(match min_boundary {
                Some(current) => current.min(nums[idx]),
                None => nums[idx],
            });
            max_boundary = max_boundary.max(nums[idx]);
        }
    }

    let mut low = 0_i64;
    let mut high = 1_000_000_000_i64;

    while low < high {
        let mid = low + (high - low) / 2;
        if feasible(&nums, mid, min_boundary, max_boundary) {
            high = mid;
        } else {
            low = mid + 1;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{low}").unwrap();
}
