use std::io::{self, Read, Write};

struct Dsu {
    parent: Vec<usize>,
    size: Vec<usize>,
}

impl Dsu {
    fn new(n: usize) -> Self {
        Self {
            parent: (0..n).collect(),
            size: vec![1; n],
        }
    }

    fn find(&mut self, x: usize) -> usize {
        let mut root = x;
        while self.parent[root] != root {
            root = self.parent[root];
        }

        let mut cur = x;
        while self.parent[cur] != cur {
            let next = self.parent[cur];
            self.parent[cur] = root;
            cur = next;
        }
        root
    }

    fn union(&mut self, a: usize, b: usize) {
        let mut ra = self.find(a);
        let mut rb = self.find(b);
        if ra == rb {
            return;
        }

        if self.size[ra] < self.size[rb] {
            std::mem::swap(&mut ra, &mut rb);
        }

        self.parent[rb] = ra;
        self.size[ra] += self.size[rb];
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut lines = input.lines().filter(|line| !line.trim().is_empty());
    let nums_line = match lines.next() {
        Some(line) => line,
        None => return,
    };
    let threshold_line = match lines.next() {
        Some(line) => line,
        None => return,
    };

    let nums: Vec<usize> = nums_line
        .split_whitespace()
        .map(|s| s.parse().unwrap())
        .collect();

    let threshold: usize = threshold_line
        .split_whitespace()
        .next()
        .unwrap()
        .parse()
        .unwrap();

    let mut dsu = Dsu::new(threshold + 1);
    let mut isolated = 0usize;

    for &x in &nums {
        if x > threshold {
            isolated += 1;
            continue;
        }

        let mut multiple = x;
        while multiple <= threshold {
            dsu.union(x, multiple);
            multiple += x;
        }
    }

    let mut seen = vec![false; threshold + 1];
    let mut components = isolated;

    for &x in &nums {
        if x <= threshold {
            let root = dsu.find(x);
            if !seen[root] {
                seen[root] = true;
                components += 1;
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{components}").unwrap();
}
