    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let mut points = Vec::with_capacity(n);

    for _ in 0..n {
        let x: i32 = iter.next().unwrap().parse().unwrap();
        let y: i32 = iter.next().unwrap().parse().unwrap();
        points.push((x, y));
    }

    let mut max_area: i32 = -1;

    for i in 0..n {
        for j in (i + 1)..n {
            let (x1, y1) = points[i];
            let (x2, y2) = points[j];

            if x1 == x2 || y1 == y2 {
                continue;
            }

            if !points.contains(&(x1, y2)) || !points.contains(&(x2, y1)) {
                continue;
            }

            let min_x = x1.min(x2);
            let max_x = x1.max(x2);
            let min_y = y1.min(y2);
            let max_y = y1.max(y2);

            let mut valid = true;
            for &(x, y) in &points {
                let is_corner = (x == min_x || x == max_x)
                    && (y == min_y || y == max_y);

                if !is_corner
                    && x >= min_x
                    && x <= max_x
                    && y >= min_y
                    && y <= max_y
                {
                    valid = false;
                    break;
                }
            }

            if valid {
                let area = (max_x - min_x) * (max_y - min_y);
                max_area = max_area.max(area);
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{max_area}").unwrap();
}
