    points.push(goal);

    let start_idx = n;
    let goal_idx = n + 1;
    let point_count = n + 2;
    let source_count = n + 1;

    let mut pair_dist = vec![-1i32; source_count * point_count];
    let mut dist = vec![-1i32; h * w];
    let mut queue = Vec::with_capacity(h * w);

    for source_idx in 0..source_count {
        dist.fill(-1);
        queue.clear();

        let source = points[source_idx];
        dist[source] = 0;
        queue.push(source);

        let mut head = 0;
        while head < queue.len() {
            let pos = queue[head];
            head += 1;

            let r = pos / w;
            let c = pos % w;
            let next_dist = dist[pos] + 1;

            if r > 0 {
                let next = pos - w;
                if grid[next] != b'#' && dist[next] == -1 {
                    dist[next] = next_dist;
                    queue.push(next);
                }
            }
            if r + 1 < h {
                let next = pos + w;
                if grid[next] != b'#' && dist[next] == -1 {
                    dist[next] = next_dist;
                    queue.push(next);
                }
            }
            if c > 0 {
                let next = pos - 1;
                if grid[next] != b'#' && dist[next] == -1 {
                    dist[next] = next_dist;
                    queue.push(next);
                }
            }
            if c + 1 < w {
                let next = pos + 1;
                if grid[next] != b'#' && dist[next] == -1 {
                    dist[next] = next_dist;
                    queue.push(next);
                }
            }
        }

        for target_idx in 0..point_count {
            pair_dist[source_idx * point_count + target_idx] =
                dist[points[target_idx]];
        }
    }

    let direct = pair_dist[start_idx * point_count + goal_idx];
    if direct == -1 || direct > t {
        let mut out = io::BufWriter::new(io::stdout().lock());
        writeln!(out, "-1").unwrap();
        return;
    }

    if n == 0 {
        let mut out = io::BufWriter::new(io::stdout().lock());
        writeln!(out, "0").unwrap();
        return;
    }

    const INF: i32 = 1 << 30;
    let states = 1usize << n;
    let mut dp = vec![INF; states * n];

    for i in 0..n {
        let d = pair_dist[start_idx * point_count + i];
        if d >= 0 && d <= t {
            dp[(1usize << i) * n + i] = d;
        }
    }

    let full_mask = states - 1;
    let mut answer = 0u32;

    for mask in 1usize..states {
        let base = mask * n;
        let candy_count = mask.count_ones();

        let mut included = mask;
        while included != 0 {
            let i = included.trailing_zeros() as usize;
            included &= included - 1;

            let current = dp[base + i];
            if current == INF {
                continue;
            }

            let to_goal = pair_dist[i * point_count + goal_idx];
            if to_goal >= 0 && current + to_goal <= t {
                answer = answer.max(candy_count);
            }

            let mut remaining = full_mask ^ mask;
            while remaining != 0 {
                let j = remaining.trailing_zeros() as usize;
                remaining &= remaining - 1;

                let d = pair_dist[i * point_count + j];
                if d < 0 {
                    continue;
                }

                let next_dist = current + d;
                if next_dist > t {
                    continue;
                }

                let next_mask = mask | (1usize << j);
                let index = next_mask * n + j;
                if next_dist < dp[index] {
                    dp[index] = next_dist;
                }
            }
        }
    }

    let mut out = io::BufWriter::new(io::stdout().lock());
    writeln!(out, "{answer}").unwrap();
}
