fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let _m: usize = iter.next().unwrap().parse().unwrap();
    let strings: Vec<Vec<u8>> = (0..n)
        .map(|_| iter.next().unwrap().as_bytes().to_vec())
        .collect();

    let mut adjacent = vec![vec![false; n]; n];
    for i in 0..n {
        for j in i + 1..n {
            let differences = strings[i]
                .iter()
                .zip(strings[j].iter())
                .filter(|(a, b)| a != b)
                .count();
            if differences == 1 {
                adjacent[i][j] = true;
                adjacent[j][i] = true;
            }
        }
    }

    let mut dp = vec![vec![false; n]; 1 << n];
    for i in 0..n {
        dp[1 << i][i] = true;
    }

    for mask in 1..(1 << n) {
        for last in 0..n {
            if !dp[mask][last] {
                continue;
            }
            for next in 0..n {
                if mask & (1 << next) == 0 && adjacent[last][next] {
                    dp[mask | (1 << next)][next] = true;
                }
            }
        }
    }

    let possible = dp[(1 << n) - 1].iter().any(|&value| value);
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", if possible { "Yes" } else { "No" }).unwrap();
}
