        if j > 0 {
            let y = b[j - 1];
            if y >= x - d {
                let sum = x + y;
                answer = Some(answer.map_or(sum, |current| current.max(sum)));
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", answer.unwrap_or(-1)).unwrap();
