fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let q: usize = iter.next().unwrap().parse().unwrap();

    let mut graph: Vec<HashSet<usize>> = (0..n).map(|_| HashSet::new()).collect();
    let mut isolated = n;
    let mut output = String::new();

    for _ in 0..q {
        let query_type: u8 = iter.next().unwrap().parse().unwrap();

        if query_type == 1 {
            let u: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
            let v: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;

            if graph[u].is_empty() {
                isolated -= 1;
            }
            if graph[v].is_empty() {
                isolated -= 1;
            }

            graph[u].insert(v);
            graph[v].insert(u);
        } else {
            let v: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
            let neighbors = std::mem::take(&mut graph[v]);

            if !neighbors.is_empty() {
                isolated += 1;
            }

            for u in neighbors {
                graph[u].remove(&v);
                if graph[u].is_empty() {
                    isolated += 1;
                }
            }
        }

        output.push_str(&isolated.to_string());
        output.push('\n');
    }

    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());
    writer.write_all(output.as_bytes()).unwrap();
}
