fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let m: usize = iter.next().unwrap().parse().unwrap();

    let mut sets: Vec<Vec<usize>> = Vec::with_capacity(n);
    let mut containing: Vec<Vec<usize>> = vec![Vec::new(); m + 1];
    let mut contains_one = vec![false; n];
    let mut contains_m = vec![false; n];

    for i in 0..n {
        let a: usize = iter.next().unwrap().parse().unwrap();
        let mut set = Vec::with_capacity(a);

        for _ in 0..a {
            let x: usize = iter.next().unwrap().parse().unwrap();
            set.push(x);
            containing[x].push(i);

            if x == 1 {
                contains_one[i] = true;
            }
            if x == m {
                contains_m[i] = true;
            }
        }
        sets.push(set);
    }

    let mut distance = vec![-1_i32; n];
    let mut queue = VecDeque::new();

    for i in 0..n {
        if contains_one[i] {
            distance[i] = 0;
            queue.push_back(i);

            if contains_m[i] {
                println!("0");
                return;
            }
        }
    }

    let mut processed_element = vec![false; m + 1];

    while let Some(set_index) = queue.pop_front() {
        let next_distance = distance[set_index] + 1;

        for &element in &sets[set_index] {
            if processed_element[element] {
                continue;
            }
            processed_element[element] = true;

            for &next_set in &containing[element] {
                if distance[next_set] != -1 {
                    continue;
                }

                distance[next_set] = next_distance;
                if contains_m[next_set] {
                    let stdout = io::stdout();
                    let mut out = io::BufWriter::new(stdout.lock());
                    writeln!(out, "{}", next_distance).unwrap();
                    return;
                }
                queue.push_back(next_set);
            }
        }
    }

    println!("-1");
}
