            let dy = points[i].1 - points[j].1;
            if dx * dx + dy * dy <= d_squared {
                infected[j] = true;
                queue.push_back(j);
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    for is_infected in infected {
        writeln!(out, "{}", if is_infected { "Yes" } else { "No" }).unwrap();
