use std::io::{self, Read, Write};

fn sleep_until(x: i64, times: &[i64], prefix: &[i64]) -> i64 {
    let mut left = 0usize;
    let mut right = times.len();

    while left < right {
        let mid = left + (right - left) / 2;
        if times[mid] <= x {
            left = mid + 1;
        } else {
            right = mid;
        }
    }

    let index = left - 1;
    prefix[index]
        + if index % 2 == 1 {
            x - times[index]
        } else {
            0
        }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let times: Vec<i64> = (0..n)
        .map(|_| iter.next().unwrap().parse().unwrap())
        .collect();

    let mut prefix = vec![0i64; n];
    for i in 1..n {
        prefix[i] = prefix[i - 1];
        if i % 2 == 0 {
            prefix[i] += times[i] - times[i - 1];
        }
    }

    let q: usize = iter.next().unwrap().parse().unwrap();
    let mut output = io::BufWriter::new(io::stdout().lock());

    for _ in 0..q {
        let l: i64 = iter.next().unwrap().parse().unwrap();
        let r: i64 = iter.next().unwrap().parse().unwrap();
        let answer = sleep_until(r, &times, &prefix) - sleep_until(l, &times, &prefix);
        writeln!(output, "{answer}").unwrap();
    }
}
