use std::collections::BTreeSet;
use std::fmt::Write as FmtWrite;
use std::io::{self, Read, Write};

fn rebalance(
    high: &mut BTreeSet<(i64, usize)>,
    low: &mut BTreeSet<(i64, usize)>,
    k: usize,
    sum: &mut i64,
) {
    while high.len() > k {
        let value = *high.iter().next().unwrap();
        high.remove(&value);
        low.insert(value);
        *sum -= value.0;
    }

    while high.len() < k {
        let value = *low.iter().next_back().unwrap();
        low.remove(&value);
        high.insert(value);
        *sum += value.0;
    }

    loop {
        let Some(&smallest_high) = high.iter().next() else {
            break;
        };
        let Some(&largest_low) = low.iter().next_back() else {
            break;
        };

        if largest_low <= smallest_high {
            break;
        }

        high.remove(&smallest_high);
        low.remove(&largest_low);
        high.insert(largest_low);
        low.insert(smallest_high);
        *sum += largest_low.0 - smallest_high.0;
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let k: usize = iter.next().unwrap().parse().unwrap();
    let q: usize = iter.next().unwrap().parse().unwrap();

    let mut values = vec![0_i64; n];
    let mut high = BTreeSet::new();
    let mut low = BTreeSet::new();

    for i in 0..n {
        if i >= n - k {
            high.insert((0_i64, i));
        } else {
            low.insert((0_i64, i));
        }
    }

    let mut sum = 0_i64;
    let mut output = String::new();

    for _ in 0..q {
        let x: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let y: i64 = iter.next().unwrap().parse().unwrap();

        let old = (values[x], x);
        if high.remove(&old) {
            sum -= old.0;
        } else {
            low.remove(&old);
        }

        values[x] = y;
        high.insert((y, x));
        sum += y;

        rebalance(&mut high, &mut low, k, &mut sum);
        writeln!(output, "{sum}").unwrap();
    }

    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());
    writer.write_all(output.as_bytes()).unwrap();
}
