use std::io::{self, Read, Write};

fn normalize(cells: &[(usize, usize)]) -> (Vec<(usize, usize)>, usize, usize) {
    let min_r = cells.iter().map(|&(r, _)| r).min().unwrap();
    let min_c = cells.iter().map(|&(_, c)| c).min().unwrap();

    let normalized: Vec<_> = cells
        .iter()
        .map(|&(r, c)| (r - min_r, c - min_c))
        .collect();

    let height = normalized.iter().map(|&(r, _)| r).max().unwrap() + 1;
    let width = normalized.iter().map(|&(_, c)| c).max().unwrap() + 1;

    (normalized, height, width)
}

fn valid_placements(
    cells: &[(usize, usize)],
    target: u128,
    hx: usize,
    wx: usize,
) -> Vec<u128> {
    let (cells, height, width) = normalize(cells);
    let mut placements = Vec::new();

    if height > hx || width > wx {
        return placements;
    }

    for dr in 0..=hx - height {
        for dc in 0..=wx - width {
            let mut mask = 0u128;
            for &(r, c) in &cells {
                let index = (r + dr) * wx + (c + dc);
                mask |= 1u128 << index;
            }
            if mask & !target == 0 {
                placements.push(mask);
            }
        }
    }

    placements
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let ha: usize = it.next().unwrap().parse().unwrap();
    let _wa: usize = it.next().unwrap().parse().unwrap();
    let mut a_cells = Vec::new();
    for r in 0..ha {
        let row = it.next().unwrap().as_bytes();
        for (c, &ch) in row.iter().enumerate() {
            if ch == b'#' {
                a_cells.push((r, c));
            }
        }
    }

    let hb: usize = it.next().unwrap().parse().unwrap();
    let _wb: usize = it.next().unwrap().parse().unwrap();
    let mut b_cells = Vec::new();
    for r in 0..hb {
        let row = it.next().unwrap().as_bytes();
        for (c, &ch) in row.iter().enumerate() {
            if ch == b'#' {
                b_cells.push((r, c));
            }
        }
    }

    let hx: usize = it.next().unwrap().parse().unwrap();
    let wx: usize = it.next().unwrap().parse().unwrap();
    let mut target = 0u128;
    for r in 0..hx {
        let row = it.next().unwrap().as_bytes();
        for (c, &ch) in row.iter().enumerate() {
            if ch == b'#' {
                target |= 1u128 << (r * wx + c);
            }
        }
    }

    let a_placements = valid_placements(&a_cells, target, hx, wx);
    let b_placements = valid_placements(&b_cells, target, hx, wx);

    let possible = a_placements.iter().any(|&a| {
        b_placements.iter().any(|&b| (a | b) == target)
    });

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", if possible { "Yes" } else { "No" }).unwrap();
}
