        let current_index = pattern.iter().position(|&c| c == grid[row][col]).unwrap();
        let next_char = pattern[(current_index + 1) % pattern.len()];

        for &(dr, dc) in &directions {
            let nr = row as isize + dr;
            let nc = col as isize + dc;

            if nr < 0 || nr >= h as isize || nc < 0 || nc >= w as isize {
                continue;
            }

            let nr = nr as usize;
            let nc = nc as usize;
            let index = nr * w + nc;

            if !visited[index] && grid[nr][nc] == next_char {
                visited[index] = true;
                queue.push_back((nr, nc));
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "No").unwrap();
