fn mex(mask: usize) -> i64 {
    for value in 0..=3 {
        if mask & (1 << value) == 0 {
            return value as i64;
        }
    }
    unreachable!()
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let a: Vec<usize> = (0..n)
        .map(|_| iter.next().unwrap().parse().unwrap())
        .collect();
    let s = iter.next().unwrap().as_bytes();

    let mut count_m = [0_i64; 8];
    let mut count_me = [0_i64; 8];
    let mut answer = 0_i64;

    for i in 0..n {
        let bit = 1_usize << a[i];

        match s[i] {
            b'M' => {
                count_m[bit] += 1;
            }
            b'E' => {
                for mask in 0..8 {
                    count_me[mask | bit] += count_m[mask];
                }
            }
            b'X' => {
                for mask in 0..8 {
                    answer += count_me[mask] * mex(mask | bit);
                }
            }
            _ => unreachable!(),
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
