        let (to_row, to_col) = border[(i + 1) % border.len()];
        result[to_row][to_col] = grid[from_row][from_col];
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for row in result {
        out.write_all(&row).unwrap();
        writeln!(out).unwrap();
