use std::collections::VecDeque;
use std::io::{self, Read, Write};

fn bfs_max(start: usize, adjacency: &[Vec<usize>], range: std::ops::Range<usize>) -> usize {
    let mut distance = vec![usize::MAX; adjacency.len()];
    let mut queue = VecDeque::new();

    distance[start] = 0;
    queue.push_back(start);

    while let Some(vertex) = queue.pop_front() {
        for &next in &adjacency[vertex] {
            if distance[next] == usize::MAX {
                distance[next] = distance[vertex] + 1;
                queue.push_back(next);
            }
        }
    }

    range.map(|v| distance[v]).max().unwrap()
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n1: usize = iter.next().unwrap().parse().unwrap();
    let n2: usize = iter.next().unwrap().parse().unwrap();
    let m: usize = iter.next().unwrap().parse().unwrap();
    let n = n1 + n2;

    let mut adjacency = vec![Vec::new(); n];

    for _ in 0..m {
        let a: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let b: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        adjacency[a].push(b);
        adjacency[b].push(a);
    }

    let max_first = bfs_max(0, &adjacency, 0..n1);
    let max_second = bfs_max(n - 1, &adjacency, n1..n);
    let answer = max_first + max_second + 1;

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
