use std::io::{self, Read, Write};

fn dfs(
    player: usize,
    n: usize,
    target: usize,
    incompatible: &[u16],
    teams: &mut Vec<u16>,
) -> u64 {
    if player == n {
        return if teams.len() == target { 1 } else { 0 };
    }

    if teams.len() + (n - player) < target {
        return 0;
    }

    let mut ways = 0u64;
    let player_bit = 1u16 << player;

    for i in 0..teams.len() {
        if teams[i] & incompatible[player] == 0 {
            teams[i] |= player_bit;
            ways += dfs(player + 1, n, target, incompatible, teams);
            teams[i] ^= player_bit;
        }
    }

    if teams.len() < target {
        teams.push(player_bit);
        ways += dfs(player + 1, n, target, incompatible, teams);
        teams.pop();
    }

    ways
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let t: usize = iter.next().unwrap().parse().unwrap();
    let m: usize = iter.next().unwrap().parse().unwrap();

    let mut incompatible = vec![0u16; n];

    for _ in 0..m {
        let a: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let b: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        incompatible[a] |= 1u16 << b;
        incompatible[b] |= 1u16 << a;
    }

    let answer = dfs(0, n, t, &incompatible, &mut Vec::new());

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
