use std::io::{self, Read, Write};

const MOD: i64 = 998_244_353;
const STATES: usize = 1 << 11;
const MASK: usize = STATES - 1;

fn mod_pow(mut base: i64, mut exp: i64) -> i64 {
    let mut result = 1i64;
    while exp > 0 {
        if exp & 1 == 1 {
            result = result * base % MOD;
        }
        base = base * base % MOD;
        exp >>= 1;
    }
    result
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let mut dp = vec![0i64; STATES];
    dp[1] = 1; // Only sum 0 is initially achievable.

    for _ in 0..n {
        let a: usize = iter.next().unwrap().parse().unwrap();
        let inv_a = mod_pow(a as i64, MOD - 2);
        let limit = a.min(10);
        let large_count = a - limit;

        let mut next = vec![0i64; STATES];

        for state in 0..STATES {
            if dp[state] == 0 {
                continue;
            }

            if large_count > 0 {
                let add = dp[state] * (large_count as i64 % MOD) % MOD * inv_a % MOD;
                next[state] = (next[state] + add) % MOD;
            }

            for value in 1..=limit {
                let new_state = state | ((state << value) & MASK);
                let add = dp[state] * inv_a % MOD;
                next[new_state] += add;
                if next[new_state] >= MOD {
                    next[new_state] -= MOD;
                }
            }
        }

        dp = next;
    }

    let mut answer = 0i64;
    for state in 0..STATES {
        if state & (1 << 10) != 0 {
            answer += dp[state];
            if answer >= MOD {
                answer -= MOD;
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
