        for j in 1..=w {
            if holed[i * w + (j - 1)] {
                current[j] = 0;
            } else {
                current[j] = 1 + previous[j]
                    .min(current[j - 1])
                    .min(previous[j - 1]);
                answer += current[j] as u64;
            }
        }

        std::mem::swap(&mut previous, &mut current);
    }

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
