    let mut dp = vec![0_u64; n + 1];
    dp[0] = 1;

    for (i, &ch) in s.iter().enumerate() {
        let mut next = vec![0_u64; n + 1];

        for balance in 0..=i {
            let ways = dp[balance];
            if ways == 0 {
                continue;
            }

            if ch == b'(' || ch == b'?' {
                next[balance + 1] += ways;
                if next[balance + 1] >= MOD {
                    next[balance + 1] -= MOD;
                }
            }

            if (ch == b')' || ch == b'?') && balance > 0 {
                next[balance - 1] += ways;
                if next[balance - 1] >= MOD {
                    next[balance - 1] -= MOD;
                }
            }
        }

        dp = next;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", dp[0]).unwrap();
}
