fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let m: usize = iter.next().unwrap().parse().unwrap();

    let mut pull_tabs: Vec<i64> = Vec::new();
    let mut regulars: Vec<i64> = Vec::new();
    let mut openers: Vec<i64> = Vec::new();

    for _ in 0..n {
        let t: i32 = iter.next().unwrap().parse().unwrap();
        let x: i64 = iter.next().unwrap().parse().unwrap();
        match t {
            0 => pull_tabs.push(x),
            1 => regulars.push(x),
            2 => openers.push(x),
            _ => unreachable!(),
        }
    }

    pull_tabs.sort_unstable_by(|a, b| b.cmp(a));
    regulars.sort_unstable_by(|a, b| b.cmp(a));
    openers.sort_unstable_by(|a, b| b.cmp(a));

    let mut pull_prefix = vec![0_i64; pull_tabs.len() + 1];
    for i in 0..pull_tabs.len() {
        pull_prefix[i + 1] = pull_prefix[i] + pull_tabs[i];
    }

    let mut regular_prefix = vec![0_i64; regulars.len() + 1];
    for i in 0..regulars.len() {
        regular_prefix[i + 1] = regular_prefix[i] + regulars[i];
    }

    let mut answer = 0_i64;
    let mut opener_count = 0_usize;
    let mut capacity = 0_i64;

    for regular_count in 0..=regulars.len().min(m) {
        while capacity < regular_count as i64 && opener_count < openers.len() {
            capacity += openers[opener_count];
            opener_count += 1;
        }

        if capacity < regular_count as i64 {
            break;
        }
        if regular_count + opener_count > m {
            break;
        }

        let pull_count = (m - regular_count - opener_count).min(pull_tabs.len());
        let happiness =
            regular_prefix[regular_count] + pull_prefix[pull_count];
        answer = answer.max(happiness);
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
