    let high = (sum + n - 1) / n;

    let mut deficit = 0_i64;
    let mut excess = 0_i64;

    for &value in &values {
        if value < low {
            deficit += low - value;
        }
        if value > high {
            excess += value - high;
        }
    }

    let answer = deficit.max(excess);

