use std::io::{self, Read, Write};

struct Wheel {
    cost: f64,
    outcomes: Vec<usize>,
    zero_count: usize,
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let m: usize = iter.next().unwrap().parse().unwrap();

    let mut wheels = Vec::with_capacity(n);

    for _ in 0..n {
        let cost: f64 = iter.next().unwrap().parse::<f64>().unwrap();
        let p: usize = iter.next().unwrap().parse().unwrap();

        let mut outcomes = Vec::with_capacity(p);
        let mut zero_count = 0;

        for _ in 0..p {
            let s: usize = iter.next().unwrap().parse().unwrap();
            if s == 0 {
                zero_count += 1;
            } else {
                outcomes.push(s);
            }
        }

        wheels.push(Wheel {
            cost,
            outcomes,
            zero_count,
        });
    }

    // dp[x]: minimum expected cost to earn at least x more points.
    let mut dp = vec![0.0_f64; m + 1];

    for remaining in 1..=m {
        let mut best = f64::INFINITY;

        for wheel in &wheels {
            let total_count = wheel.outcomes.len() + wheel.zero_count;
            let positive_count = wheel.outcomes.len();

            let mut numerator = wheel.cost * total_count as f64;

            for &score in &wheel.outcomes {
                numerator += dp[remaining.saturating_sub(score)];
            }

            let expected = numerator / positive_count as f64;
            best = best.min(expected);
        }

        dp[remaining] = best;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{:.15}", dp[m]).unwrap();
}
