    let p: i64 = iter.next().unwrap().parse().unwrap();

    let mut fares: Vec<i64> = (0..n)
        .map(|_| iter.next().unwrap().parse().unwrap())
        .collect();

    fares.sort_unstable_by(|a, b| b.cmp(a));

    let total: i64 = fares.iter().sum();
    let mut covered_sum = 0_i64;
    let mut answer = total;
    let max_batches = (n + d - 1) / d;

    for batches in 1..=max_batches {
        let start = (batches - 1) * d;
        let end = (batches * d).min(n);

        for &fare in &fares[start..end] {
            covered_sum += fare;
        }

        let cost = batches as i64 * p + total - covered_sum;
        answer = answer.min(cost);
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
