use std::io::{self, Read, Write};

fn next_permutation(a: &mut [usize]) -> bool {
    if a.len() < 2 {
        return false;
    }

    let mut i = a.len() - 2;
    loop {
        if a[i] < a[i + 1] {
            break;
        }
        if i == 0 {
            a.reverse();
            return false;
        }
        i -= 1;
    }

    let mut j = a.len() - 1;
    while a[j] <= a[i] {
        j -= 1;
    }

    a.swap(i, j);
    a[i + 1..].reverse();
    true
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let values: Vec<i32> = input
        .split_whitespace()
        .map(|s| s.parse().unwrap())
        .collect();

    let lines = [
        [0, 1, 2],
        [3, 4, 5],
        [6, 7, 8],
        [0, 3, 6],
        [1, 4, 7],
        [2, 5, 8],
        [0, 4, 8],
        [2, 4, 6],
    ];

    let mut permutation: Vec<usize> = (0..9).collect();
    let mut valid = 0usize;
    let mut total = 0usize;

    loop {
        total += 1;

        let mut position = [0usize; 9];
        for (order, &cell) in permutation.iter().enumerate() {
            position[cell] = order;
        }

        let mut disappointed = false;

        for line in &lines {
            let mut cells = *line;
            cells.sort_by_key(|&cell| position[cell]);

            if values[cells[0]] == values[cells[1]] {
                disappointed = true;
                break;
            }
        }

        if !disappointed {
            valid += 1;
        }

        if !next_permutation(&mut permutation) {
            break;
        }
    }

    let probability = valid as f64 / total as f64;
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{:.15}", probability).unwrap();
}
