fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let m: usize = iter.next().unwrap().parse().unwrap();

    let mut graph = vec![Vec::<(usize, i64, i64)>::new(); n];

    for _ in 0..m {
        let a: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let b: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let x: i64 = iter.next().unwrap().parse().unwrap();
        let y: i64 = iter.next().unwrap().parse().unwrap();

        graph[a].push((b, x, y));
        graph[b].push((a, -x, -y));
    }

    let mut coordinates: Vec<Option<(i64, i64)>> = vec![None; n];
    coordinates[0] = Some((0, 0));

    let mut stack = vec![0usize];
    while let Some(current) = stack.pop() {
        let (cx, cy) = coordinates[current].unwrap();

        for &(next, dx, dy) in &graph[current] {
            if coordinates[next].is_none() {
                coordinates[next] = Some((cx + dx, cy + dy));
                stack.push(next);
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for coordinate in coordinates {
        match coordinate {
            Some((x, y)) => writeln!(out, "{} {}", x, y).unwrap(),
            None => writeln!(out, "undecidable").unwrap(),
        }
    }
}
