use std::collections::HashSet;
use std::io::{self, Read, Write};

fn generate_placements(mut cells: Vec<(i32, i32)>) -> Vec<u16> {
    let mut placements = HashSet::new();

    for _ in 0..4 {
        let min_r = cells.iter().map(|&(r, _)| r).min().unwrap();
        let min_c = cells.iter().map(|&(_, c)| c).min().unwrap();

        for cell in &mut cells {
            cell.0 -= min_r;
            cell.1 -= min_c;
        }

        let height = cells.iter().map(|&(r, _)| r).max().unwrap() + 1;
        let width = cells.iter().map(|&(_, c)| c).max().unwrap() + 1;

        if height <= 4 && width <= 4 {
            for dr in 0..=4 - height {
                for dc in 0..=4 - width {
                    let mut mask = 0u16;
                    for &(r, c) in &cells {
                        let nr = r + dr;
                        let nc = c + dc;
                        mask |= 1u16 << (nr * 4 + nc);
                    }
                    placements.insert(mask);
                }
            }
        }

        // Rotate 90 degrees clockwise. Normalization is done next iteration.
        cells = cells.into_iter().map(|(r, c)| (c, -r)).collect();
    }

    placements.into_iter().collect()
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let rows: Vec<&str> = input.split_whitespace().collect();

    let mut pieces = Vec::with_capacity(3);
    let mut total_cells = 0;

    for p in 0..3 {
        let mut cells = Vec::new();
        for r in 0..4 {
            for (c, ch) in rows[p * 4 + r].bytes().enumerate() {
                if ch == b'#' {
                    cells.push((r as i32, c as i32));
                    total_cells += 1;
                }
            }
        }
        pieces.push(generate_placements(cells));
    }

    let mut possible = false;

    if total_cells == 16 {
        'search: for &a in &pieces[0] {
            for &b in &pieces[1] {
                if a & b != 0 {
                    continue;
                }
                let ab = a | b;
                for &c in &pieces[2] {
                    if ab & c == 0 && (ab | c) == 0xFFFF {
                        possible = true;
                        break 'search;
                    }
                }
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", if possible { "Yes" } else { "No" }).unwrap();
}
