            *x = iter.next().unwrap().parse().unwrap();
        }

        let mut next = dp.clone();

        for state in 0..states {
            if dp[state] == inf {
                continue;
            }

            let mut value = state;
            let mut next_state = 0usize;
            let mut multiplier = 1usize;

            for j in 0..k {
                let current = value % base;
                value /= base;
                let updated = (current + increase[j]).min(p);
                next_state += updated * multiplier;
                multiplier *= base;
            }

            next[next_state] = next[next_state].min(dp[state] + cost);
        }

        dp = next;
    }

    let answer = dp[states - 1];
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    if answer == inf {
        writeln!(out, "-1").unwrap();
    } else {
        writeln!(out, "{answer}").unwrap();
    }
}
