fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let t = iter.next().unwrap().as_bytes().to_vec();
    let m = t.len();

    let mut prefix_matches = Vec::with_capacity(n);
    let mut suffix_matches = Vec::with_capacity(n);

    for _ in 0..n {
        let s = iter.next().unwrap().as_bytes();

        let mut prefix = 0;
        for &c in s {
            if prefix < m && c == t[prefix] {
                prefix += 1;
            }
        }

        let mut suffix = 0;
        for &c in s.iter().rev() {
            if suffix < m && c == t[m - 1 - suffix] {
                suffix += 1;
            }
        }

        prefix_matches.push(prefix);
        suffix_matches.push(suffix);
    }

    suffix_matches.sort_unstable();

    let mut answer: u64 = 0;
    for prefix in prefix_matches {
        let required = m - prefix;
        let index = suffix_matches.partition_point(|&suffix| suffix < required);
        answer += (n - index) as u64;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
