use std::cmp::Reverse;
use std::collections::BinaryHeap;
use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let mut products = Vec::with_capacity(n);

    for _ in 0..n {
        let t: u64 = iter.next().unwrap().parse().unwrap();
        let d: u64 = iter.next().unwrap().parse().unwrap();
        products.push((t, t + d));
    }

    products.sort_unstable_by_key(|&(start, _)| start);

    let mut deadlines = BinaryHeap::<Reverse<u64>>::new();
    let mut index = 0usize;
    let mut time = 0u64;
    let mut answer = 0usize;

    while index < n || !deadlines.is_empty() {
        if deadlines.is_empty() && index < n && time < products[index].0 {
            time = products[index].0;
        }

        while index < n && products[index].0 <= time {
            deadlines.push(Reverse(products[index].1));
            index += 1;
        }

        while let Some(&Reverse(deadline)) = deadlines.peek() {
            if deadline < time {
                deadlines.pop();
            } else {
                break;
            }
        }

        if deadlines.pop().is_some() {
            answer += 1;
            time += 1;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
