use std::io::{self, Read, Write};

fn dijkstra_dense(
    distances: &[u64],
    n: usize,
    source: usize,
    multiplier: u64,
    surcharge: u64,
) -> Vec<u64> {
    const INF: u64 = u64::MAX / 4;

    let mut dist = vec![INF; n];
    let mut used = vec![false; n];
    dist[source] = 0;

    for _ in 0..n {
        let mut vertex = None;
        for i in 0..n {
            if !used[i] && vertex.is_none_or(|v| dist[i] < dist[v]) {
                vertex = Some(i);
            }
        }

        let Some(v) = vertex else {
            break;
        };
        used[v] = true;

        for to in 0..n {
            if !used[to] {
                let cost = distances[v * n + to] * multiplier + surcharge;
                dist[to] = dist[to].min(dist[v] + cost);
            }
        }
    }

    dist
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let a: u64 = iter.next().unwrap().parse().unwrap();
    let b: u64 = iter.next().unwrap().parse().unwrap();
    let c: u64 = iter.next().unwrap().parse().unwrap();

    let mut distances = Vec::with_capacity(n * n);
    for _ in 0..n * n {
        distances.push(iter.next().unwrap().parse::<u64>().unwrap());
    }

    let car = dijkstra_dense(&distances, n, 0, a, 0);
    let train = dijkstra_dense(&distances, n, n - 1, b, c);

    let answer = (0..n).map(|i| car[i] + train[i]).min().unwrap();

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
