        .map(|_| iter.next().unwrap().parse().unwrap())
        .collect();

    let inv_n = mod_pow(n as u64, MOD - 2);
    let mut suffix_sum = 0u64;

    for &value in a.iter().rev() {
        let expected = suffix_sum * inv_n % MOD;
        suffix_sum = (suffix_sum + value + expected) % MOD;
    }

    let answer = suffix_sum * inv_n % MOD;

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
