use std::io::{self, Read, Write};

#[derive(Clone, Copy)]
struct Edge {
    u: usize,
    v: usize,
    w: u64,
}

struct Dsu {
    parent: [usize; 8],
    size: [usize; 8],
}

impl Dsu {
    fn new(n: usize) -> Self {
        let mut parent = [0; 8];
        for i in 0..n {
            parent[i] = i;
        }
        Self {
            parent,
            size: [1; 8],
        }
    }

    fn root(&self, mut x: usize) -> usize {
        while self.parent[x] != x {
            x = self.parent[x];
        }
        x
    }

    fn unite(&mut self, a: usize, b: usize) -> Option<(usize, usize, usize)> {
        let mut ra = self.root(a);
        let mut rb = self.root(b);
        if ra == rb {
            return None;
        }
        if self.size[ra] < self.size[rb] {
            std::mem::swap(&mut ra, &mut rb);
        }

        let old_size = self.size[ra];
        self.parent[rb] = ra;
        self.size[ra] += self.size[rb];
        Some((ra, rb, old_size))
    }

    fn rollback(&mut self, change: (usize, usize, usize)) {
        let (ra, rb, old_size) = change;
        self.parent[rb] = rb;
        self.size[ra] = old_size;
    }
}

fn search(
    index: usize,
    selected: usize,
    sum: u64,
    target: usize,
    modulo: u64,
    edges: &[Edge],
    dsu: &mut Dsu,
    answer: &mut u64,
) {
    if *answer == 0 {
        return;
    }

    if selected == target {
        *answer = (*answer).min(sum);
        return;
    }

    if index == edges.len() || selected + (edges.len() - index) < target {
        return;
    }

    let edge = edges[index];

    if let Some(change) = dsu.unite(edge.u, edge.v) {
        search(
            index + 1,
            selected + 1,
            (sum + edge.w) % modulo,
            target,
            modulo,
            edges,
            dsu,
            answer,
        );
        dsu.rollback(change);
    }

    search(
        index + 1,
        selected,
        sum,
        target,
        modulo,
        edges,
        dsu,
        answer,
    );
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let m: usize = iter.next().unwrap().parse().unwrap();
    let k: u64 = iter.next().unwrap().parse().unwrap();

    let mut edges = Vec::with_capacity(m);
    for _ in 0..m {
        let u: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let v: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let w: u64 = iter.next().unwrap().parse().unwrap();
        edges.push(Edge { u, v, w });
    }

    if k == 1 {
        println!("0");
        return;
    }

    let mut dsu = Dsu::new(n);
    let mut answer = k;
    search(0, 0, 0, n - 1, k, &edges, &mut dsu, &mut answer);

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
