use std::collections::VecDeque;
use std::io::{self, Read, Write};

fn is_compatible(start: usize, m: usize, s: &[u8], t: &[u8], erased: &[bool]) -> bool {
    for j in 0..m {
        if !erased[start + j] && s[start + j] != t[j] {
            return false;
        }
    }
    true
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let m: usize = it.next().unwrap().parse().unwrap();
    let s = it.next().unwrap().as_bytes().to_vec();
    let t = it.next().unwrap().as_bytes().to_vec();

    let window_count = n - m + 1;
    let mut erased = vec![false; n];
    let mut used = vec![false; window_count];
    let mut queue = VecDeque::new();

    for start in 0..window_count {
        if is_compatible(start, m, &s, &t, &erased) {
            used[start] = true;
            queue.push_back(start);
        }
    }

    let mut erased_count = 0;

    while let Some(start) = queue.pop_front() {
        for pos in start..start + m {
            if erased[pos] {
                continue;
            }

            erased[pos] = true;
            erased_count += 1;

            let left = pos.saturating_sub(m - 1);
            let right = pos.min(n - m);

            for next_start in left..=right {
                if !used[next_start]
                    && is_compatible(next_start, m, &s, &t, &erased)
                {
                    used[next_start] = true;
                    queue.push_back(next_start);
                }
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", if erased_count == n { "Yes" } else { "No" }).unwrap();
}
