use std::io::{self, Read, Write};

fn count_black(prefix: &[i64], n: usize, rows: i64, cols: i64) -> i64 {
    let n64 = n as i64;
    let full_rows = rows / n64;
    let full_cols = cols / n64;
    let rem_rows = (rows % n64) as usize;
    let rem_cols = (cols % n64) as usize;
    let width = n + 1;

    let total = prefix[n * width + n];
    let row_strip = prefix[n * width + rem_cols];
    let col_strip = prefix[rem_rows * width + n];
    let corner = prefix[rem_rows * width + rem_cols];

    full_rows * full_cols * total
        + full_rows * row_strip
        + full_cols * col_strip
        + corner
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let q: usize = iter.next().unwrap().parse().unwrap();

    let width = n + 1;
    let mut prefix = vec![0_i64; width * width];

    for i in 0..n {
        let row = iter.next().unwrap().as_bytes();
        for j in 0..n {
            let black = if row[j] == b'B' { 1 } else { 0 };
            prefix[(i + 1) * width + (j + 1)] =
                prefix[i * width + (j + 1)]
                + prefix[(i + 1) * width + j]
                - prefix[i * width + j]
                + black;
        }
    }

    let mut output = String::new();

    for _ in 0..q {
        let a: i64 = iter.next().unwrap().parse().unwrap();
        let b: i64 = iter.next().unwrap().parse().unwrap();
        let c: i64 = iter.next().unwrap().parse().unwrap();
        let d: i64 = iter.next().unwrap().parse().unwrap();

        let answer =
            count_black(&prefix, n, c + 1, d + 1)
            - count_black(&prefix, n, a, d + 1)
            - count_black(&prefix, n, c + 1, b)
            + count_black(&prefix, n, a, b);

        output.push_str(&answer.to_string());
        output.push('\n');
    }

    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());
    writer.write_all(output.as_bytes()).unwrap();
}
