use std::io::{self, Read, Write};

fn next_permutation(a: &mut [usize]) -> bool {
    if a.len() < 2 {
        return false;
    }

    let mut i = a.len() - 2;
    while a[i] >= a[i + 1] {
        if i == 0 {
            a.reverse();
            return false;
        }
        i -= 1;
    }

    let mut j = a.len() - 1;
    while a[j] <= a[i] {
        j -= 1;
    }

    a.swap(i, j);
    a[i + 1..].reverse();
    true
}

fn inversion_count(p: &[usize]) -> usize {
    let mut count = 0;
    for i in 0..p.len() {
        for j in i + 1..p.len() {
            if p[i] > p[j] {
                count += 1;
            }
        }
    }
    count
}

fn permutations(n: usize) -> Vec<(Vec<usize>, usize)> {
    let mut p: Vec<usize> = (0..n).collect();
    let mut result = Vec::new();

    loop {
        result.push((p.clone(), inversion_count(&p)));
        if !next_permutation(&mut p) {
            break;
        }
    }

    result
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let h: usize = iter.next().unwrap().parse().unwrap();
    let w: usize = iter.next().unwrap().parse().unwrap();

    let mut a = vec![vec![0_i64; w]; h];
    let mut b = vec![vec![0_i64; w]; h];

    for row in &mut a {
        for value in row {
            *value = iter.next().unwrap().parse().unwrap();
        }
    }

    for row in &mut b {
        for value in row {
            *value = iter.next().unwrap().parse().unwrap();
        }
    }

    let row_permutations = permutations(h);
    let column_permutations = permutations(w);
    let mut answer: Option<usize> = None;

    for (rows, row_cost) in &row_permutations {
        for (columns, column_cost) in &column_permutations {
            let mut matches = true;

            'check: for i in 0..h {
                for j in 0..w {
                    if a[rows[i]][columns[j]] != b[i][j] {
                        matches = false;
                        break 'check;
                    }
                }
            }

            if matches {
                let cost = row_cost + column_cost;
                answer = Some(answer.map_or(cost, |current| current.min(cost)));
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    match answer {
        Some(value) => writeln!(out, "{value}").unwrap(),
        None => writeln!(out, "-1").unwrap(),
    }
}
