use std::io::{self, Read, Write};

const MOD: i64 = 998_244_353;

fn mod_pow(mut base: i64, mut exp: i64) -> i64 {
    let mut result = 1i64;
    while exp > 0 {
        if exp & 1 == 1 {
            result = result * base % MOD;
        }
        base = base * base % MOD;
        exp >>= 1;
    }
    result
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let h: usize = iter.next().unwrap().parse().unwrap();
    let w: usize = iter.next().unwrap().parse().unwrap();
    let n = h * w;

    let mut grid = Vec::with_capacity(n);
    for _ in 0..h {
        grid.extend_from_slice(iter.next().unwrap().as_bytes());
    }

    let mut component = vec![-1i32; n];
    let mut stack = Vec::new();
    let mut component_count = 0i64;

    for start in 0..n {
        if grid[start] != b'#' || component[start] != -1 {
            continue;
        }

        let id = component_count as i32;
        component_count += 1;
        component[start] = id;
        stack.push(start);

        while let Some(pos) = stack.pop() {
            let row = pos / w;
            let col = pos % w;

            if row > 0 {
                let next = pos - w;
                if grid[next] == b'#' && component[next] == -1 {
                    component[next] = id;
                    stack.push(next);
                }
            }
            if row + 1 < h {
                let next = pos + w;
                if grid[next] == b'#' && component[next] == -1 {
                    component[next] = id;
                    stack.push(next);
                }
            }
            if col > 0 {
                let next = pos - 1;
                if grid[next] == b'#' && component[next] == -1 {
                    component[next] = id;
                    stack.push(next);
                }
            }
            if col + 1 < w {
                let next = pos + 1;
                if grid[next] == b'#' && component[next] == -1 {
                    component[next] = id;
                    stack.push(next);
                }
            }
        }
    }

    let mut red_count = 0i64;
    let mut total_components = 0i64;

    for pos in 0..n {
        if grid[pos] != b'.' {
            continue;
        }

        red_count += 1;
        let row = pos / w;
        let col = pos % w;
        let mut adjacent = [-1i32; 4];
        let mut distinct = 0usize;

        let mut add_component = |id: i32| {
            if id >= 0 && !adjacent[..distinct].contains(&id) {
                adjacent[distinct] = id;
                distinct += 1;
            }
        };

        if row > 0 {
            add_component(component[pos - w]);
        }
        if row + 1 < h {
            add_component(component[pos + w]);
        }
        if col > 0 {
            add_component(component[pos - 1]);
        }
        if col + 1 < w {
            add_component(component[pos + 1]);
        }

        total_components += component_count + 1 - distinct as i64;
    }

    let answer = (total_components % MOD) * mod_pow(red_count % MOD, MOD - 2) % MOD;

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
