    let mut base = 0_i64;
    let mut diff = vec![0_i64; n + 1];

    for i in 0..m - 1 {
        let a = x[i].min(x[i + 1]);
        let b = x[i].max(x[i + 1]);
        let distance = (b - a) as i64;

        base += distance;

        let change = n as i64 - 2 * distance;
        diff[a - 1] += change;
        diff[b - 1] -= change;
    }

    let mut current = 0_i64;
    let mut answer = i64::MAX;

    for edge in 0..n {
        current += diff[edge];
        answer = answer.min(base + current);
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
