use std::collections::VecDeque;
use std::io::{self, Read, Write};

fn pair_index(a: usize, b: usize, m: usize) -> usize {
    a * m - a * (a.saturating_sub(1)) / 2 + (b - a)
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let mut grid = Vec::with_capacity(n);
    let mut player_cells = Vec::with_capacity(2);

    for r in 0..n {
        let row = it.next().unwrap().as_bytes().to_vec();
        for c in 0..n {
            if row[c] == b'P' {
                player_cells.push((r, c));
            }
        }
        grid.push(row);
    }

    let mut cell_id = vec![usize::MAX; n * n];
    let mut cells = Vec::new();

    for r in 0..n {
        for c in 0..n {
            if grid[r][c] != b'#' {
                cell_id[r * n + c] = cells.len();
                cells.push((r, c));
            }
        }
    }

    let m = cells.len();
    let mut next_pos = vec![[0usize; 4]; m];
    let directions = [(-1isize, 0isize), (1, 0), (0, -1), (0, 1)];

    for (id, &(r, c)) in cells.iter().enumerate() {
        for (dir, &(dr, dc)) in directions.iter().enumerate() {
            let nr = r as isize + dr;
            let nc = c as isize + dc;

            if nr >= 0
                && nr < n as isize
                && nc >= 0
                && nc < n as isize
                && grid[nr as usize][nc as usize] != b'#'
            {
                next_pos[id][dir] = cell_id[nr as usize * n + nc as usize];
            } else {
                next_pos[id][dir] = id;
            }
        }
    }

    let mut a = cell_id[player_cells[0].0 * n + player_cells[0].1];
    let mut b = cell_id[player_cells[1].0 * n + player_cells[1].1];
    if a > b {
        std::mem::swap(&mut a, &mut b);
    }

    let state_count = m * (m + 1) / 2;
    let mut visited = vec![false; state_count];
    visited[pair_index(a, b, m)] = true;

    let mut queue = VecDeque::<u32>::new();
    queue.push_back((a * m + b) as u32);

    let mut moves = 0i32;
    let mut answer = -1;

    'bfs: while !queue.is_empty() {
        let level_size = queue.len();

        for _ in 0..level_size {
            let code = queue.pop_front().unwrap() as usize;
            let x = code / m;
            let y = code % m;

            for dir in 0..4 {
                let mut nx = next_pos[x][dir];
                let mut ny = next_pos[y][dir];

                if nx == ny {
                    answer = moves + 1;
                    break 'bfs;
                }

                if nx > ny {
                    std::mem::swap(&mut nx, &mut ny);
                }

                let idx = pair_index(nx, ny, m);
                if !visited[idx] {
                    visited[idx] = true;
                    queue.push_back((nx * m + ny) as u32);
                }
            }
        }

        moves += 1;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
