fn gcd(mut a: i128, mut b: i128) -> i128 {
    while b != 0 {
        let r = a % b;
        a = b;
        b = r;
    }
    a
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: i128 = iter.next().unwrap().parse().unwrap();
    let m: i128 = iter.next().unwrap().parse().unwrap();
    let k: i128 = iter.next().unwrap().parse().unwrap();

    let lcm = n / gcd(n, m) * m;

    let count = |x: i128| -> i128 {
        x / n + x / m - 2 * (x / lcm)
    };

    let mut low = 0i128;
    let mut high = 1i128;

    while count(high) < k {
        high *= 2;
    }

    while high - low > 1 {
        let mid = low + (high - low) / 2;
        if count(mid) >= k {
            high = mid;
        } else {
            low = mid;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{high}").unwrap();
}
