use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let m: usize = iter.next().unwrap().parse().unwrap();

    let mut graph = vec![Vec::new(); n];
    for _ in 0..m {
        let u: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let v: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        graph[u].push(v);
        graph[v].push(u);
    }

    let mut weight = vec![0usize; n];
    for w in &mut weight {
        *w = iter.next().unwrap().parse().unwrap();
    }

    let mut pieces = vec![0i64; n];
    for a in &mut pieces {
        *a = iter.next().unwrap().parse().unwrap();
    }

    let mut order: Vec<usize> = (0..n).collect();
    order.sort_unstable_by_key(|&v| weight[v]);

    let mut value = vec![0i64; n];

    for x in order {
        let capacity = weight[x] - 1;
        let mut dp = vec![0i64; capacity + 1];

        for &y in &graph[x] {
            if weight[y] >= weight[x] {
                continue;
            }

            let cost = weight[y];
            for c in (cost..=capacity).rev() {
                dp[c] = dp[c].max(dp[c - cost] + value[y]);
            }
        }

        value[x] = 1 + dp[capacity];
    }

    let answer: i64 = (0..n).map(|i| pieces[i] * value[i]).sum();

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
