use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let values: Vec<usize> = (0..n)
        .map(|_| iter.next().unwrap().parse().unwrap())
        .collect();

    let max_value = values.iter().copied().max().unwrap_or(0);

    let mut spf = vec![0usize; max_value + 1];
    for i in 2..=max_value {
        if spf[i] == 0 {
            spf[i] = i;
            if i <= max_value / i {
                for j in (i * i..=max_value).step_by(i) {
                    if spf[j] == 0 {
                        spf[j] = i;
                    }
                }
            }
        }
    }

    let mut kernel = vec![0usize; max_value + 1];
    if max_value >= 1 {
        kernel[1] = 1;
    }

    for x in 2..=max_value {
        let p = spf[x];
        let y = x / p;
        kernel[x] = if y % p == 0 {
            kernel[y / p]
        } else {
            kernel[y] * p
        };
    }

    let mut frequencies = vec![0i64; max_value + 1];
    let mut zero_count = 0i64;
    let mut answer = 0i64;

    for (index, &value) in values.iter().enumerate() {
        if value == 0 {
            answer += index as i64;
            zero_count += 1;
        } else {
            let key = kernel[value];
            answer += zero_count + frequencies[key];
            frequencies[key] += 1;
        }
    }

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    writeln!(output, "{answer}").unwrap();
}
