use std::collections::HashSet;
use std::io::{self, Read, Write};

fn dfs(
    occupied: u128,
    used: usize,
    h: usize,
    w: usize,
    tiles: &[(usize, usize)],
    target: u128,
    area_sum: &[usize],
    memo: &mut HashSet<(u128, usize)>,
) -> bool {
    if occupied == target {
        return true;
    }

    let state = (occupied, used);
    if memo.contains(&state) {
        return false;
    }

    let n = tiles.len();
    let all = (1usize << n) - 1;
    let available = all ^ used;
    let remaining_area = h * w - occupied.count_ones() as usize;

    let mut subset = available;
    let mut area_possible = false;
    loop {
        if area_sum[subset] == remaining_area {
            area_possible = true;
            break;
        }
        if subset == 0 {
            break;
        }
        subset = (subset - 1) & available;
    }

    if !area_possible {
        memo.insert(state);
        return false;
    }

    let first = (!occupied & target).trailing_zeros() as usize;
    let row = first / w;
    let col = first % w;

    for i in 0..n {
        if used & (1usize << i) != 0 {
            continue;
        }

        let (a, b) = tiles[i];
        let orientations = if a == b {
            [(a, b), (a, b)]
        } else {
            [(a, b), (b, a)]
        };
        let orientation_count = if a == b { 1 } else { 2 };

        for &(tile_h, tile_w) in orientations.iter().take(orientation_count) {
            if row + tile_h > h || col + tile_w > w {
                continue;
            }

            let mut placement = 0u128;
            let row_bits = ((1u128 << tile_w) - 1) << col;
            for r in row..row + tile_h {
                placement |= row_bits << (r * w);
            }

            if occupied & placement != 0 {
                continue;
            }

            if dfs(
                occupied | placement,
                used | (1usize << i),
                h,
                w,
                tiles,
                target,
                area_sum,
                memo,
            ) {
                return true;
            }
        }
    }

    memo.insert(state);
    false
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let h: usize = iter.next().unwrap().parse().unwrap();
    let w: usize = iter.next().unwrap().parse().unwrap();

    let mut tiles = Vec::with_capacity(n);
    for _ in 0..n {
        let a: usize = iter.next().unwrap().parse().unwrap();
        let b: usize = iter.next().unwrap().parse().unwrap();
        tiles.push((a, b));
    }

    let mut area_sum = vec![0usize; 1usize << n];
    for mask in 1usize..(1usize << n) {
        let bit = mask.trailing_zeros() as usize;
        area_sum[mask] = area_sum[mask ^ (1usize << bit)] + tiles[bit].0 * tiles[bit].1;
    }

    let cells = h * w;
    let target = (1u128 << cells) - 1;
    let mut memo = HashSet::new();

    let possible = dfs(0, 0, h, w, &tiles, target, &area_sum, &mut memo);

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", if possible { "Yes" } else { "No" }).unwrap();
}
