    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let h: usize = it.next().unwrap().parse().unwrap();
    let w: usize = it.next().unwrap().parse().unwrap();
    let m: usize = it.next().unwrap().parse().unwrap();

    let mut operations = Vec::with_capacity(m);
    let mut max_color = 0usize;

    for _ in 0..m {
        let t: usize = it.next().unwrap().parse().unwrap();
        let a: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
        let x: usize = it.next().unwrap().parse().unwrap();
        max_color = max_color.max(x);
        operations.push((t, a, x));
    }

    let mut used_rows = vec![false; h];
    let mut used_cols = vec![false; w];
    let mut fixed_rows = 0usize;
    let mut fixed_cols = 0usize;
    let mut counts = vec![0u64; max_color + 1];

    for &(t, a, x) in operations.iter().rev() {
        if t == 1 {
            if !used_rows[a] {
                used_rows[a] = true;
                counts[x] += (w - fixed_cols) as u64;
                fixed_rows += 1;
            }
        } else if !used_cols[a] {
            used_cols[a] = true;
            counts[x] += (h - fixed_rows) as u64;
            fixed_cols += 1;
        }
    }

    counts[0] += ((h - fixed_rows) as u64) * ((w - fixed_cols) as u64);

    let k = counts.iter().filter(|&&count| count > 0).count();

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{k}").unwrap();

    for (color, &count) in counts.iter().enumerate() {
        if count > 0 {
            writeln!(out, "{color} {count}").unwrap();
        }
    }
}
