use std::collections::VecDeque;
use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let h: usize = iter.next().unwrap().parse().unwrap();
    let w: usize = iter.next().unwrap().parse().unwrap();

    let mut grid = Vec::with_capacity(h);
    let mut start = (0usize, 0usize);
    let mut target = (0usize, 0usize);

    for r in 0..h {
        let row = iter.next().unwrap().as_bytes().to_vec();
        for c in 0..w {
            match row[c] {
                b'S' => start = (r, c),
                b'T' => target = (r, c),
                _ => {}
            }
        }
        grid.push(row);
    }

    let n: usize = iter.next().unwrap().parse().unwrap();
    let mut medicines = Vec::with_capacity(n);
    let mut medicine_at = vec![usize::MAX; h * w];

    for i in 0..n {
        let r: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let c: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let e: usize = iter.next().unwrap().parse().unwrap();
        medicines.push((r, c, e));
        medicine_at[r * w + c] = i;
    }

    let start_medicine = medicine_at[start.0 * w + start.1];
    if start_medicine == usize::MAX {
        println!("No");
        return;
    }

    let mut reachable = vec![false; n];
    let mut medicine_queue = VecDeque::new();
    reachable[start_medicine] = true;
    medicine_queue.push_back(start_medicine);

    let mut distances = vec![usize::MAX; h * w];
    let directions = [(1isize, 0isize), (-1, 0), (0, 1), (0, -1)];

    while let Some(index) = medicine_queue.pop_front() {
        let (sr, sc, energy) = medicines[index];

        distances.fill(usize::MAX);
        let mut bfs = VecDeque::new();
        distances[sr * w + sc] = 0;
        bfs.push_back((sr, sc));

        while let Some((r, c)) = bfs.pop_front() {
            let distance = distances[r * w + c];

            if (r, c) == target {
                let stdout = io::stdout();
                let mut out = io::BufWriter::new(stdout.lock());
                writeln!(out, "Yes").unwrap();
                return;
            }

            let medicine_index = medicine_at[r * w + c];
            if medicine_index != usize::MAX && !reachable[medicine_index] {
                reachable[medicine_index] = true;
                medicine_queue.push_back(medicine_index);
            }

            if distance == energy {
                continue;
            }

            for &(dr, dc) in &directions {
                let nr = r as isize + dr;
                let nc = c as isize + dc;

                if nr < 0 || nr >= h as isize || nc < 0 || nc >= w as isize {
                    continue;
                }

                let nr = nr as usize;
                let nc = nc as usize;
                let position = nr * w + nc;

                if grid[nr][nc] != b'#' && distances[position] == usize::MAX {
                    distances[position] = distance + 1;
                    bfs.push_back((nr, nc));
                }
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "No").unwrap();
}
