use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let mut graph = vec![Vec::<usize>::new(); n];

    for _ in 0..n.saturating_sub(1) {
        let a: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let b: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        graph[a].push(b);
        graph[b].push(a);
    }

    let mut weights = vec![0_i128; n];
    for weight in &mut weights {
        *weight = iter.next().unwrap().parse::<i128>().unwrap();
    }

    let mut parent = vec![usize::MAX; n];
    let mut depth = vec![0_usize; n];
    let mut order = Vec::with_capacity(n);
    let mut stack = vec![0_usize];
    parent[0] = 0;

    while let Some(v) = stack.pop() {
        order.push(v);
        for &to in &graph[v] {
            if parent[to] == usize::MAX {
                parent[to] = v;
                depth[to] = depth[v] + 1;
                stack.push(to);
            }
        }
    }

    let total_weight: i128 = weights.iter().sum();
    let mut subtree_weight = weights.clone();
    let mut root_value = 0_i128;

    for v in 0..n {
        root_value += weights[v] * depth[v] as i128;
    }

    for &v in order.iter().rev() {
        if v != 0 {
            subtree_weight[parent[v]] += subtree_weight[v];
        }
    }

    let mut values = vec![0_i128; n];
    values[0] = root_value;
    let mut answer = root_value;

    for &v in order.iter().skip(1) {
        values[v] = values[parent[v]] + total_weight - 2 * subtree_weight[v];
        answer = answer.min(values[v]);
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
