            largest_fitting
        } else {
            let largest_aligned = current & current.wrapping_neg();
            largest_aligned.min(largest_fitting)
        };

        intervals.push((current, current + length));
        current += length;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    writeln!(out, "{}", intervals.len()).unwrap();
    for (left, right) in intervals {
        writeln!(out, "{} {}", left, right).unwrap();
