    let y: f64 = iter.next().unwrap().parse::<u64>().unwrap() as f64;

    let mut memo = HashMap::new();
    memo.insert(0, 0.0);

    let answer = expected_cost(n, a, x, y, &mut memo);

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{:.15}", answer).unwrap();
}
