use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let h: usize = iter.next().unwrap().parse().unwrap();
    let w: usize = iter.next().unwrap().parse().unwrap();

    let grid: Vec<Vec<u8>> = (0..h)
        .map(|_| iter.next().unwrap().as_bytes().to_vec())
        .collect();

    let n = h * w;
    let mut dangerous = vec![false; n];
    let directions = [(-1_i32, 0_i32), (1, 0), (0, -1), (0, 1)];

    for r in 0..h {
        for c in 0..w {
            if grid[r][c] != b'.' {
                continue;
            }
            for &(dr, dc) in &directions {
                let nr = r as i32 + dr;
                let nc = c as i32 + dc;
                if nr >= 0
                    && nr < h as i32
                    && nc >= 0
                    && nc < w as i32
                    && grid[nr as usize][nc as usize] == b'#'
                {
                    dangerous[r * w + c] = true;
                    break;
                }
            }
        }
    }

    let mut visited = vec![false; n];
    let mut boundary_stamp = vec![0usize; n];
    let mut component_id = 0usize;
    let mut answer = 1usize;
    let mut stack = Vec::new();

    for start_r in 0..h {
        for start_c in 0..w {
            let start = start_r * w + start_c;
            if grid[start_r][start_c] == b'#'
                || dangerous[start]
                || visited[start]
            {
                continue;
            }

            component_id += 1;
            visited[start] = true;
            stack.push(start);
            let mut reachable = 0usize;

            while let Some(pos) = stack.pop() {
                reachable += 1;
                let r = pos / w;
                let c = pos % w;

                for &(dr, dc) in &directions {
                    let nr = r as i32 + dr;
                    let nc = c as i32 + dc;
                    if nr < 0 || nr >= h as i32 || nc < 0 || nc >= w as i32 {
                        continue;
                    }

                    let nr = nr as usize;
                    let nc = nc as usize;
                    if grid[nr][nc] == b'#' {
                        continue;
                    }

                    let next = nr * w + nc;
                    if dangerous[next] {
                        if boundary_stamp[next] != component_id {
                            boundary_stamp[next] = component_id;
                            reachable += 1;
                        }
                    } else if !visited[next] {
                        visited[next] = true;
                        stack.push(next);
                    }
                }
            }

            answer = answer.max(reachable);
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
