use std::io::{self, Read, Write};

struct Fenwick {
    tree: Vec<i64>,
}

impl Fenwick {
    fn new(n: usize) -> Self {
        Self {
            tree: vec![0; n + 1],
        }
    }

    fn add(&mut self, mut index: usize, value: i64) {
        while index < self.tree.len() {
            self.tree[index] += value;
            index += index & (!index + 1);
        }
    }

    fn sum(&self, mut index: usize) -> i64 {
        let mut result = 0;
        while index > 0 {
            result += self.tree[index];
            index &= index - 1;
        }
        result
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let a: Vec<i64> = (0..n)
        .map(|_| iter.next().unwrap().parse().unwrap())
        .collect();

    let mut values = a.clone();
    values.sort_unstable();
    values.dedup();

    let mut count_tree = Fenwick::new(values.len());
    let mut sum_tree = Fenwick::new(values.len());
    let mut answer = 0i64;

    for &x in &a {
        let pos = values.binary_search(&x).unwrap();

        let smaller_count = count_tree.sum(pos);
        let smaller_sum = sum_tree.sum(pos);
        answer += x * smaller_count - smaller_sum;

        count_tree.add(pos + 1, 1);
        sum_tree.add(pos + 1, x);
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
