use std::io::{self, Read, Write};

struct Dsu {
    parent: Vec<usize>,
    size: Vec<usize>,
    components: usize,
}

impl Dsu {
    fn new(n: usize) -> Self {
        Self {
            parent: (0..n).collect(),
            size: vec![1; n],
            components: n,
        }
    }

    fn find(&mut self, x: usize) -> usize {
        let mut root = x;
        while self.parent[root] != root {
            root = self.parent[root];
        }

        let mut cur = x;
        while self.parent[cur] != cur {
            let next = self.parent[cur];
            self.parent[cur] = root;
            cur = next;
        }
        root
    }

    fn unite(&mut self, a: usize, b: usize) -> bool {
        let mut ra = self.find(a);
        let mut rb = self.find(b);

        if ra == rb {
            return false;
        }

        if self.size[ra] < self.size[rb] {
            std::mem::swap(&mut ra, &mut rb);
        }

        self.parent[rb] = ra;
        self.size[ra] += self.size[rb];
        self.components -= 1;
        true
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let m: usize = iter.next().unwrap().parse().unwrap();

    let mut operations: Vec<(i64, Vec<usize>)> = Vec::with_capacity(m);

    for _ in 0..m {
        let k: usize = iter.next().unwrap().parse().unwrap();
        let cost: i64 = iter.next().unwrap().parse().unwrap();

        let mut vertices = Vec::with_capacity(k);
        for _ in 0..k {
            let vertex: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
            vertices.push(vertex);
        }
        operations.push((cost, vertices));
    }

    operations.sort_unstable_by_key(|operation| operation.0);

    let mut dsu = Dsu::new(n);
    let mut answer = 0i64;

    for (cost, vertices) in operations {
        let first = vertices[0];
        for &vertex in &vertices[1..] {
            if dsu.unite(first, vertex) {
                answer += cost;
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    if dsu.components == 1 {
        writeln!(out, "{answer}").unwrap();
    } else {
        writeln!(out, "-1").unwrap();
    }
}
