                if a[i] == a[j] || b[i] == b[j] {
                    let next = mask ^ (1usize << i) ^ (1usize << j);
                    if !winning[next] {
                        winning[mask] = true;
                        break 'search;
                    }
                }
            }
        }
    }

    let answer = if winning[size - 1] {
        "Takahashi"
    } else {
        "Aoki"
    };

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
