use std::collections::VecDeque;
use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let mut next = Vec::with_capacity(n);
    let mut indegree = vec![0usize; n];

    for _ in 0..n {
        let v: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        next.push(v);
        indegree[v] += 1;
    }

    let mut queue = VecDeque::new();
    for i in 0..n {
        if indegree[i] == 0 {
            queue.push_back(i);
        }
    }

    let mut removed_order = Vec::with_capacity(n);
    while let Some(v) = queue.pop_front() {
        removed_order.push(v);
        let to = next[v];
        indegree[to] -= 1;
        if indegree[to] == 0 {
            queue.push_back(to);
        }
    }

    let mut reachable = vec![0i64; n];
    let mut visited = vec![false; n];

    for start in 0..n {
        if indegree[start] > 0 && !visited[start] {
            let mut cycle = Vec::new();
            let mut v = start;

            loop {
                visited[v] = true;
                cycle.push(v);
                v = next[v];
                if v == start {
                    break;
                }
            }

            let cycle_len = cycle.len() as i64;
            for v in cycle {
                reachable[v] = cycle_len;
            }
        }
    }

    for &v in removed_order.iter().rev() {
        reachable[v] = reachable[next[v]] + 1;
    }

    let answer: i64 = reachable.iter().sum();

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
