const MOD: i64 = 998_244_353;

fn mod_pow(mut base: i64, mut exp: u64) -> i64 {
    let mut result = 1i64;
    while exp > 0 {
        if exp & 1 == 1 {
            result = result * base % MOD;
        }
        base = base * base % MOD;
        exp >>= 1;
    }
    result
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: i64 = iter.next().unwrap().parse().unwrap();
    let k: u64 = iter.next().unwrap().parse().unwrap();

    let inv_n = mod_pow(n, (MOD - 2) as u64);
    let ratio = (n - 2).rem_euclid(MOD) * inv_n % MOD;
    let ratio_k = mod_pow(ratio, k);
    let inv_two = (MOD + 1) / 2;

    let answer = ((n + 1) % MOD - (n - 1) % MOD * ratio_k % MOD)
        .rem_euclid(MOD)
        * inv_two
        % MOD;

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
