use std::collections::VecDeque;
use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let s = iter.next().unwrap().as_bytes();
    let t = iter.next().unwrap().as_bytes();

    let len = n + 2;
    let empty_positions = n + 1;

    let mut start_mask = 0usize;
    let mut target_mask = 0usize;

    for i in 0..n {
        if s[i] == b'B' {
            start_mask |= 1usize << i;
        }
        if t[i] == b'B' {
            target_mask |= 1usize << i;
        }
    }

    let start = start_mask * empty_positions + n;
    let target = target_mask * empty_positions + n;

    let state_count = (1usize << len) * empty_positions;
    let mut distance = vec![-1i32; state_count];
    let mut queue = VecDeque::new();

    distance[start] = 0;
    queue.push_back(start);

    while let Some(state) = queue.pop_front() {
        if state == target {
            break;
        }

        let mask = state / empty_positions;
        let empty = state % empty_positions;
        let next_distance = distance[state] + 1;

        for source in 0..=n {
            // The chosen occupied pair must not overlap the empty pair.
            if !(source + 1 < empty || source > empty + 1) {
                continue;
            }

            let pair = (mask >> source) & 3;
            let new_mask = (mask & !(3usize << source)) | (pair << empty);
            let next_state = new_mask * empty_positions + source;

            if distance[next_state] == -1 {
                distance[next_state] = next_distance;
                queue.push_back(next_state);
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", distance[target]).unwrap();
}
