use std::cmp::Reverse;
use std::collections::BinaryHeap;
use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let m: usize = iter.next().unwrap().parse().unwrap();

    let weights: Vec<u64> = (0..n)
        .map(|_| iter.next().unwrap().parse().unwrap())
        .collect();

    let mut graph = vec![Vec::<(usize, u64)>::new(); n];
    for _ in 0..m {
        let u: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let v: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let b: u64 = iter.next().unwrap().parse().unwrap();
        graph[u].push((v, b));
        graph[v].push((u, b));
    }

    let mut dist = vec![u64::MAX; n];
    dist[0] = weights[0];

    let mut heap = BinaryHeap::new();
    heap.push(Reverse((dist[0], 0usize)));

    while let Some(Reverse((current_dist, u))) = heap.pop() {
        if current_dist != dist[u] {
            continue;
        }

        for &(v, edge_weight) in &graph[u] {
            let next_dist = current_dist + edge_weight + weights[v];
            if next_dist < dist[v] {
                dist[v] = next_dist;
                heap.push(Reverse((next_dist, v)));
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for i in 1..n {
        if i > 1 {
            write!(out, " ").unwrap();
        }
        write!(out, "{}", dist[i]).unwrap();
    }
    writeln!(out).unwrap();
}
