use std::cmp::Reverse;
use std::collections::BinaryHeap;
use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_ascii_whitespace();

    let h: usize = iter.next().unwrap().parse().unwrap();
    let w: usize = iter.next().unwrap().parse().unwrap();
    let y_max: u32 = iter.next().unwrap().parse().unwrap();

    let n = h * w;
    let mut elevation = Vec::with_capacity(n);
    for _ in 0..n {
        elevation.push(iter.next().unwrap().parse::<u32>().unwrap());
    }

    let mut discovered = vec![false; n];
    let mut heap = BinaryHeap::<Reverse<(u32, usize)>>::new();

    for row in 0..h {
        for col in 0..w {
            if row == 0 || row + 1 == h || col == 0 || col + 1 == w {
                let index = row * w + col;
                if !discovered[index] {
                    discovered[index] = true;
                    heap.push(Reverse((elevation[index], index)));
                }
            }
        }
    }

    let mut remaining = n;
    let mut output = String::new();

    for year in 1..=y_max {
        while let Some(&Reverse((height, _))) = heap.peek() {
            if height > year {
                break;
            }

            let Reverse((_, index)) = heap.pop().unwrap();
            remaining -= 1;

            let row = index / w;
            let col = index % w;

            if row > 0 {
                let next = index - w;
                if !discovered[next] {
                    discovered[next] = true;
                    heap.push(Reverse((elevation[next], next)));
                }
            }
            if row + 1 < h {
                let next = index + w;
                if !discovered[next] {
                    discovered[next] = true;
                    heap.push(Reverse((elevation[next], next)));
                }
            }
            if col > 0 {
                let next = index - 1;
                if !discovered[next] {
                    discovered[next] = true;
                    heap.push(Reverse((elevation[next], next)));
                }
            }
            if col + 1 < w {
                let next = index + 1;
                if !discovered[next] {
                    discovered[next] = true;
                    heap.push(Reverse((elevation[next], next)));
                }
            }
        }

        output.push_str(&remaining.to_string());
        output.push('\n');
    }

    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());
    writer.write_all(output.as_bytes()).unwrap();
}
