        let next_col = col as isize + dc;

        if next_row >= 0
            && next_row < h as isize
            && next_col >= 0
            && next_col < w as isize
            && grid[next_row as usize][next_col as usize] == b'.'
        {
            row = next_row as usize;
            col = next_col as usize;
        }
