            let win = if current == (aoki + 1) % 3 { 1 } else { 0 };

            if i == 0 {
                next[current] = win;
            } else {
                for previous in 0..3 {
                    if previous != current {
                        next[current] = next[current].max(dp[previous] + win);
                    }
                }
            }
        }
        dp = next;
    }

    let answer = *dp.iter().max().unwrap();
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
