    }

    let prefix_count = n as u64 + 1;
    let mut all_subarray_sum = 0u64;

    for bit in 0..27 {
        let one_count = ones[bit];
        let zero_count = prefix_count - one_count;
        all_subarray_sum += one_count * zero_count * (1u64 << bit);
    }

    let answer = all_subarray_sum - sum_a;

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
