    let size = n + 1;
    let idx = |x: usize, y: usize, z: usize| -> usize {
        (x * size + y) * size + z
    };

    let mut prefix = vec![0_i64; size * size * size];

    for x in 1..=n {
        for y in 1..=n {
            for z in 1..=n {
                let value: i64 = iter.next().unwrap().parse().unwrap();

                prefix[idx(x, y, z)] = value
                    + prefix[idx(x - 1, y, z)]
                    + prefix[idx(x, y - 1, z)]
                    + prefix[idx(x, y, z - 1)]
                    - prefix[idx(x - 1, y - 1, z)]
                    - prefix[idx(x - 1, y, z - 1)]
                    - prefix[idx(x, y - 1, z - 1)]
                    + prefix[idx(x - 1, y - 1, z - 1)];
            }
        }
    }

    let q: usize = iter.next().unwrap().parse().unwrap();
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for _ in 0..q {
        let lx: usize = iter.next().unwrap().parse().unwrap();
        let rx: usize = iter.next().unwrap().parse().unwrap();
        let ly: usize = iter.next().unwrap().parse().unwrap();
        let ry: usize = iter.next().unwrap().parse().unwrap();
        let lz: usize = iter.next().unwrap().parse().unwrap();
        let rz: usize = iter.next().unwrap().parse().unwrap();

        let x0 = lx - 1;
        let y0 = ly - 1;
        let z0 = lz - 1;

        let answer = prefix[idx(rx, ry, rz)]
            - prefix[idx(x0, ry, rz)]
            - prefix[idx(rx, y0, rz)]
            - prefix[idx(rx, ry, z0)]
            + prefix[idx(x0, y0, rz)]
            + prefix[idx(x0, ry, z0)]
            + prefix[idx(rx, y0, z0)]
            - prefix[idx(x0, y0, z0)];

        writeln!(out, "{answer}").unwrap();
