        let rhs = (a2 - 1) * b1;
        rhs.cmp(&lhs)
    });

    let mut dp = vec![i64::MIN; k + 1];
    dp[0] = 1;

    for &(a, b) in functions.iter().rev() {
        for count in (0..k).rev() {
            if dp[count] != i64::MIN {
                dp[count + 1] = dp[count + 1].max(a * dp[count] + b);
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", dp[k]).unwrap();
