use std::io::{self, Read, Write};

fn dfs(
    index: usize,
    sum: usize,
    n: usize,
    k: usize,
    limits: &[usize],
    sequence: &mut [usize],
    output: &mut String,
) {
    if index == n {
        if sum % k == 0 {
            for (i, value) in sequence.iter().enumerate() {
                if i > 0 {
                    output.push(' ');
                }
                output.push_str(&value.to_string());
            }
            output.push('\n');
        }
        return;
    }

    for value in 1..=limits[index] {
        sequence[index] = value;
        dfs(index + 1, sum + value, n, k, limits, sequence, output);
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

