use std::collections::BTreeSet;
use std::io::{self, Read, Write};
use std::ops::Bound::{Excluded, Unbounded};

fn remove_wall(
    r: usize,
    c: usize,
    rows: &mut [BTreeSet<usize>],
    cols: &mut [BTreeSet<usize>],
    remaining: &mut usize,
) {
    if rows[r].remove(&c) {
        cols[c].remove(&r);
        *remaining -= 1;
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let h: usize = it.next().unwrap().parse().unwrap();
    let w: usize = it.next().unwrap().parse().unwrap();
    let q: usize = it.next().unwrap().parse().unwrap();

    let mut rows: Vec<BTreeSet<usize>> =
        (0..h).map(|_| (0..w).collect()).collect();
    let mut cols: Vec<BTreeSet<usize>> =
        (0..w).map(|_| (0..h).collect()).collect();

    let mut remaining = h * w;

    for _ in 0..q {
        let r: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
        let c: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;

        if rows[r].contains(&c) {
            remove_wall(r, c, &mut rows, &mut cols, &mut remaining);
            continue;
        }

        let left = rows[r].range(..c).next_back().copied();
        let right = rows[r]
            .range((Excluded(c), Unbounded))
            .next()
            .copied();
        let up = cols[c].range(..r).next_back().copied();
        let down = cols[c]
            .range((Excluded(r), Unbounded))
            .next()
            .copied();

        if let Some(nc) = left {
            remove_wall(r, nc, &mut rows, &mut cols, &mut remaining);
        }
        if let Some(nc) = right {
            remove_wall(r, nc, &mut rows, &mut cols, &mut remaining);
        }
        if let Some(nr) = up {
            remove_wall(nr, c, &mut rows, &mut cols, &mut remaining);
        }
        if let Some(nr) = down {
            remove_wall(nr, c, &mut rows, &mut cols, &mut remaining);
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{remaining}").unwrap();
}
