        let forbidden = sums.get(&(prefix - k)).copied().unwrap_or(0);
        answer = (total - forbidden + MOD) % MOD;

        let entry = sums.entry(prefix).or_insert(0);
        *entry = (*entry + answer) % MOD;
        total = (total + answer) % MOD;
