use std::io::{self, Read, Write};

fn count_feasible_starts(prefix: &[i64], n: usize, k: usize, x: i64) -> usize {
    let m = 2 * n;
    let sentinel = m + 1;
    let len = m + 2;

    // next[p] is the smallest boundary q > p such that
    // the mass of pieces between p and q is at least x.
    let mut jump = vec![sentinel; len];
    let mut q = 1usize;

    for p in 0..=m {
        if q <= p {
            q = p + 1;
        }
        while q <= m && prefix[q] - prefix[p] < x {
            q += 1;
        }
        jump[p] = if q <= m { q } else { sentinel };
    }
    jump[sentinel] = sentinel;

    let mut starts: Vec<usize> = (0..n).collect();
    let mut positions: Vec<usize> = (0..n).collect();
    let mut squared = vec![sentinel; len];

    let mut exponent = k;
    while exponent > 0 {
        if exponent & 1 == 1 {
            let mut kept = 0usize;
            for i in 0..starts.len() {
                let start = starts[i];
                let next_position = jump[positions[i]];
                if next_position <= start + n {
                    starts[kept] = start;
                    positions[kept] = next_position;
                    kept += 1;
                }
            }
            starts.truncate(kept);
            positions.truncate(kept);

            if starts.is_empty() {
                return 0;
            }
        }

        exponent >>= 1;
        if exponent == 0 {
            break;
        }

        for i in 0..len {
            squared[i] = jump[jump[i]];
        }
        std::mem::swap(&mut jump, &mut squared);
    }

    starts.len()
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let k: usize = iter.next().unwrap().parse().unwrap();

    let mut a = vec![0i64; n];
    let mut total = 0i64;
    for value in &mut a {
        *value = iter.next().unwrap().parse().unwrap();
        total += *value;
    }

    let mut prefix = vec![0i64; 2 * n + 1];
    for i in 0..2 * n {
        prefix[i + 1] = prefix[i] + a[i % n];
    }

    let mut low = 0i64;
    let mut high = total / k as i64 + 1;

    while high - low > 1 {
        let mid = low + (high - low) / 2;
        if count_feasible_starts(&prefix, n, k, mid) > 0 {
            low = mid;
        } else {
            high = mid;
        }
    }

    let cuttable = count_feasible_starts(&prefix, n, k, low);
    let never_cut = n - cuttable;

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{} {}", low, never_cut).unwrap();
}
