use std::io::{self, Read, Write};

const MOD: u64 = 998_244_353;

struct Solver {
    n: u64,
    sqrt_n: usize,
    small: Vec<[u64; 3]>,
    large: Vec<[u64; 3]>,
    primes: Vec<u64>,
    prefix_total: Vec<u64>,
    prefix_bad: Vec<u64>,
    combinations: Vec<u64>,
    m_mod: u64,
}

impl Solver {
    fn initial_counts(x: u64) -> [u64; 3] {
        let count_0 = x / 3;
        let count_1 = (x + 2) / 3;
        let count_2 = (x + 1) / 3;
        [count_0, count_1.saturating_sub(1), count_2]
    }

    fn get_counts_from(
        n: u64,
        sqrt_n: usize,
        small: &[[u64; 3]],
        large: &[[u64; 3]],
        x: u64,
    ) -> [u64; 3] {
        if x <= sqrt_n as u64 {
            small[x as usize]
        } else {
            large[(n / x) as usize]
        }
    }

    fn new(n: u64, m: u64) -> Self {
        let mut sqrt_n = (n as f64).sqrt() as u64;
        while (sqrt_n + 1) <= n / (sqrt_n + 1) {
            sqrt_n += 1;
        }
        while sqrt_n > n / sqrt_n {
            sqrt_n -= 1;
        }
        let s = sqrt_n as usize;

        let mut is_prime = vec![true; s + 1];
        if s >= 0 {
            is_prime[0] = false;
        }
        if s >= 1 {
            is_prime[1] = false;
        }
        let mut i = 2usize;
        while i * i <= s {
            if is_prime[i] {
                let mut j = i * i;
                while j <= s {
                    is_prime[j] = false;
                    j += i;
                }
            }
            i += 1;
        }

        let primes: Vec<u64> = (2..=s)
            .filter(|&x| is_prime[x])
            .map(|x| x as u64)
            .collect();

        let mut small = vec![[0u64; 3]; s + 1];
        for x in 0..=s {
            small[x] = Self::initial_counts(x as u64);
        }

        let mut large = vec![[0u64; 3]; s + 1];
        for idx in 1..=s {
            large[idx] = Self::initial_counts(n / idx as u64);
        }

        for &p in &primes {
            if p > n / p {
                break;
            }
            let p2 = p * p;
            let before = small[(p - 1) as usize];

            let mut idx = 1usize;
            while idx <= s {
                let x = n / idx as u64;
                if x <= s as u64 || x < p2 {
                    break;
                }

                let y = x / p;
                let yc = Self::get_counts_from(n, s, &small, &large, y);
                let delta = [
                    yc[0] - before[0],
                    yc[1] - before[1],
                    yc[2] - before[2],
                ];

                let mut cur = large[idx];
                match p % 3 {
                    1 => {
                        cur[0] -= delta[0];
                        cur[1] -= delta[1];
                        cur[2] -= delta[2];
                    }
                    2 => {
                        cur[0] -= delta[0];
                        cur[1] -= delta[2];
                        cur[2] -= delta[1];
                    }
                    _ => {
                        cur[0] -= delta[0] + delta[1] + delta[2];
                    }
                }
                large[idx] = cur;
                idx += 1;
            }

            if p2 <= s as u64 {
                for x in (p2 as usize..=s).rev() {
                    let yc = small[x / p as usize];
                    let delta = [
                        yc[0] - before[0],
                        yc[1] - before[1],
                        yc[2] - before[2],
                    ];

                    match p % 3 {
                        1 => {
                            small[x][0] -= delta[0];
                            small[x][1] -= delta[1];
                            small[x][2] -= delta[2];
                        }
                        2 => {
                            small[x][0] -= delta[0];
                            small[x][1] -= delta[2];
                            small[x][2] -= delta[1];
                        }
                        _ => {
                            small[x][0] -= delta[0] + delta[1] + delta[2];
                        }
                    }
                }
            }
        }

        let m_mod = m % MOD;
        let mut prefix_total = vec![0u64; primes.len() + 1];
        let mut prefix_bad = vec![0u64; primes.len() + 1];

        for (idx, &p) in primes.iter().enumerate() {
            prefix_total[idx + 1] = (prefix_total[idx] + m_mod) % MOD;
            let bad_prime_value = if p % 3 == 0 || p % 3 == 1 {
                m_mod
            } else {
                0
            };
            prefix_bad[idx + 1] = (prefix_bad[idx] + bad_prime_value) % MOD;
        }

        let max_exp = 64usize;
        let mut inverses = vec![0u64; max_exp + 1];
        inverses[1] = 1;
        for e in 2..=max_exp {
            inverses[e] =
                MOD - (MOD / e as u64) * inverses[(MOD as usize) % e] % MOD;
        }

        let mut combinations = vec![0u64; max_exp + 1];
        combinations[0] = 1;
        for e in 1..=max_exp {
            let factor = (m_mod + e as u64 - 1) % MOD;
            combinations[e] =
                combinations[e - 1] * factor % MOD * inverses[e] % MOD;
        }

        Self {
            n,
            sqrt_n: s,
            small,
            large,
            primes,
            prefix_total,
            prefix_bad,
            combinations,
            m_mod,
        }
    }

    fn counts(&self, x: u64) -> [u64; 3] {
        if x <= self.sqrt_n as u64 {
            self.small[x as usize]
        } else {
            self.large[(self.n / x) as usize]
        }
    }

    fn prime_sum(&self, x: u64, bad: bool) -> u64 {
        if x < 2 {
            return 0;
        }
        let c = self.counts(x);
        if bad {
            ((c[0] % MOD + c[1] % MOD) % MOD) * self.m_mod % MOD
        } else {
            let count = (c[0] % MOD + c[1] % MOD + c[2] % MOD) % MOD;
            count * self.m_mod % MOD
        }
    }

    fn prime_power_value(&self, p: u64, e: usize, bad: bool) -> u64 {
        if !bad {
            return self.combinations[e];
        }

        let allowed = match p % 3 {
            0 => true,
            1 => e % 3 != 2,
            _ => e % 2 == 0,
        };

        if allowed {
            self.combinations[e]
        } else {
            0
        }
    }

    fn summatory(&self, x: u64, prime_index: usize, bad: bool) -> u64 {
        let prefix = if bad {
            self.prefix_bad[prime_index]
        } else {
            self.prefix_total[prime_index]
        };

        let mut result = (1 + self.prime_sum(x, bad) + MOD - prefix) % MOD;

        let mut i = prime_index;
        while i < self.primes.len() {
            let p = self.primes[i];
            if p > x / p {
                break;
            }

            let mut power = p;
            let mut exponent = 1usize;

            while power <= x / p {
                let coefficient = self.prime_power_value(p, exponent, bad);
                if coefficient != 0 {
                    let sub = self.summatory(x / power, i + 1, bad);
                    let non_empty = (sub + MOD - 1) % MOD;
                    result = (result + coefficient * non_empty) % MOD;
                }

                let next_coefficient =
                    self.prime_power_value(p, exponent + 1, bad);
                result += next_coefficient;
                if result >= MOD {
                    result -= MOD;
                }

                power *= p;
                exponent += 1;
            }

            i += 1;
        }

        result
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: u64 = it.next().unwrap().parse().unwrap();
    let m: u64 = it.next().unwrap().parse().unwrap();

    let solver = Solver::new(n, m);
    let total = solver.summatory(n, 0, false);
    let bad = solver.summatory(n, 0, true);
    let answer = (total + MOD - bad) % MOD;

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", answer).unwrap();
}
