use std::io::{self, Read, Write};

struct SegmentTree {
    n: usize,
    sum: Vec<i64>,
    min: Vec<i64>,
    max: Vec<i64>,
    lazy: Vec<i64>,
}

impl SegmentTree {
    const NONE: i64 = i64::MIN;

    fn new(values: &[i64]) -> Self {
        let n = values.len();
        let size = 4 * n + 5;
        let mut seg = Self {
            n,
            sum: vec![0; size],
            min: vec![0; size],
            max: vec![0; size],
            lazy: vec![Self::NONE; size],
        };
        seg.build(1, 0, n - 1, values);
        seg
    }

    fn build(&mut self, node: usize, left: usize, right: usize, values: &[i64]) {
        if left == right {
            let value = values[left];
            self.sum[node] = value;
            self.min[node] = value;
            self.max[node] = value;
            return;
        }

        let mid = (left + right) / 2;
        self.build(node * 2, left, mid, values);
        self.build(node * 2 + 1, mid + 1, right, values);
        self.pull(node);
    }

    fn pull(&mut self, node: usize) {
        self.sum[node] = self.sum[node * 2] + self.sum[node * 2 + 1];
        self.min[node] = self.min[node * 2].min(self.min[node * 2 + 1]);
        self.max[node] = self.max[node * 2].max(self.max[node * 2 + 1]);
    }

    fn apply(&mut self, node: usize, left: usize, right: usize, value: i64) {
        self.sum[node] = value * (right - left + 1) as i64;
        self.min[node] = value;
        self.max[node] = value;
        self.lazy[node] = value;
    }

    fn push(&mut self, node: usize, left: usize, right: usize) {
        let value = self.lazy[node];
        if value == Self::NONE || left == right {
            return;
        }

        let mid = (left + right) / 2;
        self.apply(node * 2, left, mid, value);
        self.apply(node * 2 + 1, mid + 1, right, value);
        self.lazy[node] = Self::NONE;
    }

    fn assign(&mut self, query_left: usize, query_right: usize, value: i64) {
        self.assign_rec(1, 0, self.n - 1, query_left, query_right, value);
    }

    fn assign_rec(
        &mut self,
        node: usize,
        left: usize,
        right: usize,
        query_left: usize,
        query_right: usize,
        value: i64,
    ) {
        if query_right < left || right < query_left {
            return;
        }
        if query_left <= left && right <= query_right {
            self.apply(node, left, right, value);
            return;
        }

        self.push(node, left, right);
        let mid = (left + right) / 2;
        self.assign_rec(node * 2, left, mid, query_left, query_right, value);
        self.assign_rec(
            node * 2 + 1,
            mid + 1,
            right,
            query_left,
            query_right,
            value,
        );
        self.pull(node);
    }

    fn range_sum(&mut self, query_left: usize, query_right: usize) -> i64 {
        self.sum_rec(1, 0, self.n - 1, query_left, query_right)
    }

    fn sum_rec(
        &mut self,
        node: usize,
        left: usize,
        right: usize,
        query_left: usize,
        query_right: usize,
    ) -> i64 {
        if query_right < left || right < query_left {
            return 0;
        }
        if query_left <= left && right <= query_right {
            return self.sum[node];
        }

        self.push(node, left, right);
        let mid = (left + right) / 2;
        self.sum_rec(node * 2, left, mid, query_left, query_right)
            + self.sum_rec(
                node * 2 + 1,
                mid + 1,
                right,
                query_left,
                query_right,
            )
    }

    fn point(&mut self, index: usize) -> i64 {
        self.range_sum(index, index)
    }

    fn first_greater(&mut self, value: i64) -> Option<usize> {
        if self.max[1] <= value {
            None
        } else {
            Some(self.first_greater_rec(1, 0, self.n - 1, value))
        }
    }

    fn first_greater_rec(
        &mut self,
        node: usize,
        left: usize,
        right: usize,
        value: i64,
    ) -> usize {
        if left == right {
            return left;
        }

        self.push(node, left, right);
        let mid = (left + right) / 2;
        if self.max[node * 2] > value {
            self.first_greater_rec(node * 2, left, mid, value)
        } else {
            self.first_greater_rec(node * 2 + 1, mid + 1, right, value)
        }
    }

    fn last_less(&mut self, value: i64) -> Option<usize> {
        if self.min[1] >= value {
            None
        } else {
            Some(self.last_less_rec(1, 0, self.n - 1, value))
        }
    }

    fn last_less_rec(
        &mut self,
        node: usize,
        left: usize,
        right: usize,
        value: i64,
    ) -> usize {
        if left == right {
            return left;
        }

        self.push(node, left, right);
        let mid = (left + right) / 2;
        if self.min[node * 2 + 1] < value {
            self.last_less_rec(node * 2 + 1, mid + 1, right, value)
        } else {
            self.last_less_rec(node * 2, left, mid, value)
        }
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let mut transformed = Vec::with_capacity(n);

    for i in 0..n {
        let x: i64 = iter.next().unwrap().parse().unwrap();
        transformed.push(x - i as i64);
    }

    let mut seg = SegmentTree::new(&transformed);
    let q: usize = iter.next().unwrap().parse().unwrap();
    let mut answer: i64 = 0;

    for _ in 0..q {
        let t: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let g_input: i64 = iter.next().unwrap().parse().unwrap();
        let g = g_input - t as i64;
        let current = seg.point(t);

        if current > g {
            let left = seg.first_greater(g).unwrap();
            let old_sum = seg.range_sum(left, t);
            let len = (t - left + 1) as i64;
            answer += old_sum - g * len;
            seg.assign(left, t, g);
        } else if current < g {
            let right = seg.last_less(g).unwrap();
            let old_sum = seg.range_sum(t, right);
            let len = (right - t + 1) as i64;
            answer += g * len - old_sum;
            seg.assign(t, right, g);
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
