use std::fmt::Write as FmtWrite;
use std::io::{self, Read, Write};

fn extended_gcd(a: i64, b: i64) -> (i64, i64, i64) {
    if b == 0 {
        (a, 1, 0)
    } else {
        let (g, x, y) = extended_gcd(b, a % b);
        (g, y, x - (a / b) * y)
    }
}

fn mod_inverse(a: i64, modulus: i64) -> i64 {
    let (_, x, _) = extended_gcd(a, modulus);
    x.rem_euclid(modulus)
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let p: Vec<usize> = (0..n)
        .map(|_| it.next().unwrap().parse::<usize>().unwrap() - 1)
        .collect();
    let a: Vec<usize> = (0..n)
        .map(|_| it.next().unwrap().parse::<usize>().unwrap())
        .collect();

    let mut spf = vec![0usize; n + 1];
    if n >= 1 {
        spf[1] = 1;
    }
    for i in 2..=n {
        if spf[i] == 0 {
            spf[i] = i;
            let mut j = i;
            while j <= n {
                if spf[j] == 0 {
                    spf[j] = i;
                }
                j += i;
            }
        }
    }

    // For each prime, store the largest prime-power modulus fixed so far,
    // and the residue of the operation count modulo that prime power.
    let mut max_power = vec![0usize; n + 1];
    let mut residue = vec![0usize; n + 1];

    let mut visited = vec![false; n];
    let mut answer = vec![0usize; n];

    for start in 0..n {
        if visited[start] {
            continue;
        }

        let mut cycle = Vec::new();
        let mut current = start;
        loop {
            cycle.push(current);
            visited[current] = true;
            current = p[current];
            if current == start {
                break;
            }
        }

        let len = cycle.len();

        let mut factors = Vec::<(usize, usize)>::new();
        let mut value = len;
        while value > 1 {
            let prime = spf[value];
            let mut prime_power = 1usize;
            while value % prime == 0 {
                value /= prime;
                prime_power *= prime;
            }
            factors.push((prime, prime_power));
        }

        // Compute the currently required residue modulo gcd(M, len),
        // where M is the accumulated modulus.
        let mut required = 0i64;
        let mut gcd_modulus = 1i64;

        for &(prime, prime_power) in &factors {
            let old_power = max_power[prime];
            if old_power == 0 {
                continue;
            }

            let component = old_power.min(prime_power) as i64;
            let target = (residue[prime] % component as usize) as i64;

            let delta = (target - required).rem_euclid(component);
            let inverse = mod_inverse(gcd_modulus.rem_euclid(component), component);
            let multiplier = (delta * inverse).rem_euclid(component);

            required += gcd_modulus * multiplier;
            gcd_modulus *= component;
            required = required.rem_euclid(gcd_modulus);
        }

        let step = gcd_modulus as usize;
        let first = required as usize;

        let mut best_shift = first;
        let mut best_value = a[cycle[first]];

        let mut shift = first + step;
        while shift < len {
            let candidate = a[cycle[shift]];
            if candidate < best_value {
                best_value = candidate;
                best_shift = shift;
            }
            shift += step;
        }

        // Add the newly fixed congruence k ≡ best_shift (mod len).
        for &(prime, prime_power) in &factors {
            if prime_power > max_power[prime] {
                max_power[prime] = prime_power;
                residue[prime] = best_shift % prime_power;
            }
        }

        for index in 0..len {
            answer[cycle[index]] = a[cycle[(index + best_shift) % len]];
        }
    }

    let mut output = String::new();
    for i in 0..n {
        if i > 0 {
            output.push(' ');
        }
        write!(output, "{}", answer[i]).unwrap();
    }
    output.push('\n');

    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());
    writer.write_all(output.as_bytes()).unwrap();
}
