use std::io::{self, Read, Write};

fn is_abc(s: &[u8], i: usize) -> bool {
    i + 2 < s.len() && s[i] == b'A' && s[i + 1] == b'B' && s[i + 2] == b'C'
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let q: usize = iter.next().unwrap().parse().unwrap();
    let mut s = iter.next().unwrap().as_bytes().to_vec();

    let mut count = (0..n - 2).filter(|&i| is_abc(&s, i)).count() as i32;
    let mut output = String::new();

    for _ in 0..q {
        let x: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let c = iter.next().unwrap().as_bytes()[0];

        let start = x.saturating_sub(2);
        let end = x.min(n - 3);

        for i in start..=end {
            if is_abc(&s, i) {
                count -= 1;
            }
        }

        s[x] = c;

        for i in start..=end {
            if is_abc(&s, i) {
                count += 1;
            }
        }

        output.push_str(&format!("{count}\n"));
    }

    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());
    writer.write_all(output.as_bytes()).unwrap();
}
