use std::io::{self, Read, Write};

const MOD: u64 = 998_244_353;

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let m: usize = it.next().unwrap().parse().unwrap();
    let k: usize = it.next().unwrap().parse().unwrap();

    let mut edges = Vec::with_capacity(m);
    for _ in 0..m {
        let x: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
        let y: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
        edges.push((x, y));
    }

    // q[r] is the number of ways to be at vertex (r + time) mod N.
    // Moving along a cycle edge leaves this rotated coordinate unchanged.
    let mut q = vec![0u64; n];
    q[0] = 1;

    let mut values = vec![0u64; m];
    let mut answer = 1u64;

    for time in 0..k {
        let shift = time % n;

        // All shortcut transitions must use the state before this step.
        for (i, &(x, _)) in edges.iter().enumerate() {
            let index = (x + n - shift) % n;
            values[i] = q[index];
        }

        let next_shift = (time + 1) % n;
        for (i, &(_, y)) in edges.iter().enumerate() {
            let value = values[i];
            let index = (y + n - next_shift) % n;

            q[index] += value;
            if q[index] >= MOD {
                q[index] -= MOD;
            }

            answer += value;
            if answer >= MOD {
                answer -= MOD;
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
