use std::cmp::Ordering;
use std::fmt::Write as FmtWrite;
use std::io::{self, Read, Write as IoWrite};

#[derive(Clone, Copy)]
struct Line {
    a: i128,
    b: i128,
    d: i128, // C - 1
}

#[derive(Clone, Copy)]
struct HullEntry {
    line: Line,
    start: Option<(i128, i128)>, // Rational start point, numerator / denominator
}

fn ratio_cmp(n1: i128, d1: i128, n2: i128, d2: i128) -> Ordering {
    (n1 * d2).cmp(&(n2 * d1))
}

fn fraction_le(n1: i128, d1: i128, n2: i128, d2: i128) -> bool {
    n1 * d2 <= n2 * d1
}

fn ceil_fraction(n: i128, d: i128) -> i128 {
    let q = n / d;
    let r = n % d;
    if r > 0 { q + 1 } else { q }
}

// Returns sum_{i=0}^{n-1} floor((a*i+b)/m), with all arguments nonnegative.
fn floor_sum(mut n: i128, mut m: i128, mut a: i128, mut b: i128) -> i128 {
    let mut ans = 0i128;

    loop {
        if a >= m {
            ans += (n - 1) * n * (a / m) / 2;
            a %= m;
        }
        if b >= m {
            ans += n * (b / m);
            b %= m;
        }

        let y_max = a * n + b;
        if y_max < m {
            break;
        }

        n = y_max / m;
        b = y_max % m;
        std::mem::swap(&mut m, &mut a);
    }

    ans
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let t: usize = it.next().unwrap().parse().unwrap();
    let mut output = String::new();

    for _ in 0..t {
        let n: usize = it.next().unwrap().parse().unwrap();
        let mut lines = Vec::with_capacity(n);

        for _ in 0..n {
            let a: i128 = it.next().unwrap().parse().unwrap();
            let b: i128 = it.next().unwrap().parse().unwrap();
            let c: i128 = it.next().unwrap().parse().unwrap();
            lines.push(Line { a, b, d: c - 1 });
        }

        // The line is (d - a*x) / b. Its slope is -a/b.
        // Sort by a/b ascending, i.e. by slope descending.
        lines.sort_unstable_by(|x, y| {
            let slope_cmp = ratio_cmp(x.a, x.b, y.a, y.b);
            if slope_cmp != Ordering::Equal {
                slope_cmp
            } else {
                ratio_cmp(x.d, x.b, y.d, y.b)
            }
        });

        // For equal slopes, retain only the line with the smallest intercept.
        let mut unique: Vec<Line> = Vec::with_capacity(lines.len());
        for line in lines {
            if let Some(last) = unique.last() {
                if last.a * line.b == line.a * last.b {
                    continue;
                }
            }
            unique.push(line);
        }

        // Construct the lower envelope.
        let mut hull: Vec<HullEntry> = Vec::with_capacity(unique.len());

        for line in unique {
            loop {
                if hull.is_empty() {
                    hull.push(HullEntry { line, start: None });
                    break;
                }

                let old = hull.last().unwrap().line;

                // Intersection:
                // (d_old - a_old*x)/b_old = (d_new - a_new*x)/b_new
                let num = line.d * old.b - old.d * line.b;
                let den = line.a * old.b - old.a * line.b;

                if hull.len() == 1 {
                    hull.push(HullEntry {
                        line,
                        start: Some((num, den)),
                    });
                    break;
                }

                let (start_num, start_den) = hull.last().unwrap().start.unwrap();
                if fraction_le(num, den, start_num, start_den) {
                    hull.pop();
                } else {
                    hull.push(HullEntry {
                        line,
                        start: Some((num, den)),
                    });
                    break;
                }
            }
        }

        let mut answer = 0i128;

        for j in 0..hull.len() {
            let line = hull[j].line;

            let mut left = 1i128;
            if let Some((num, den)) = hull[j].start {
                left = left.max(ceil_fraction(num, den));
            }

            // floor((d-a*x)/b) >= 1 exactly when d-a*x >= b.
            let mut right = if line.d >= line.b {
                (line.d - line.b) / line.a
            } else {
                0
            };

            if j + 1 < hull.len() {
                let (num, den) = hull[j + 1].start.unwrap();
                right = right.min(ceil_fraction(num, den) - 1);
            }

            if left <= right {
                let count = right - left + 1;
                // Reverse the range so the numerator has a nonnegative slope:
                // x = right-i, hence d-a*x = (d-a*right)+a*i.
                let base = line.d - line.a * right;
                answer += floor_sum(count, line.b, line.a, base);
            }
        }

        writeln!(&mut output, "{answer}").unwrap();
    }

    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());
    writer.write_all(output.as_bytes()).unwrap();
}
