use std::io::{self, Read, Write};

fn lower_bound(values: &[i64], target: i64) -> usize {
    let mut left = 0;
    let mut right = values.len();
    while left < right {
        let mid = left + (right - left) / 2;
        if values[mid] < target {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    left
}

fn range_cost(values: &[i64], prefix: &[i64], left: usize, right: usize, target: i64) -> i64 {
    let p = lower_bound(values, target).max(left).min(right);
    target * (p - left) as i64 - (prefix[p] - prefix[left])
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let m: usize = iter.next().unwrap().parse().unwrap();
    let k: i64 = iter.next().unwrap().parse().unwrap();

    let mut a = Vec::with_capacity(n);
    let mut sum = 0_i64;
    for _ in 0..n {
        let value: i64 = iter.next().unwrap().parse().unwrap();
        a.push(value);
        sum += value;
    }

    let remaining = k - sum;

    if m == n {
        let output = vec!["0"; n].join(" ");
        let stdout = io::stdout();
        let mut out = io::BufWriter::new(stdout.lock());
        writeln!(out, "{}", output).unwrap();
        return;
    }

    let mut indexed: Vec<(i64, usize)> = a
        .iter()
        .copied()
        .enumerate()
        .map(|(index, value)| (value, index))
        .collect();
    indexed.sort_unstable();

    let values: Vec<i64> = indexed.iter().map(|&(value, _)| value).collect();
    let mut position = vec![0usize; n];
    for (pos, &(_, original_index)) in indexed.iter().enumerate() {
        position[original_index] = pos;
    }

    let mut prefix = vec![0_i64; n + 1];
    for i in 0..n {
        prefix[i + 1] = prefix[i] + values[i];
    }

    let top_start = n - m;
    let extended_start = top_start - 1;
    let mut answers = vec![0_i64; n];

    for i in 0..n {
        let is_guaranteed = |x: i64| -> bool {
            let target = a[i] + x + 1;
            let needed = if position[i] < top_start {
                range_cost(&values, &prefix, top_start, n, target)
            } else {
                range_cost(&values, &prefix, extended_start, n, target) - (x + 1)
            };
            needed > remaining - x
        };

        if !is_guaranteed(remaining) {
            answers[i] = -1;
            continue;
        }

        let mut low = -1_i64;
        let mut high = remaining;
        while high - low > 1 {
            let mid = low + (high - low) / 2;
            if is_guaranteed(mid) {
                high = mid;
            } else {
                low = mid;
            }
        }
        answers[i] = high;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    for i in 0..n {
        if i > 0 {
            write!(out, " ").unwrap();
        }
        write!(out, "{}", answers[i]).unwrap();
    }
    writeln!(out).unwrap();
}
