use std::io::{self, Read, Write};

#[derive(Clone, Copy)]
struct Line {
    slope: i64,
    intercept: i64,
}

impl Line {
    fn eval(&self, x: i64) -> i64 {
        self.slope * x + self.intercept
    }
}

fn is_redundant(a: Line, b: Line, c: Line) -> bool {
    let left = (a.intercept as i128 - b.intercept as i128)
        * (c.slope as i128 - b.slope as i128);
    let right = (b.intercept as i128 - c.intercept as i128)
        * (b.slope as i128 - a.slope as i128);
    left >= right
}

fn main() {
    let mut input = String::new();
    io::stdin().lock().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let capacity: usize = iter.next().unwrap().parse().unwrap();

    let neg_inf = i64::MIN / 4;
    let mut dp = vec![neg_inf; capacity + 1];
    dp[0] = 0;

    let mut hull: Vec<Line> = Vec::with_capacity(capacity + 1);

    for _ in 0..n {
        let weight: usize = iter.next().unwrap().parse().unwrap();
        let value: i64 = iter.next().unwrap().parse().unwrap();

        let mut next = vec![neg_inf; capacity + 1];

        for residue in 0..weight {
            if residue > capacity {
                break;
            }

            hull.clear();
            let mut head = 0usize;
            let max_pos = (capacity - residue) / weight;

            for j in 0..=max_pos {
                let index = residue + j * weight;
                let j64 = j as i64;

                if dp[index] != neg_inf {
                    let line = Line {
                        slope: 2 * j64,
                        intercept: dp[index] - j64 * value - j64 * j64,
                    };

                    while hull.len() >= head + 2
                        && is_redundant(
                            hull[hull.len() - 2],
                            hull[hull.len() - 1],
                            line,
                        )
                    {
                        hull.pop();
                    }
                    hull.push(line);
                }

                if head < hull.len() {
                    while head + 1 < hull.len()
                        && hull[head].eval(j64) <= hull[head + 1].eval(j64)
                    {
                        head += 1;
                    }

                    next[index] =
                        j64 * value - j64 * j64 + hull[head].eval(j64);
                }
            }
        }

        dp = next;
    }

    let answer = *dp.iter().max().unwrap();
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
