use std::collections::VecDeque;
use std::io::{self, Read, Write};

const NONE: usize = usize::MAX;
const INF: usize = usize::MAX / 4;

fn dfs_matching(
    u: usize,
    adj: &[Vec<usize>],
    pair_left: &mut [usize],
    pair_right: &mut [usize],
    dist: &mut [usize],
) -> bool {
    for &v in &adj[u] {
        let next = pair_right[v];
        if next == NONE
            || (dist[next] == dist[u] + 1
                && dfs_matching(next, adj, pair_left, pair_right, dist))
        {
            pair_left[u] = v;
            pair_right[v] = u;
            return true;
        }
    }
    dist[u] = INF;
    false
}

fn maximum_matching(adj: &[Vec<usize>]) -> usize {
    let n = adj.len();
    let mut pair_left = vec![NONE; n];
    let mut pair_right = vec![NONE; n];
    let mut dist = vec![INF; n];
    let mut matching = 0;

    loop {
        let mut queue = VecDeque::new();
        for u in 0..n {
            if pair_left[u] == NONE {
                dist[u] = 0;
                queue.push_back(u);
            } else {
                dist[u] = INF;
            }
        }

        while let Some(u) = queue.pop_front() {
            for &v in &adj[u] {
                let next = pair_right[v];
                if next != NONE && dist[next] == INF {
                    dist[next] = dist[u] + 1;
                    queue.push_back(next);
                }
            }
        }

        let mut augmented = 0;
        for u in 0..n {
            if pair_left[u] == NONE
                && dfs_matching(u, adj, &mut pair_left, &mut pair_right, &mut dist)
            {
                augmented += 1;
            }
        }

        if augmented == 0 {
            break;
        }
        matching += augmented;
    }

    matching
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let mut edges = Vec::with_capacity(n);
    let mut reach = vec![vec![false; 26]; 26];

    for i in 0..26 {
        reach[i][i] = true;
    }

    for _ in 0..n {
        let s = iter.next().unwrap().as_bytes();
        let a = (s[0] - b'A') as usize;
        let b = (s[1] - b'A') as usize;
        edges.push((a, b));
        reach[a][b] = true;
    }

    for k in 0..26 {
        for i in 0..26 {
            if reach[i][k] {
                for j in 0..26 {
                    if reach[k][j] {
                        reach[i][j] = true;
                    }
                }
            }
        }
    }

    let mut component = vec![NONE; 26];
    let mut component_count = 0;

    for i in 0..26 {
        if component[i] != NONE {
            continue;
        }
        for j in 0..26 {
            if component[j] == NONE && reach[i][j] && reach[j][i] {
                component[j] = component_count;
            }
        }
        component_count += 1;
    }

    let mut component_reach = vec![vec![false; component_count]; component_count];
    for i in 0..26 {
        for j in 0..26 {
            if reach[i][j] {
                component_reach[component[i]][component[j]] = true;
            }
        }
    }

    let mut has_internal_edge = vec![false; component_count];
    let mut requirements: Vec<(usize, usize)> = Vec::new();

    for &(a, b) in &edges {
        let ca = component[a];
        let cb = component[b];
        if ca == cb {
            has_internal_edge[ca] = true;
        } else {
            requirements.push((ca, cb));
        }
    }

    for c in 0..component_count {
        if has_internal_edge[c] {
            requirements.push((c, c));
        }
    }

    let m = requirements.len();
    let mut adjacency = vec![Vec::new(); m];

    for i in 0..m {
        let end_component = requirements[i].1;
        for j in 0..m {
            if i != j {
                let start_component = requirements[j].0;
                if component_reach[end_component][start_component] {
                    adjacency[i].push(j);
                }
            }
        }
    }

    let matching = maximum_matching(&adjacency);
    let answer = m - matching;

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", answer).unwrap();
}
