        for c in 0..n {
            let depth = r.min(c).min(n - 1 - r).min(n - 1 - c) + 1;

            let (sr, sc) = match depth % 4 {
                0 => (r, c),
                1 => (n - 1 - c, r),
                2 => (n - 1 - r, n - 1 - c),
                _ => (c, n - 1 - r),
            };

            output.push(grid[sr][sc]);
        }
        output.push(b'\n');
    }

    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());
    writer.write_all(&output).unwrap();
}
