use std::cmp::Reverse;
use std::collections::BinaryHeap;
use std::io::{self, Read, Write};

const INF: i64 = i64::MAX / 4;

fn dijkstra(start: usize, graph: &[Vec<(usize, i64)>]) -> Vec<i64> {
    let n = graph.len();
    let mut dist = vec![INF; n];
    let mut heap = BinaryHeap::new();

    dist[start] = 0;
    heap.push(Reverse((0_i64, start)));

    while let Some(Reverse((d, v))) = heap.pop() {
        if d != dist[v] {
            continue;
        }

        for &(to, cost) in &graph[v] {
            let nd = d + cost;
            if nd < dist[to] {
                dist[to] = nd;
                heap.push(Reverse((nd, to)));
            }
        }
    }

    dist
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let m: usize = it.next().unwrap().parse().unwrap();

    let mut edges = Vec::with_capacity(m);
    let mut graph = vec![Vec::<(usize, i64)>::new(); n];

    for _ in 0..m {
        let a: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
        let b: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
        let c: i64 = it.next().unwrap().parse().unwrap();

        edges.push((a, b, c));
        graph[a].push((b, c));
        graph[b].push((a, c));
    }

    let dist_from_start = dijkstra(0, &graph);
    let dist_from_goal = dijkstra(n - 1, &graph);
    let shortest = dist_from_start[n - 1];

    // Undirected graph consisting only of edges that belong to at least one
    // shortest path from city 1 to city N.
    let mut shortest_graph = vec![Vec::<(usize, usize)>::new(); n];

    for (id, &(a, b, c)) in edges.iter().enumerate() {
        let ab = dist_from_start[a] < INF
            && dist_from_goal[b] < INF
            && dist_from_start[a] + c + dist_from_goal[b] == shortest;
        let ba = dist_from_start[b] < INF
            && dist_from_goal[a] < INF
            && dist_from_start[b] + c + dist_from_goal[a] == shortest;

        if ab || ba {
            shortest_graph[a].push((b, id));
            shortest_graph[b].push((a, id));
        }
    }

    // Find bridges in the shortest-path subgraph using iterative Tarjan DFS.
    let mut tin = vec![0usize; n];
    let mut low = vec![0usize; n];
    let mut parent = vec![usize::MAX; n];
    let mut parent_edge = vec![usize::MAX; n];
    let mut next_edge = vec![0usize; n];
    let mut is_bridge = vec![false; m];

    let mut timer = 1usize;
    tin[0] = timer;
    low[0] = timer;

    let mut stack = vec![0usize];

    while let Some(&v) = stack.last() {
        if next_edge[v] < shortest_graph[v].len() {
            let (to, edge_id) = shortest_graph[v][next_edge[v]];
            next_edge[v] += 1;

            if edge_id == parent_edge[v] {
                continue;
            }

            if tin[to] == 0 {
                parent[to] = v;
                parent_edge[to] = edge_id;
                timer += 1;
                tin[to] = timer;
                low[to] = timer;
                stack.push(to);
            } else {
                low[v] = low[v].min(tin[to]);
            }
        } else {
            stack.pop();

            if parent[v] != usize::MAX {
                let p = parent[v];
                let edge_id = parent_edge[v];

                if low[v] > tin[p] {
                    is_bridge[edge_id] = true;
                }
                low[p] = low[p].min(low[v]);
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for bridge in is_bridge {
        if bridge {
            writeln!(out, "Yes").unwrap();
        } else {
            writeln!(out, "No").unwrap();
        }
    }
}
