    let mut purchased_size = None;
    let mut possible = true;

    for box_size in boxes {
        if toys[toy_idx] <= box_size {
            toy_idx += 1;
        } else {
            if purchased_size.is_some() {
                possible = false;
                break;
            }

            purchased_size = Some(toys[toy_idx]);
            toy_idx += 1;

            if toy_idx >= n || toys[toy_idx] > box_size {
                possible = false;
                break;
            }
            toy_idx += 1;
        }
    }

    let answer = if !possible {
        -1
    } else if let Some(size) = purchased_size {
        size
    } else {
        toys[toy_idx]
    };

