use std::io::{self, Read, Write};

fn directed_distance(from: usize, to: usize, n: usize, dir: i32) -> usize {
    if dir == 1 {
        (to + n - from) % n
    } else {
        (from + n - to) % n
    }
}

fn move_to_target(
    start: usize,
    blocker: usize,
    target: usize,
    n: usize,
    dir: i32,
) -> (usize, i64) {
    let hand_dist = directed_distance(start, target, n, dir);
    let blocker_dist = directed_distance(start, blocker, n, dir);

    if blocker_dist <= hand_dist {
        let new_blocker = if dir == 1 {
            (target + 1) % n
        } else {
            (target + n - 1) % n
        };
        let cost = hand_dist + (hand_dist - blocker_dist + 1);
        (new_blocker, cost as i64)
    } else {
        (blocker, hand_dist as i64)
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let q: usize = iter.next().unwrap().parse().unwrap();

    let inf = i64::MAX / 4;
    let mut dp = vec![inf; n];

    // The currently fixed hand is initially L at part 1.
    // The other hand R is at part 2.
    let mut current_hand = b'L';
    let mut current_pos = 0usize;
    dp[1] = 0;

    for _ in 0..q {
        let requested_hand = iter.next().unwrap().as_bytes()[0];
        let target: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;

        let mut next_dp = vec![inf; n];

        for other_pos in 0..n {
            if dp[other_pos] == inf {
                continue;
            }

            for &dir in &[1, -1] {
                let (start, blocker) = if requested_hand == current_hand {
                    (current_pos, other_pos)
                } else {
                    (other_pos, current_pos)
                };

                let (new_other_pos, move_cost) =
                    move_to_target(start, blocker, target, n, dir);

                let new_cost = dp[other_pos] + move_cost;
                if new_cost < next_dp[new_other_pos] {
                    next_dp[new_other_pos] = new_cost;
                }
            }
        }

        dp = next_dp;
        current_hand = requested_hand;
        current_pos = target;
    }

    let answer = *dp.iter().min().unwrap();
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", answer).unwrap();
}
