fn mod_pow(mut base: u64, mut exp: u64, modulus: u64) -> u64 {
    if modulus == 1 {
        return 0;
    }
    let mut result = 1u64;
    base %= modulus;
    while exp > 0 {
        if exp & 1 == 1 {
            result = result * base % modulus;
        }
        base = base * base % modulus;
        exp >>= 1;
    }
    result
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let k: u64 = iter.next().unwrap().parse().unwrap();
    let p: Vec<usize> = (0..n)
        .map(|_| iter.next().unwrap().parse::<usize>().unwrap() - 1)
        .collect();

    let mut answer = vec![0usize; n];
    let mut visited = vec![false; n];

    for start in 0..n {
        if visited[start] {
            continue;
        }

        let mut cycle = Vec::new();
        let mut current = start;
        while !visited[current] {
            visited[current] = true;
            cycle.push(current);
            current = p[current];
        }

        let len = cycle.len();
        let shift = mod_pow(2, k, len as u64) as usize;

        for i in 0..len {
            answer[cycle[i]] = cycle[(i + shift) % len];
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    for (i, &value) in answer.iter().enumerate() {
        if i > 0 {
            write!(out, " ").unwrap();
        }
        write!(out, "{}", value + 1).unwrap();
    }
