use std::io::{self, Read, Write};

fn dfs(
    current: usize,
    remaining: usize,
    graph: &[Vec<usize>],
    visited: &mut [bool],
) -> u64 {
    if remaining == 0 {
        return 1;
    }

    let mut count = 0;
    for &next in &graph[current] {
        if !visited[next] {
            visited[next] = true;
            count += dfs(next, remaining - 1, graph, visited);
            visited[next] = false;
        }
    }
    count
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let h: usize = iter.next().unwrap().parse().unwrap();
    let w: usize = iter.next().unwrap().parse().unwrap();
    let k: usize = iter.next().unwrap().parse().unwrap();

    let grid: Vec<Vec<u8>> = (0..h)
        .map(|_| iter.next().unwrap().as_bytes().to_vec())
        .collect();

    let mut graph = vec![Vec::new(); h * w];
    let directions = [(-1_i32, 0_i32), (1, 0), (0, -1), (0, 1)];

    for row in 0..h {
        for col in 0..w {
            if grid[row][col] == b'#' {
                continue;
            }

            let id = row * w + col;
            for &(dr, dc) in &directions {
                let nr = row as i32 + dr;
                let nc = col as i32 + dc;

                if nr >= 0
                    && nr < h as i32
                    && nc >= 0
                    && nc < w as i32
                    && grid[nr as usize][nc as usize] == b'.'
                {
                    graph[id].push(nr as usize * w + nc as usize);
                }
            }
        }
    }

    let mut visited = vec![false; h * w];
    let mut answer = 0_u64;

    for row in 0..h {
        for col in 0..w {
            if grid[row][col] == b'.' {
                let start = row * w + col;
                visited[start] = true;
                answer += dfs(start, k, &graph, &mut visited);
                visited[start] = false;
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
