use std::io::{self, Read, Write};

struct Fenwick {
    tree: Vec<i64>,
}

impl Fenwick {
    fn new(n: usize) -> Self {
        Self {
            tree: vec![0; n + 1],
        }
    }

    fn add(&mut self, mut index: usize, value: i64) {
        while index < self.tree.len() {
            self.tree[index] += value;
            index += index & index.wrapping_neg();
        }
    }

    fn sum(&self, mut index: usize) -> i64 {
        let mut result = 0;
        while index > 0 {
            result += self.tree[index];
            index &= index - 1;
        }
        result
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let m: i64 = iter.next().unwrap().parse().unwrap();

    let mut fenwick = Fenwick::new(m as usize);
    let mut prefix = 0_i64;
    let mut previous_sum = 0_i64;
    let mut answer = 0_i64;

    // Initial prefix sum P_0 = 0.
    fenwick.add(1, 1);

    for j in 1..=n {
        let a: i64 = iter.next().unwrap().parse().unwrap();
        prefix = (prefix + a % m) % m;

        let less_or_equal = fenwick.sum(prefix as usize + 1);
        let greater = j as i64 - less_or_equal;

        answer += j as i64 * prefix - previous_sum + greater * m;

        fenwick.add(prefix as usize + 1, 1);
        previous_sum += prefix;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
