                elapsed += t;
            }
            3 => {
                let h: i64 = iter.next().unwrap().parse().unwrap();
                let threshold = elapsed - h;
                let start = head;

                while head < planted_at.len() && planted_at[head] <= threshold {
                    head += 1;
                }

                output.push_str(&(head - start).to_string());
                output.push('\n');
            }
            _ => unreachable!(),
        }
    }

    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());
    writer.write_all(output.as_bytes()).unwrap();
}
