    for ch in &mut s[previous_end + 1..=current_end] {
        *ch = b'0';
    }
    for ch in &mut s[previous_end + 1..previous_end + 1 + block_length] {
        *ch = b'1';
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    out.write_all(&s).unwrap();
