use std::io::{self, Read, Write};

fn is_winning(
    state: usize,
    turn: usize,
    hand: usize,
    table: usize,
    values: &[u64],
    pow3: &[usize],
    memo: &[u8],
) -> bool {
    let owner = turn + 1;
    let next_turn = 1 - turn;
    let mut cards = hand;

    while cards != 0 {
        let x = cards.trailing_zeros() as usize;
        cards &= cards - 1;

        let after_play = state - owner * pow3[x];

        // Do not take a card from the table.
        if memo[after_play * 2 + next_turn] == 0 {
            return true;
        }

        // Take a strictly smaller card from the table.
        let mut table_cards = table;
        while table_cards != 0 {
            let y = table_cards.trailing_zeros() as usize;
            table_cards &= table_cards - 1;

            if values[y] < values[x] {
                let next_state = after_play + owner * pow3[y];
                if memo[next_state * 2 + next_turn] == 0 {
                    return true;
                }
            }
        }
    }

    false
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let m: usize = iter.next().unwrap().parse().unwrap();
    let l: usize = iter.next().unwrap().parse().unwrap();
    let k = n + m + l;

    let mut values = Vec::with_capacity(k);
    for _ in 0..k {
        values.push(iter.next().unwrap().parse::<u64>().unwrap());
    }

    let mut pow3 = vec![1usize; k + 1];
    for i in 0..k {
        pow3[i + 1] = pow3[i] * 3;
    }
    let state_count = pow3[k];
    let mask_count = 1usize << k;
    let full_mask = mask_count - 1;

    // code[mask] is the ternary-state contribution when every card in mask
    // belongs to Takahashi (digit 1).
    let mut code = vec![0usize; mask_count];
    let mut sums = vec![0u64; mask_count];
    for mask in 1..mask_count {
        let bit = mask.trailing_zeros() as usize;
        let previous = mask & (mask - 1);
        code[mask] = code[previous] + pow3[bit];
        sums[mask] = sums[previous] + values[bit];
    }

    // Every move strictly decreases the sum of the values in both hands,
    // so states can be evaluated in increasing order of that sum.
    let mut held_masks: Vec<usize> = (0..mask_count).collect();
    held_masks.sort_unstable_by_key(|&mask| sums[mask]);

    let mut memo = vec![0u8; state_count * 2];

    for held in held_masks {
        let table = full_mask ^ held;

        // Partition the held cards between Takahashi and Aoki.
        let mut takahashi = held;
        loop {
            let aoki = held ^ takahashi;
            let state = code[takahashi] + 2 * code[aoki];

            if is_winning(
                state,
                0,
                takahashi,
                table,
                &values,
                &pow3,
                &memo,
            ) {
                memo[state * 2] = 1;
            }

            if is_winning(
                state,
                1,
                aoki,
                table,
                &values,
                &pow3,
                &memo,
            ) {
                memo[state * 2 + 1] = 1;
            }

            if takahashi == 0 {
                break;
            }
            takahashi = (takahashi - 1) & held;
        }
    }

    let initial_takahashi = (1usize << n) - 1;
    let initial_aoki = ((1usize << m) - 1) << n;
    let initial_state = code[initial_takahashi] + 2 * code[initial_aoki];

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    if memo[initial_state * 2] == 1 {
        writeln!(out, "Takahashi").unwrap();
    } else {
        writeln!(out, "Aoki").unwrap();
    }
}
