use std::io::{self, Read, Write};

fn lower_bound(values: &[usize], target: usize) -> usize {
    let mut left = 0;
    let mut right = values.len();
    while left < right {
        let mid = left + (right - left) / 2;
        if values[mid] < target {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    left
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let q: usize = iter.next().unwrap().parse().unwrap();
    let s = iter.next().unwrap().as_bytes();

    let mut prefix_one = vec![0usize; n + 1];
    let mut prefix_two = vec![0usize; n + 1];
    let mut slashes = Vec::new();

    for i in 0..n {
        prefix_one[i + 1] = prefix_one[i] + usize::from(s[i] == b'1');
        prefix_two[i + 1] = prefix_two[i] + usize::from(s[i] == b'2');
        if s[i] == b'/' {
            slashes.push(i + 1);
        }
    }

    let mut output = String::new();

    for _ in 0..q {
        let l: usize = iter.next().unwrap().parse().unwrap();
        let r: usize = iter.next().unwrap().parse().unwrap();

        let begin = lower_bound(&slashes, l);
        let end = lower_bound(&slashes, r + 1);

        if begin == end {
            output.push_str("0\n");
            continue;
        }

        let count = |p: usize| -> usize {
            let ones = prefix_one[p - 1] - prefix_one[l - 1];
            let twos = prefix_two[r] - prefix_two[p];
            ones.min(twos)
        };

        // Find the first slash where the number of available 1s is
        // at least the number of available 2s.
        let mut low = begin;
        let mut high = end;
        while low < high {
            let mid = low + (high - low) / 2;
            let p = slashes[mid];
            let ones = prefix_one[p - 1] - prefix_one[l - 1];
            let twos = prefix_two[r] - prefix_two[p];

            if ones >= twos {
                high = mid;
            } else {
                low = mid + 1;
            }
        }

        let crossing = low;
        let mut best = 0usize;

        if crossing < end {
            best = best.max(count(slashes[crossing]));
        }
        if crossing > begin {
            best = best.max(count(slashes[crossing - 1]));
        }

        output.push_str(&(2 * best + 1).to_string());
        output.push('\n');
    }

    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());
    writer.write_all(output.as_bytes()).unwrap();
}
