use std::fmt::Write as FmtWrite;
use std::io::{self, Read, Write};

fn binomial(n: u64, k: u64) -> u64 {
    let k = k.min(n - k);
    let mut result = 1u64;
    for i in 1..=k {
        result = result * (n - k + i) / i;
    }
    result
}

fn generate(
    pos: usize,
    n: usize,
    m: i32,
    min_value: i32,
    sequence: &mut [i32],
    output: &mut String,
) {
    if pos == n {
        for (i, value) in sequence.iter().enumerate() {
            if i > 0 {
                output.push(' ');
            }
            write!(output, "{}", value).unwrap();
        }
        output.push('\n');
        return;
    }

    let remaining = n - pos - 1;
    let max_value = m - 10 * remaining as i32;

    for value in min_value..=max_value {
        sequence[pos] = value;
        generate(pos + 1, n, m, value + 10, sequence, output);
    }
}

fn main() {
