use std::io::{self, Read, Write};

struct SegmentTree {
    n: usize,
    min: Vec<usize>,
    lazy: Vec<Option<usize>>,
}

impl SegmentTree {
    fn new(n: usize, initial: usize) -> Self {
        Self {
            n,
            min: vec![initial; 4 * n.max(1)],
            lazy: vec![None; 4 * n.max(1)],
        }
    }

    fn apply(&mut self, node: usize, value: usize) {
        self.min[node] = value;
        self.lazy[node] = Some(value);
    }

    fn push(&mut self, node: usize) {
        if let Some(value) = self.lazy[node].take() {
            self.apply(node * 2, value);
            self.apply(node * 2 + 1, value);
        }
    }

    fn assign_range(&mut self, left: usize, right: usize, value: usize) {
        self.assign_range_rec(left, right, value, 1, 0, self.n);
    }

    fn assign_range_rec(
        &mut self,
        left: usize,
        right: usize,
        value: usize,
        node: usize,
        node_left: usize,
        node_right: usize,
    ) {
        if right <= node_left || node_right <= left {
            return;
        }
        if left <= node_left && node_right <= right {
            self.apply(node, value);
            return;
        }

        self.push(node);
        let mid = (node_left + node_right) / 2;
        self.assign_range_rec(left, right, value, node * 2, node_left, mid);
        self.assign_range_rec(left, right, value, node * 2 + 1, mid, node_right);
        self.min[node] = self.min[node * 2].min(self.min[node * 2 + 1]);
    }

    fn query_min(&mut self, left: usize, right: usize) -> usize {
        self.query_min_rec(left, right, 1, 0, self.n)
    }

    fn query_min_rec(
        &mut self,
        left: usize,
        right: usize,
        node: usize,
        node_left: usize,
        node_right: usize,
    ) -> usize {
        if right <= node_left || node_right <= left {
            return usize::MAX;
        }
        if left <= node_left && node_right <= right {
            return self.min[node];
        }

        self.push(node);
        let mid = (node_left + node_right) / 2;
        let a = self.query_min_rec(left, right, node * 2, node_left, mid);
        let b = self.query_min_rec(left, right, node * 2 + 1, mid, node_right);
        a.min(b)
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let h: usize = iter.next().unwrap().parse().unwrap();
    let w: usize = iter.next().unwrap().parse().unwrap();
    let n: usize = iter.next().unwrap().parse().unwrap();

    let mut bars = Vec::with_capacity(n);
    for index in 0..n {
        let r: usize = iter.next().unwrap().parse().unwrap();
        let c: usize = iter.next().unwrap().parse().unwrap();
        let l: usize = iter.next().unwrap().parse().unwrap();
        bars.push((r, c - 1, l, index));
    }

    bars.sort_unstable_by(|a, b| b.0.cmp(&a.0));

    let mut seg = SegmentTree::new(w, h + 1);
    let mut answer = vec![0usize; n];

    for &(_, left, length, index) in &bars {
        let right = left + length;
        let nearest_below = seg.query_min(left, right);
        let final_row = nearest_below - 1;
        answer[index] = final_row;
        seg.assign_range(left, right, final_row);
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    for row in answer {
        writeln!(out, "{row}").unwrap();
    }
}
