use std::cmp::Reverse;
use std::collections::BinaryHeap;
use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let h: usize = iter.next().unwrap().parse().unwrap();
    let w: usize = iter.next().unwrap().parse().unwrap();
    let x: u128 = iter.next().unwrap().parse().unwrap();
    let p: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
    let q: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;

    let mut grid = vec![0u64; h * w];
    for value in &mut grid {
        *value = iter.next().unwrap().parse().unwrap();
    }

    let start = p * w + q;
    let mut strength = grid[start] as u128;
    let mut discovered = vec![false; h * w];
    discovered[start] = true;

    let mut heap = BinaryHeap::<Reverse<(u64, usize)>>::new();

    fn add_neighbors(
        idx: usize,
        h: usize,
        w: usize,
        grid: &[u64],
        discovered: &mut [bool],
        heap: &mut BinaryHeap<Reverse<(u64, usize)>>,
    ) {
        let r = idx / w;
        let c = idx % w;

        if r > 0 {
            let next = idx - w;
            if !discovered[next] {
                discovered[next] = true;
                heap.push(Reverse((grid[next], next)));
            }
        }
        if r + 1 < h {
            let next = idx + w;
            if !discovered[next] {
                discovered[next] = true;
                heap.push(Reverse((grid[next], next)));
            }
        }
        if c > 0 {
            let next = idx - 1;
            if !discovered[next] {
                discovered[next] = true;
                heap.push(Reverse((grid[next], next)));
            }
        }
        if c + 1 < w {
            let next = idx + 1;
            if !discovered[next] {
                discovered[next] = true;
                heap.push(Reverse((grid[next], next)));
            }
        }
    }

    add_neighbors(
        start,
        h,
        w,
        &grid,
        &mut discovered,
        &mut heap,
    );

    while let Some(&Reverse((value, idx))) = heap.peek() {
        if (value as u128) * x >= strength {
            break;
        }

        heap.pop();
        strength += value as u128;
        add_neighbors(
            idx,
            h,
            w,
            &grid,
            &mut discovered,
            &mut heap,
        );
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{strength}").unwrap();
}
