use std::io::{self, Read, Write};

#[derive(Clone, Copy, Default)]
struct Node {
    left: usize,
    right: usize,
    count: i32,
    sum: i64,
}

#[derive(Clone, Copy)]
struct Query {
    x: usize,
    y: usize,
}

fn insert(
    nodes: &mut Vec<Node>,
    previous: usize,
    left: usize,
    right: usize,
    position: usize,
    value: i64,
) -> usize {
    let index = nodes.len();
    let previous_node = nodes[previous];
    nodes.push(Node {
        left: previous_node.left,
        right: previous_node.right,
        count: previous_node.count + 1,
        sum: previous_node.sum + value,
    });

    if right - left > 1 {
        let middle = (left + right) / 2;
        if position < middle {
            let child = insert(
                nodes,
                previous_node.left,
                left,
                middle,
                position,
                value,
            );
            nodes[index].left = child;
        } else {
            let child = insert(
                nodes,
                previous_node.right,
                middle,
                right,
                position,
                value,
            );
            nodes[index].right = child;
        }
    }

    index
}

fn upper_bound(values: &[i64], target: i64) -> usize {
    let mut left = 0;
    let mut right = values.len();
    while left < right {
        let middle = (left + right) / 2;
        if values[middle] <= target {
            left = middle + 1;
        } else {
            right = middle;
        }
    }
    left
}

fn query_prefix(
    nodes: &[Node],
    root: usize,
    size: usize,
    end: usize,
) -> (i64, i64) {
    if end == 0 || root == 0 {
        return (0, 0);
    }
    if end >= size {
        let node = nodes[root];
        return (node.count as i64, node.sum);
    }

    let mut node_index = root;
    let mut left = 0usize;
    let mut right = size;
    let mut count = 0i64;
    let mut sum = 0i64;

    while right - left > 1 && node_index != 0 {
        let middle = (left + right) / 2;
        let node = nodes[node_index];

        if end <= middle {
            node_index = node.left;
            right = middle;
        } else {
            let left_node = nodes[node.left];
            count += left_node.count as i64;
            sum += left_node.sum;
            node_index = node.right;
            left = middle;
        }
    }

    if node_index != 0 && left < end {
        let node = nodes[node_index];
        count += node.count as i64;
        sum += node.sum;
    }

    (count, sum)
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let mut a = Vec::with_capacity(n);
    for _ in 0..n {
        a.push(it.next().unwrap().parse::<i64>().unwrap());
    }

    let mut b = Vec::with_capacity(n);
    for _ in 0..n {
        b.push(it.next().unwrap().parse::<i64>().unwrap());
    }

    let k: usize = it.next().unwrap().parse().unwrap();
    let mut queries = Vec::with_capacity(k);
    for _ in 0..k {
        let x = it.next().unwrap().parse::<usize>().unwrap();
        let y = it.next().unwrap().parse::<usize>().unwrap();
        queries.push(Query { x, y });
    }

    let mut coordinates = b.clone();
    coordinates.sort_unstable();
    coordinates.dedup();
    let coordinate_count = coordinates.len();

    let mut nodes = Vec::with_capacity((n + 1) * 20);
    nodes.push(Node::default());

    let mut roots = vec![0usize; n + 1];
    for i in 0..n {
        let position = coordinates.binary_search(&b[i]).unwrap();
        roots[i + 1] = insert(
            &mut nodes,
            roots[i],
            0,
            coordinate_count,
            position,
            b[i],
        );
    }

    let mut a_upper_bounds = Vec::with_capacity(n);
    for &value in &a {
        a_upper_bounds.push(upper_bound(&coordinates, value));
    }

    let levels = {
        let mut value = coordinate_count.max(2) - 1;
        let mut result = 0usize;
        while value > 0 {
            result += 1;
            value >>= 1;
        }
        result.max(1)
    };

    let denominator = ((k.max(1) * levels) as f64).sqrt();
    let block_size = ((n as f64 / denominator).floor() as usize).max(1);

    let block_count = n / block_size + 1;
    let mut groups = vec![Vec::<usize>::new(); block_count];
    for (index, query) in queries.iter().enumerate() {
        groups[query.x / block_size].push(index);
    }

    let mut b_order: Vec<usize> = (0..n).collect();
    b_order.sort_unstable_by_key(|&index| b[index]);

    let mut answers = vec![0i64; k];
    let mut contribution_per_b = vec![0i64; n];
    let mut previous_boundary = 0usize;

    for block in 0..block_count {
        if groups[block].is_empty() {
            continue;
        }

        let boundary = (block * block_size).min(n);

        if boundary > previous_boundary {
            let mut added = a[previous_boundary..boundary].to_vec();
            added.sort_unstable();

            let added_count = added.len();
            let total_sum: i64 = added.iter().sum();
            let mut pointer = 0usize;
            let mut left_sum = 0i64;

            for &b_index in &b_order {
                let value = b[b_index];
                while pointer < added_count && added[pointer] <= value {
                    left_sum += added[pointer];
                    pointer += 1;
                }

                let left_count = pointer as i64;
                let right_count = (added_count - pointer) as i64;
                let delta = value * left_count - left_sum
                    + (total_sum - left_sum) - value * right_count;
                contribution_per_b[b_index] += delta;
            }

            previous_boundary = boundary;
        }

        if boundary != 0 {
            groups[block].sort_unstable_by_key(|&index| queries[index].y);

            let mut position = 0usize;
            let mut prefix_sum = 0i64;
            for &query_index in &groups[block] {
                let y = queries[query_index].y;
                while position < y {
                    prefix_sum += contribution_per_b[position];
                    position += 1;
                }
                answers[query_index] = prefix_sum;
            }
        }
    }

    for (query_index, query) in queries.iter().enumerate() {
        let boundary = (query.x / block_size) * block_size;
        let root = roots[query.y];
        let total_b_sum = nodes[root].sum;
        let total_b_count = query.y as i64;

        for i in boundary..query.x {
            let value = a[i];
            let (lower_count, lower_sum) = query_prefix(
                &nodes,
                root,
                coordinate_count,
                a_upper_bounds[i],
            );

            let upper_count = total_b_count - lower_count;
            let upper_sum = total_b_sum - lower_sum;

            answers[query_index] +=
                value * lower_count - lower_sum + upper_sum - value * upper_count;
        }
    }

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    for answer in answers {
        writeln!(output, "{answer}").unwrap();
    }
}
