    for center in 0..n {
        let mut capacities: Vec<usize> = graph[center]
            .iter()
            .map(|&neighbor| degrees[neighbor] - 1)
            .filter(|&capacity| capacity > 0)
            .collect();

        capacities.sort_unstable_by(|a, b| b.cmp(a));

        for (i, &y) in capacities.iter().enumerate() {
            let x = i + 1;
            let remaining = 1 + x * (y + 1);
            max_remaining = max_remaining.max(remaining);
        }
    }

    let answer = n - max_remaining;
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
