use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let k: usize = iter.next().unwrap().parse().unwrap();
    let s = iter.next().unwrap().as_bytes();
    let t = iter.next().unwrap().as_bytes();

    if s.len().abs_diff(t.len()) > k {
        println!("No");
        return;
    }

    // Remove a common prefix and suffix.
    let mut start = 0;
    while start < s.len() && start < t.len() && s[start] == t[start] {
        start += 1;
    }

    let mut s_end = s.len();
    let mut t_end = t.len();
    while s_end > start && t_end > start && s[s_end - 1] == t[t_end - 1] {
        s_end -= 1;
        t_end -= 1;
    }

    let s = &s[start..s_end];
    let t = &t[start..t_end];
    let n = s.len();
    let m = t.len();

    if n.abs_diff(m) > k {
        println!("No");
        return;
    }

    let inf = k + 2;
    let width = 2 * k + 1;
    let mut prev = vec![inf; width];
    let mut cur = vec![inf; width];

    let mut prev_low = 0usize;
    let mut prev_high = m.min(k);
    for j in prev_low..=prev_high {
        prev[j - prev_low] = j;
    }

    for i in 1..=n {
        cur.fill(inf);

        let low = i.saturating_sub(k);
        let high = m.min(i + k);
        let mut row_min = inf;

        for j in low..=high {
            let idx = j - low;
            let mut best = inf;

            // Delete s[i - 1].
            if j >= prev_low && j <= prev_high {
                best = best.min(prev[j - prev_low] + 1);
            }

            // Insert t[j - 1].
            if j > low {
                best = best.min(cur[idx - 1] + 1);
            }

            // Match or replace.
            if j > 0 && j - 1 >= prev_low && j - 1 <= prev_high {
                let cost = if s[i - 1] == t[j - 1] { 0 } else { 1 };
                best = best.min(prev[j - 1 - prev_low] + cost);
            }

            cur[idx] = best;
            row_min = row_min.min(best);
        }

        if row_min > k {
            let stdout = io::stdout();
            let mut out = io::BufWriter::new(stdout.lock());
            writeln!(out, "No").unwrap();
            return;
        }

        std::mem::swap(&mut prev, &mut cur);
        prev_low = low;
        prev_high = high;
    }

    let possible = m >= prev_low
        && m <= prev_high
        && prev[m - prev_low] <= k;

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", if possible { "Yes" } else { "No" }).unwrap();
}
