use std::io::{self, Read, Write};

struct Fenwick {
    n: usize,
    tree: Vec<usize>,
}

impl Fenwick {
    fn new(n: usize) -> Self {
        Self {
            n,
            tree: vec![0; n + 1],
        }
    }

    fn add(&mut self, mut i: usize, value: usize) {
        while i <= self.n {
            self.tree[i] += value;
            i += i & (!i + 1);
        }
    }

    fn sum(&self, mut i: usize) -> usize {
        let mut result = 0;
        while i > 0 {
            result += self.tree[i];
            i &= i - 1;
        }
        result
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let mut p = vec![0usize; n];
    for x in &mut p {
        *x = it.next().unwrap().parse().unwrap();
    }

    let m: usize = it.next().unwrap().parse().unwrap();
    let mut a = vec![0usize; m];
    for x in &mut a {
        *x = it.next().unwrap().parse().unwrap();
    }

    let mut fenwick = Fenwick::new(n);
    let mut greater_before = vec![0usize; n + 1];
    let mut inversions = 0i64;

    for (i, &value) in p.iter().enumerate() {
        let not_greater = fenwick.sum(value);
        let greater = i - not_greater;
        greater_before[i + 1] = greater;
        inversions += greater as i64;
        fenwick.add(value, 1);
    }

    let mut diff = vec![0i64; m + 1];
    let mut first_operation = 0usize;

    for position in 1..=n {
        while first_operation < m && a[first_operation] < position {
            first_operation += 1;
        }

        let swaps_needed = greater_before[position];
        if first_operation < m && swaps_needed > 0 {
            let end = (first_operation + swaps_needed).min(m);
            diff[first_operation] += 1;
            diff[end] -= 1;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    let mut swaps_this_operation = 0i64;

    for i in 0..m {
        swaps_this_operation += diff[i];
        inversions -= swaps_this_operation;
        writeln!(out, "{inversions}").unwrap();
    }
}
