use std::io::{self, Read, Write};

const MOD: u64 = 998_244_353;
const P: usize = 6;
const STATES: usize = 1 << P;
const DIM: usize = STATES + 1;

type Matrix = Vec<Vec<u64>>;

fn mat_mul(a: &Matrix, b: &Matrix) -> Matrix {
    let mut c = vec![vec![0u64; DIM]; DIM];

    // All matrices used here are lower triangular.
    for i in 0..DIM {
        for k in 0..=i {
            let aik = a[i][k];
            if aik == 0 {
                continue;
            }
            for j in 0..=k {
                let bkj = b[k][j];
                if bkj == 0 {
                    continue;
                }
                let add = aik * bkj % MOD;
                let value = c[i][j] + add;
                c[i][j] = if value >= MOD { value - MOD } else { value };
            }
        }
    }
    c
}

fn mat_vec_mul(a: &Matrix, v: &[u64]) -> Vec<u64> {
    let mut result = vec![0u64; DIM];
    for i in 0..DIM {
        let mut sum = 0u64;
        for j in 0..=i {
            if a[i][j] == 0 || v[j] == 0 {
                continue;
            }
            let add = a[i][j] * v[j] % MOD;
            sum += add;
            if sum >= MOD {
                sum -= MOD;
            }
        }
        result[i] = sum;
    }
    result
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();
    let mut n: u64 = it.next().unwrap().parse().unwrap();
    let m: usize = it.next().unwrap().parse().unwrap();

    let primes = [2usize, 3, 5, 7, 11, 13];

    // coefficient[mask] =
    // sum_{x=1}^M product_{p in mask} exponent_p(x)
    let mut coefficient = vec![0u64; STATES];

    for x in 1..=m {
        let mut exponents = [0u64; P];
        let mut value = x;
        for i in 0..P {
            while value % primes[i] == 0 {
                exponents[i] += 1;
                value /= primes[i];
            }
        }

        for mask in 0..STATES {
            let mut product = 1u64;
            for i in 0..P {
                if (mask >> i) & 1 == 1 {
                    product = product * exponents[i] % MOD;
                }
            }
            coefficient[mask] += product;
            if coefficient[mask] >= MOD {
                coefficient[mask] -= MOD;
            }
        }
    }

    let mut transition = vec![vec![0u64; DIM]; DIM];

    // V_S(k) = sum over length-k sequences of
    // product_{p in S} (total exponent of p + 1).
    for s in 0..STATES {
        let mut t = s;
        loop {
            transition[s][t] = coefficient[s ^ t];
            if t == 0 {
                break;
            }
            t = (t - 1) & s;
        }
    }

    // The final state accumulates V_full(1) + ... + V_full(k).
    let accumulator = STATES;
    for t in 0..STATES {
        transition[accumulator][t] = transition[STATES - 1][t];
    }
    transition[accumulator][accumulator] = 1;

    // At length zero, every moment equals 1.
    let mut state = vec![1u64; DIM];
    state[accumulator] = 0;

    let mut power = transition;
    while n > 0 {
        if n & 1 == 1 {
            state = mat_vec_mul(&power, &state);
        }
        n >>= 1;
        if n > 0 {
            power = mat_mul(&power, &power);
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", state[accumulator]).unwrap();
}
