    for _ in 0..t {
        let n: usize = it.next().unwrap().parse().unwrap();
        let k: usize = it.next().unwrap().parse().unwrap();

        let mut a = Vec::with_capacity(n);
        for _ in 0..n {
            a.push(it.next().unwrap().parse::<usize>().unwrap());
        }

        let mut b = Vec::with_capacity(n);
        for _ in 0..n {
            b.push(it.next().unwrap().parse::<usize>().unwrap());
        }

        let possible = if k == 1 {
            let mut compressed_a = Vec::new();
            for &x in &a {
                if compressed_a.last().copied() != Some(x) {
                    compressed_a.push(x);
                }
            }

            let mut pos = 0usize;
            let mut previous = None;
            let mut ok = true;

            for &x in &b {
                if previous == Some(x) {
                    continue;
                }
                previous = Some(x);

                while pos < compressed_a.len() && compressed_a[pos] != x {
                    pos += 1;
                }
                if pos == compressed_a.len() {
                    ok = false;
                    break;
                }
                pos += 1;
            }
            ok
        } else {
            let mut present = vec![false; n + 1];
            for &x in &a {
                present[x] = true;
            }

            let mut all_present = true;
            let mut unchanged = true;
            let mut has_close_equal_pair = false;
            let mut last_position = vec![usize::MAX; n + 1];

            for i in 0..n {
                let x = b[i];

                if !present[x] {
                    all_present = false;
                }
                if a[i] != x {
                    unchanged = false;
                }

                if last_position[x] != usize::MAX && i - last_position[x] <= k {
                    has_close_equal_pair = true;
                }
                last_position[x] = i;
            }

            all_present && (unchanged || has_close_equal_pair)
        };

        output.push_str(if possible { "Yes\n" } else { "No\n" });
    }

    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());
    writer.write_all(output.as_bytes()).unwrap();
