use std::collections::HashMap;
use std::collections::hash_map::Entry;
use std::io::{self, Read, Write};

const MOD: u64 = 998_244_353;

struct Group {
    phases: Vec<u32>,
    phase_sum: u64,
    base_sum: i64,
    period: u32,
}

fn fenwick_sum(bit: &[u64], mut i: usize) -> u64 {
    let mut result = 0;
    while i > 0 {
        result += bit[i];
        i &= i - 1;
    }
    result
}

fn fenwick_add(bit: &mut [u64], mut i: usize) {
    while i < bit.len() {
        bit[i] += 1;
        i += i & i.wrapping_neg();
    }
}

fn inversion_count(values: &[u32]) -> u64 {
    if values.len() <= 1 {
        return 0;
    }

    let mut sorted = values.to_vec();
    sorted.sort_unstable();
    sorted.dedup();

    let mut bit = vec![0u64; sorted.len() + 1];
    let mut seen = 0u64;
    let mut inversions = 0u64;

    for &value in values {
        let pos = sorted.binary_search(&value).unwrap() + 1;
        let not_greater = fenwick_sum(&bit, pos);
        inversions += seen - not_greater;
        fenwick_add(&mut bit, pos);
        seen += 1;
    }

    inversions
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let m: usize = iter.next().unwrap().parse().unwrap();

    let mut group_ids: HashMap<Vec<u8>, usize> = HashMap::new();
    let mut groups: Vec<Group> = Vec::new();

    for _ in 0..n {
        let mut sequence = Vec::new();
        let mut started = false;

        for _ in 0..m {
            let value = iter.next().unwrap().as_bytes()[0] - b'0';
            if started {
                sequence.push(value);
            } else if value == 1 {
                started = true;
                sequence.push(1);
            }
        }

        let (phase, period) = if sequence.is_empty() {
            (0u32, 1u32)
        } else {
            let len = sequence.len();
            let period = len.next_power_of_two() as u32;
            let mut phase = 0u32;
            let mut shift = 1usize;

            while shift < len {
                if sequence[shift] == 1 {
                    let mut i = len;
                    while i > shift {
                        i -= 1;
                        sequence[i] ^= sequence[i - shift];
                    }
                    phase |= shift as u32;
                }
                shift <<= 1;
            }

            (phase, period)
        };

        let group_id = match group_ids.entry(sequence) {
            Entry::Occupied(entry) => *entry.get(),
            Entry::Vacant(entry) => {
                let id = groups.len();
                groups.push(Group {
                    phases: Vec::new(),
                    phase_sum: 0,
                    base_sum: 0,
                    period,
                });
                entry.insert(id);
                id
            }
        };

        let group = &mut groups[group_id];
        let count = group.phases.len() as u64;
        group.base_sum += (count * phase as u64) as i64 - group.phase_sum as i64;
        group.phase_sum += phase as u64;
        group.phases.push(phase);
    }

    let mut answer = 0u64;

    for group in groups {
        let base_mod = group.base_sum.rem_euclid(MOD as i64) as u64;
        let inversions = if group.period == 1 {
            0
        } else {
            inversion_count(&group.phases)
        };

        let wrap_mod = (inversions % MOD) * (group.period as u64 % MOD) % MOD;
        answer += base_mod + wrap_mod;
        answer %= MOD;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", answer).unwrap();
}
