use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let q: usize = it.next().unwrap().parse().unwrap();

    let max_sum = n * n;
    let words = (max_sum + 64) / 64;
    let side = n + 1;

    // dp[r][c] is a bitset:
    // bit s is set if mixed SCC blocks using r rows and c columns
    // can have total area s.
    let mut dp = vec![0u64; side * side * words];

    let index = |r: usize, c: usize| -> usize { (r * side + c) * words };
    dp[index(0, 0)] = 1;

    // Every mixed strongly connected component must contain at least
    // two rows and two columns. Such a component of sizes (a, b)
    // contributes a*b non-fixed elements.
    for a in 2..=n {
        for b in 2..=n {
            let shift = a * b;
            let word_shift = shift / 64;
            let bit_shift = shift % 64;

            for r in a..=n {
                for c in b..=n {
                    let src = index(r - a, c - b);
                    let dst = index(r, c);

                    for w in 0..words {
                        let value = dp[src + w];
                        if value == 0 {
                            continue;
                        }

                        let target = w + word_shift;
                        if target < words {
                            dp[dst + target] |= value << bit_shift;
                        }
                        if bit_shift != 0 && target + 1 < words {
                            dp[dst + target + 1] |= value >> (64 - bit_shift);
                        }
                    }
                }
            }
        }
    }

    let mut possible_non_fixed = vec![false; max_sum + 1];
    for r in 0..=n {
        for c in 0..=n {
            let base = index(r, c);
            for s in 0..=max_sum {
                if ((dp[base + s / 64] >> (s % 64)) & 1) != 0 {
                    possible_non_fixed[s] = true;
                }
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for _ in 0..q {
        let k: usize = it.next().unwrap().parse().unwrap();
        let non_fixed = max_sum - k;
        if possible_non_fixed[non_fixed] {
            writeln!(out, "Yes").unwrap();
        } else {
            writeln!(out, "No").unwrap();
        }
    }
}
