use std::io::{self, Read, Write};

struct Fenwick {
    n: usize,
    count: Vec<i64>,
    sum: Vec<i64>,
}

impl Fenwick {
    fn new(n: usize) -> Self {
        Self {
            n,
            count: vec![0; n + 1],
            sum: vec![0; n + 1],
        }
    }

    fn add(&mut self, mut index: usize, count_delta: i64, sum_delta: i64) {
        index += 1;
        while index <= self.n {
            self.count[index] += count_delta;
            self.sum[index] += sum_delta;
            index += index & (!index + 1);
        }
    }

    fn total_count(&self) -> i64 {
        let mut index = self.n;
        let mut result = 0;
        while index > 0 {
            result += self.count[index];
            index &= index - 1;
        }
        result
    }

    fn kth_index(&self, k: i64) -> usize {
        let mut index = 0usize;
        let mut accumulated = 0i64;
        let mut step = 1usize;
        while (step << 1) <= self.n {
            step <<= 1;
        }

        while step > 0 {
            let next = index + step;
            if next <= self.n && accumulated + self.count[next] < k {
                accumulated += self.count[next];
                index = next;
            }
            step >>= 1;
        }
        index
    }

    fn sum_smallest(&self, k: i64, values: &[i64]) -> i64 {
        if k <= 0 {
            return 0;
        }

        let idx = self.kth_index(k);
        let mut prefix_count = 0i64;
        let mut prefix_sum = 0i64;
        let mut x = idx;

        while x > 0 {
            prefix_count += self.count[x];
            prefix_sum += self.sum[x];
            x &= x - 1;
        }

        prefix_sum + (k - prefix_count) * values[idx]
    }
}

fn lower_bound(values: &[i64], target: i64) -> usize {
    let mut left = 0usize;
    let mut right = values.len();
    while left < right {
        let mid = (left + right) / 2;
        if values[mid] < target {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    left
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let t: usize = it.next().unwrap().parse().unwrap();
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for _ in 0..t {
        let n: usize = it.next().unwrap().parse().unwrap();
        let m: usize = it.next().unwrap().parse().unwrap();

        let mut boxes = Vec::with_capacity(n);
        let mut coordinates = Vec::with_capacity(2 * n);
        let mut total_positive = 0i64;

        for _ in 0..n {
            let v: i64 = it.next().unwrap().parse().unwrap();
            let p: i64 = it.next().unwrap().parse().unwrap();

            let regular_profit = (v - p).max(0);
            total_positive += regular_profit;

            let higher_cost = p - 1;
            let minimum_cost = v.max(p) - 1;

            coordinates.push(higher_cost);
            coordinates.push(minimum_cost);
            boxes.push((v, p));
        }

        if m == 1 {
            writeln!(out, "{}", total_positive).unwrap();
            continue;
        }

        let k = (m - 1) as i64;
        if k > n as i64 {
            writeln!(out, "0").unwrap();
            continue;
        }

        boxes.sort_unstable_by(|a, b| b.0.cmp(&a.0));
        coordinates.sort_unstable();
        coordinates.dedup();

        let mut fenwick = Fenwick::new(coordinates.len());
        let mut baseline = total_positive;
        let mut answer = 0i64;
        let mut start = 0usize;

        while start < n {
            let value = boxes[start].0;
            let mut end = start;
            while end < n && boxes[end].0 == value {
                end += 1;
            }

            let mut min_current_cost = i64::MAX;

            for idx in start..end {
                let (v, p) = boxes[idx];
                let current_cost = v.max(p) - 1;
                min_current_cost = min_current_cost.min(current_cost);
                let pos = lower_bound(&coordinates, current_cost);
                fenwick.add(pos, 1, current_cost);
            }

            if fenwick.total_count() >= k {
                let sum_k = fenwick.sum_smallest(k, &coordinates);
                let kth_idx = fenwick.kth_index(k);
                let kth_value = coordinates[kth_idx];

                let minimum_penalty = if min_current_cost <= kth_value {
                    sum_k
                } else {
                    for idx in start..end {
                        let (v, p) = boxes[idx];
                        let current_cost = v.max(p) - 1;
                        let pos = lower_bound(&coordinates, current_cost);
                        fenwick.add(pos, -1, -current_cost);
                    }

                    let forced = min_current_cost
                        + fenwick.sum_smallest(k - 1, &coordinates);

                    for idx in start..end {
                        let (v, p) = boxes[idx];
                        let current_cost = v.max(p) - 1;
                        let pos = lower_bound(&coordinates, current_cost);
                        fenwick.add(pos, 1, current_cost);
                    }

                    forced
                };

                answer = answer.max(baseline - minimum_penalty);
            }

            for idx in start..end {
                let (v, p) = boxes[idx];
                let current_cost = v.max(p) - 1;
                let pos = lower_bound(&coordinates, current_cost);
                fenwick.add(pos, -1, -current_cost);
            }

            for idx in start..end {
                let (_, p) = boxes[idx];
                let higher_cost = p - 1;
                let pos = lower_bound(&coordinates, higher_cost);
                fenwick.add(pos, 1, higher_cost);
            }

            for idx in start..end {
                let (v, p) = boxes[idx];
                baseline -= (v - p).max(0);
            }

            start = end;
        }

        writeln!(out, "{}", answer.max(0)).unwrap();
    }
}
