use std::io::{self, Read, Write};

const MOD: i64 = 998_244_353;

fn mod_pow(mut base: i64, mut exp: i64) -> i64 {
    let mut result = 1i64;
    while exp > 0 {
        if exp & 1 == 1 {
            result = result * base % MOD;
        }
        base = base * base % MOD;
        exp >>= 1;
    }
    result
}

fn binom(n: usize, k: usize, fact: &[i64], inv_fact: &[i64]) -> i64 {
    if k > n {
        return 0;
    }
    fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD
}

// Sum of the numbers of valid completions F(r, t) for t = r-K, ..., r.
fn prefix_forest_sum(r: usize, k: i64, fact: &[i64], inv_fact: &[i64]) -> i64 {
    if k < 0 {
        return 0;
    }
    let k = k as usize;
    let n = r + k;
    (binom(n, r, fact, inv_fact) - binom(n, r + 1, fact, inv_fact) + MOD) % MOD
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let a: Vec<i64> = (0..n)
        .map(|_| it.next().unwrap().parse().unwrap())
        .collect();

    let max_fact = 2 * n + 2;
    let mut fact = vec![1i64; max_fact + 1];
    for i in 1..=max_fact {
        fact[i] = fact[i - 1] * i as i64 % MOD;
    }

    let mut inv_fact = vec![1i64; max_fact + 1];
    inv_fact[max_fact] = mod_pow(fact[max_fact], MOD - 2);
    for i in (1..=max_fact).rev() {
        inv_fact[i - 1] = inv_fact[i] * i as i64 % MOD;
    }

    let mut answer = 0i64;
    let mut slots = 1i64;

    for i in 0..n {
        let remaining = n - i - 1;
        let ai = a[i];

        if remaining == 0 {
            let required = 1 - slots;
            if required >= 0 && required <= ai {
                answer += 1;
                if answer >= MOD {
                    answer -= MOD;
                }
            }
            break;
        }

        // Choose a value x < A_i. The number of pending subtrees afterward is
        // t = slots + x - 1, and it must satisfy 1 <= t <= remaining.
        let lower_t = (slots - 1).max(1);
        let upper_t = (slots + ai - 2).min(remaining as i64);

        if lower_t <= upper_t {
            let k_low = remaining as i64 - upper_t;
            let k_high = remaining as i64 - lower_t;

            let high_sum =
                prefix_forest_sum(remaining, k_high, &fact, &inv_fact);
            let low_sum =
                prefix_forest_sum(remaining, k_low - 1, &fact, &inv_fact);

            answer = (answer + high_sum - low_sum + MOD) % MOD;
        }

        // Continue with the prefix equal to A.
        slots += ai - 1;
        if slots <= 0 {
            break;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", answer).unwrap();
}
