use std::io::{self, Read, Write};

const MOD: u64 = 998_244_353;

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let m: usize = iter.next().unwrap().parse().unwrap();
    let b: Vec<i32> = (0..n)
        .map(|_| iter.next().unwrap().parse().unwrap())
        .collect();

    let unknown_total = b.iter().filter(|&&x| x == -1).count();

    let width = m + 1;
    let mut powers = vec![0u32; (n + 1) * width];

    for base in 0..=m {
        powers[base] = 1;
    }
    for exp in 1..=n {
        for base in 0..=m {
            powers[exp * width + base] =
                (powers[(exp - 1) * width + base] as u64 * base as u64 % MOD) as u32;
        }
    }

    let mut suffix_fixed_max = vec![0usize; n + 1];
    for i in (0..n).rev() {
        suffix_fixed_max[i] = suffix_fixed_max[i + 1];
        if b[i] != -1 {
            suffix_fixed_max[i] = suffix_fixed_max[i].max(b[i] as usize);
        }
    }

    let mut answer = powers[unknown_total * width + m] as u64;
    let mut prefix_unknown = 0usize;
    let mut prefix_fixed_min = m + 1;

    for cut in 1..n {
        if b[cut - 1] == -1 {
            prefix_unknown += 1;
        } else {
            prefix_fixed_min = prefix_fixed_min.min(b[cut - 1] as usize);
        }

        let left_unknown = prefix_unknown;
        let right_unknown = unknown_total - prefix_unknown;
        let right_fixed_max = suffix_fixed_max[cut];
        let upper = prefix_fixed_min - 1;
        let start = right_fixed_max.max(1);

        if start > upper {
            continue;
        }

        let mut ways_for_cut = 0u64;

        for t in start..=upper {
            let right_at_most_t = powers[right_unknown * width + t] as u64;
            let right_at_most_prev = if t - 1 >= right_fixed_max {
                powers[right_unknown * width + (t - 1)] as u64
            } else {
                0
            };

            let right_max_exactly_t =
                (right_at_most_t + MOD - right_at_most_prev) % MOD;
            let left_ways = powers[left_unknown * width + (m - t)] as u64;

            ways_for_cut =
                (ways_for_cut + right_max_exactly_t * left_ways) % MOD;
        }

        answer = (answer + ways_for_cut) % MOD;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
