use std::io::{self, Read, Write};

const MOD: i64 = 998_244_353;

fn solve(n: usize, a: Vec<usize>, b: Vec<i64>) -> i64 {
    let mut owner = vec![usize::MAX; n];

    for i in 0..n {
        let pair = (a[i] - 1) / 2;
        if pair >= n || owner[pair] != usize::MAX {
            return 0;
        }
        owner[pair] = i;
    }

    if owner.iter().any(|&x| x == usize::MAX) {
        return 0;
    }

    let mut next = vec![None; n];
    let mut indegree = vec![0usize; n];

    for j in 0..n {
        if b[j] == -1 {
            continue;
        }

        let rank = b[j] as usize;
        if rank == 0 || rank > 2 * n {
            return 0;
        }

        let pair = (rank - 1) / 2;
        let p = owner[pair];
        let complement = if a[p] % 2 == 1 {
            a[p] + 1
        } else {
            a[p] - 1
        };

        if rank != complement || next[p].is_some() || indegree[j] != 0 {
            return 0;
        }

        next[p] = Some(j);
        indegree[j] = 1;
    }

    let mut visited = vec![false; n];
    let mut odd_components = 0usize;
    let mut even_components = 0usize;
    let mut mixed_components = 0usize;

    // Components with an indegree-zero vertex are directed paths.
    for start in 0..n {
        if indegree[start] != 0 || visited[start] {
            continue;
        }

        let mut has_odd = false;
        let mut has_even = false;
        let mut current = start;

        loop {
            if visited[current] {
                break;
            }
            visited[current] = true;

            if a[current] % 2 == 1 {
                has_odd = true;
            } else {
                has_even = true;
            }

            match next[current] {
                Some(v) => current = v,
                None => break,
            }
        }

        match (has_odd, has_even) {
            (true, true) => mixed_components += 1,
            (true, false) => odd_components += 1,
            (false, true) => even_components += 1,
            _ => return 0,
        }
    }

    // Every remaining component is an already completed directed cycle.
    for start in 0..n {
        if visited[start] {
            continue;
        }

        let mut has_odd = false;
        let mut has_even = false;
        let mut current = start;

        loop {
            if visited[current] {
                break;
            }
            visited[current] = true;

            if a[current] % 2 == 1 {
                has_odd = true;
            } else {
                has_even = true;
            }

            match next[current] {
                Some(v) => current = v,
                None => return 0,
            }
        }

        if !(has_odd && has_even) {
            return 0;
        }
    }

    let component_count = odd_components + even_components + mixed_components;
    if component_count == 0 {
        return 1;
    }

    let mut factorial = vec![1i64; component_count + 1];
    for i in 1..=component_count {
        factorial[i] = factorial[i - 1] * i as i64 % MOD;
    }

    let homogeneous = (odd_components + even_components) as i64;
    let mut answer = factorial[component_count];
    answer = (answer - homogeneous * factorial[component_count - 1]) % MOD;

    if component_count >= 2 {
        let add = (odd_components as i64)
            * (even_components as i64)
            % MOD
            * factorial[component_count - 2]
            % MOD;
        answer = (answer + add) % MOD;
    }

    if answer < 0 {
        answer += MOD;
    }
    answer
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();

    let mut a = Vec::with_capacity(n);
    for _ in 0..n {
        a.push(iter.next().unwrap().parse::<usize>().unwrap());
    }

    let mut b = Vec::with_capacity(n);
    for _ in 0..n {
        b.push(iter.next().unwrap().parse::<i64>().unwrap());
    }

    let answer = solve(n, a, b);

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
