use std::io::{self, Read, Write};

fn required_sequence(
    n: usize,
    x: usize,
    balls: &[usize],
    perm: &[usize],
) -> Option<Vec<usize>> {
    let mut inverse = vec![0usize; n];
    for i in 0..n {
        inverse[perm[i]] = i;
    }

    let mut distance = vec![usize::MAX; n];
    distance[x] = 0;

    // cycle_nodes[d - 1] is the vertex at distance d from X.
    let mut cycle_nodes = Vec::new();
    let mut current = inverse[x];
    let mut d = 1usize;

    while current != x {
        distance[current] = d;
        cycle_nodes.push(current);
        current = inverse[current];
        d += 1;
    }

    let mut max_distance = 0usize;
    for i in 0..n {
        if balls[i] > 0 {
            if distance[i] == usize::MAX {
                return None;
            }
            max_distance = max_distance.max(distance[i]);
        }
    }

    let mut sequence = Vec::with_capacity(max_distance);
    for i in (0..max_distance).rev() {
        sequence.push(cycle_nodes[i]);
    }
    Some(sequence)
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let x: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;

    let a: Vec<usize> = (0..n)
        .map(|_| it.next().unwrap().parse().unwrap())
        .collect();
    let b: Vec<usize> = (0..n)
        .map(|_| it.next().unwrap().parse().unwrap())
        .collect();
    let p: Vec<usize> = (0..n)
        .map(|_| it.next().unwrap().parse::<usize>().unwrap() - 1)
        .collect();
    let q: Vec<usize> = (0..n)
        .map(|_| it.next().unwrap().parse::<usize>().unwrap() - 1)
        .collect();

    let red = required_sequence(n, x, &a, &p);
    let blue = required_sequence(n, x, &b, &q);

    let answer = match (red, blue) {
        (Some(red), Some(blue)) => {
            let mut blue_position = vec![usize::MAX; n];
            for (i, &vertex) in blue.iter().enumerate() {
                blue_position[vertex] = i;
            }

            // Since both sequences contain distinct vertices, their LCS is
            // the LIS of blue positions in red order.
            let mut lis: Vec<usize> = Vec::new();
            for &vertex in &red {
                let pos = blue_position[vertex];
                if pos == usize::MAX {
                    continue;
                }

                let mut low = 0usize;
                let mut high = lis.len();
                while low < high {
                    let mid = (low + high) / 2;
                    if lis[mid] < pos {
                        low = mid + 1;
                    } else {
                        high = mid;
                    }
                }

                if low == lis.len() {
                    lis.push(pos);
                } else {
                    lis[low] = pos;
                }
            }

            (red.len() + blue.len() - lis.len()) as i64
        }
        _ => -1,
    };

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
